  'Oito2BackButton': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'An [Oito2IconButton] that goes back: a chevron pointing to the start\nside, with the localized "Back" tooltip. By default it pops the\nclosest [Navigator] route.', signature: '', constructors: [ApiConstructor(name: 'Oito2BackButton', doc: 'Creates a back button.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'onPressed', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the button is pressed; defaults to popping the current\nroute.'), ApiParameter(name: 'tooltip', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The tooltip; defaults to the localized "Back".'), ApiParameter(name: 'enabled', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the button responds to presses; when false it is shown\ndisabled and neither calls [onPressed] nor pops.')])], properties: [], methods: [], values: []),
  'Oito2Banner': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A card-like clickable surface for promoting content, such as an app in\na store grid. Hovering strengthens its border when it has an [onTap].\n\n[Oito2Banner.tile] lays out an icon, a title and a subtitle. [onHover]\ntells when the pointer enters and leaves, so the content can change\non hover, and [tint] washes the background with a color.', signature: '', constructors: [ApiConstructor(name: 'Oito2Banner', doc: 'Creates a banner around [child].', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The content.'), ApiParameter(name: 'onTap', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the banner is activated.'), ApiParameter(name: 'onHover', type: 'ValueChanged<bool>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with true when the pointer enters the banner and false when\nit leaves.'), ApiParameter(name: 'selected', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the banner is selected.'), ApiParameter(name: 'color', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The background; defaults to the scheme surface.'), ApiParameter(name: 'tint', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A color blended lightly over the background.'), ApiParameter(name: 'padding', type: 'EdgeInsetsGeometry', isRequired: false, isNamed: true, defaultValue: 'const EdgeInsets.all(Oito2Spacing.lg)', doc: 'Space around the content.')]), ApiConstructor(name: 'Oito2Banner.tile', doc: 'Creates a banner with [icon] before a [title] and an optional\n[subtitle].', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'key', type: 'Key?', isRequired: false, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'title', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'subtitle', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'icon', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'onTap', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'onHover', type: 'ValueChanged<bool>?', isRequired: false, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'selected', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: ''), ApiParameter(name: 'color', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'tint', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'padding', type: 'EdgeInsetsGeometry', isRequired: false, isNamed: true, defaultValue: 'const EdgeInsets.all(Oito2Spacing.lg)', doc: '')])], properties: [], methods: [], values: []),
  'Oito2BorderContainer': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A container with a thin `outlineVariant` border, the large radius and\nthe scheme surface as background.\n\nIt paints on a [Material], so ink effects of widgets inside it, such as\n[ListTile] hover and splashes, show on its surface.', signature: '', constructors: [ApiConstructor(name: 'Oito2BorderContainer', doc: 'Creates a bordered container.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'child', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The content.'), ApiParameter(name: 'padding', type: 'EdgeInsetsGeometry?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Space inside the border.'), ApiParameter(name: 'margin', type: 'EdgeInsetsGeometry?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Space outside the border.'), ApiParameter(name: 'width', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A fixed width; the container sizes to its content when null.'), ApiParameter(name: 'height', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A fixed height; the container sizes to its content when null.'), ApiParameter(name: 'color', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The background; defaults to the scheme surface.'), ApiParameter(name: 'borderColor', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The border color; defaults to the scheme `outlineVariant`.'), ApiParameter(name: 'borderRadius', type: 'BorderRadius', isRequired: false, isNamed: true, defaultValue: 'Oito2Radius.largeAll', doc: 'The corner radius.'), ApiParameter(name: 'clipBehavior', type: 'Clip', isRequired: false, isNamed: true, defaultValue: 'Clip.antiAlias', doc: 'How the content is clipped to the rounded border.')]), ApiConstructor(name: 'Oito2BorderContainer.tinted', doc: 'Creates a container tinted with [tint]: a [tint] border over a fill\no