  'Oito2Breadcrumb': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A path bar: the [items] from the root to the current location, with\nchevron separators that point toward the end of the reading direction.\n\nEvery segment but the last is a button that calls [onSelected] with its\nindex; the last one is the current location and reads as such to\nassistive technologies. When the segments don\'t fit the width, the\nones after the first collapse into a "…" button, as few as needed, so\nthe last segments stay visible; the button opens a menu with the\nhidden segments. When even the first and the last don\'t fit, the first\ncollapses too and the last one is cut with an ellipsis.\n\nWith [onSubmitted], the bar can turn into a text field holding [path]:\nthrough the edit button at its end, or a click on its empty area.\nEnter submits the text to [onSubmitted] and Escape, or moving the focus\naway, cancels. Left and Right move the focus between the segment\nbuttons.', signature: '', constructors: [ApiConstructor(name: 'Oito2Breadcrumb', doc: 'Creates a breadcrumb.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'items', type: 'List<Oito2BreadcrumbItem<T>>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The segments, from the root to the current location.'), ApiParameter(name: 'onSelected', type: 'ValueChanged<int>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the index of an activated segment; null makes the\nsegments plain text.'), ApiParameter(name: 'onSubmitted', type: 'ValueChanged<String>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the text submitted in the edit mode; null turns the\nedit mode off.'), ApiParameter(name: 'path', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The text of the edit field; defaults to the labels of [items] joined\nby [pathSeparator].'), ApiParameter(name: 'pathSeparator', type: 'String', isRequired: false, isNamed: true, defaultValue: '\'/\'', doc: 'The separator that joins the labels into the default [path].')])], properties: [ApiMember(name: 'separatorWidth', signature: 'static double', doc: 'The width of the chevron between two segments.'), ApiMember(name: 'buttonWidth', signature: 'static double', doc: 'The width of the "…" and edit buttons, before any padding to the\ntouch target.')], methods: [ApiMember(name: 'collapse', signature: 'static collapse(List<double> widths, double maxWidth, double separatorWidth, double buttonWidth, double minSegmentWidth, double editWidth) → ({int collapsedEnd, int collapsedStart, bool lastTruncated})', doc: 'Returns which segments a breadcrumb collapses into its "…" button\nwhen its segments, [widths] wide from the root to the current\nlocation, are laid out in [maxWidth].\n\nEvery segment but the last is at least [minSegmentWidth] wide, the\nsegments are [separatorWidth] apart, the "…" button is [buttonWidth]\nwide and [editWidth] is kept free at the end for the edit button and\nits gap. When every segment fits, none collapses. Otherwise the\nsegments after the first collapse, from the second on and as few as\nneeded, so the last ones stay; when even the first and the last\ndon\'t fit with the button, every segment but the last collapses.\n\nReturns the collapsed range of indexes, from `collapsedStart`\ninclusive to `collapsedEnd` exclusive and empty when none collapses,\nand `lastTruncated`, whether the row is still wider than the space,\nso the last segment is cut with an ellipsis.')], values: []),
  'Oito2BreadcrumbItem': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A segment of an [Oito2Breadcrumb], such as a folder of a path.', signature: '', constructors: [ApiConstructor(name: 'Oito2BreadcrumbItem', doc: 'Creates a breadcrumb segment named [label].', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'label', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The segment name.'), ApiParameter(name: 'icon', type: 'IconData?', isRequired: false, isNamed: true, defaultValue: '', doc: 'An icon before [label], such as a drive or home icon.'), ApiParameter(name: 'value', type: 'T?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The value the segment stands for, such as a folder path.')])], properties: [], methods: [], values: []),
  'Oito2BusyButton': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Shows a busy state on any button, such as a [FilledButton] that\nstarted a call to a server, without changing its look or width.\n\nWhile [busy], the button keeps its colors and focus but ignores\nclicks, taps, the activation keys (Enter, Space and Select) and the\ntap action of assistive technologies, which read it with "Loading" as\nits value; the pointer shows the progress cursor over it. Put an\n[Oito2BusyLabel] around the button\'s icon or label to show a spinner\nin its place.\n\n```dart\nOito2BusyButton(\n  busy: saving,\n  child: FilledButton.icon(\n    onPressed: save,\n    icon: const Oito2BusyLabel(child: Icon(LucideIcons.save)),\n    label: const Text(\'Save\'),\n  ),\n)\n```', signature: '', constructors: [ApiConstructor(name: 'Oito2BusyButton', doc: 'Creates a busy button wrapper.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'busy', type: 'bool', isRequired: true, isNamed: true, defaultValue: '', doc: 'Whether the action of the button is running.'), ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The button.')])], properties: [], methods: [ApiMember(name: 'isBusy', signature: 'static isBusy(BuildContext context) → bool', doc: 'Returns whether the closest [Oito2BusyButton] around [context] is\nbusy, or false when there is none.')], values: []),
  'Oito2BusyLabel': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'The icon or label of a button that a spinner replaces while the\nclosest [Oito2BusyButton] is busy.\n\nThe [child] stays laid out, hidden, so the button keeps its size, and\nits text is still read by assistive technologies. The spinner takes\nthe color of the button\'s icons and stands still when animations are\ndisabled.', signature: '', constructors: [ApiConstructor(name: 'Oito2BusyLabel', doc: 'Creates a busy label.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The icon or label shown while not busy.'), ApiParameter(name: 'busy', type: 'bool?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Whether the spinner shows; defaults to the state of the closest\n[Oito2BusyButton].')])], properties: [], methods: [], values: []),
  'Oito2ByteUnits': ApiEntry(kind: 'enum', package: 'oito2_ui', doc: 'The units of [Oito2Format.bytes].', signature: '', constructors: [], properties: [], methods: [], values: [ApiMember(name: 'si', signature: '', doc: 'Powers of 1000: B, kB, MB, GB, TB, PB.'), ApiMember(name: 'iec', signature: '', doc: 'Powers of 1024: B, KiB, MiB, GiB, TiB, PiB.')]),
  'Oito2Calendar': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A month grid that picks a date, or a range of dates when\n[onRangeSelected] is set.\n\nThe header changes the month. The grid takes the focus as a whole: the\narrow keys move by a day or a week, Home and End to the start and end\nof the week, Page Up and Page Down by a month (a year with Shift), and\nEnter or Space picks the focused day. A range takes two picks; the\nsecond may come before the first. Days outside [firstDate] and\n[lastDate], or refused by [selectableDayPredicate], can\'t be picked.\nWeek numbers follow ISO 8601.', signature: '', constructors: [ApiConstructor(name: 'Oito2Calendar', doc: 'Creates a calendar.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'firstDate', type: 'DateTime', isRequired: true, isNamed: true, defaultValue: '', doc: 'The earliest date that can be picked.'), ApiParameter(name: 'lastDate', type: 'DateTime', isRequired: true, isNamed: true, defaultValue: '', doc: 'The latest date that can be picked.'), ApiParameter(name: 'selectedDate', type: 'DateTime?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The picked date, in single mode.'), ApiParameter(name: 'onDateSelected', type: 'ValueChanged<DateTime>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with a picked date, in single mode.'), ApiParameter(name: 'selectedRange', type: 'DateTimeRange<DateTime>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The picked range, in range mode.'), ApiParameter(name: 'onRangeSelected', type: 'ValueChanged<DateTimeRange<DateTime>>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with a completed range; setting it turns on range mode.'), ApiParameter(name: 'initialMonth', type: 'DateTime?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The month shown first; defaults to the month of the selection or of\ntoday, kept within [firstDate] and [lastDate].'), ApiParameter(name: 'selectableDayPredicate', type: 'SelectableDayPredicate?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Decides which days between [firstDate] and [lastDate] can be picked;\nevery day can when null.'), ApiParameter(name: 'showWeekNumbers', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether a week number column shows.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the grid takes the focus when shown.'), ApiParameter(name: 'currentDate', type: 'DateTime?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The day marked as today; the current date by default.')])], properties: [], methods: [], values: []),
  'Oito2Carousel': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A row of pages shown one at a time, with previous and next buttons and\nan [Oito2PageIndicator] below.\n\nPages change by the buttons, the dots, the Left and Right arrow keys\n(swapped in right-to-left text) while the carousel itself has focus (it\ntakes focus as a whole and shows the focus ring; arrows pressed while a\nbutton or page content has focus are left to them), or a swipe (also with a mouse). The buttons and arrows\nwrap around when [loop] is true, jumping straight to the other end.\nAutomatic scrolling comes from an [Oito2CarouselController].', signature: '', constructors: [ApiConstructor(name: 'Oito2Carousel', doc: 'Creates a carousel.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'children', type: 'List<Widget>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The pages.'), ApiParameter(name: 'controller', type: 'Oito2CarouselController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The controller; one without automatic scrolling is created when null.'), ApiParameter(name: 'height', type: 'double', isRequired: false, isNamed: true, defaultValue: '240', doc: 'The height of the pages.'), ApiParameter(name: 'navigationControls', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether previous and next buttons sit over the pages.'), ApiParameter(name: 'pageIndicator', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether an [Oito2PageIndicator] sits below the pages.'), ApiParameter(name: 'loop', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether going past the last page returns to the first, and back.'), ApiParameter(name: 'onPageChanged', type: 'ValueChanged<int>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the new page index.')])], properties: [], methods: [], values: []),
  'Oito2CarouselController': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Controls an [Oito2Carousel]: the current page, page changes and\nautomatic scrolling.\n\nWith [autoScroll], the carousel moves to the next page every\n[autoScrollInterval], wrapping to the first, while no pointer hovers it\nand nothing inside it has focus. It never scrolls by itself when\nanimations are disabled.', signature: '', constructors: [ApiConstructor(name: 'Oito2CarouselController', doc: 'Creates a carousel controller.', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'initialPage', type: 'int', isRequired: false, isNamed: true, defaultValue: '0', doc: ''), ApiParameter(name: 'viewportFraction', type: 'double', isRequired: false, isNamed: true, defaultValue: '1.0', doc: ''), ApiParameter(name: 'autoScroll', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the carousel advances by itself.'), ApiParameter(name: 'autoScrollInterval', type: 'Duration', isRequired: false, isNamed: true, defaultValue: 'const Duration(seconds: 4)', doc: 'The time each page stays before the next one when [autoScroll].'), ApiParameter(name: 'animationDuration', type: 'Duration', isRequired: false, isNamed: true, defaultValue: 'const Duration(milliseconds: 400)', doc: 'The duration of page changes.'), ApiParameter(name: 'animationCurve', type: 'Curve', isRequired: false, isNamed: true, defaultValue: 'Curves.easeInOutCubic', doc: 'The curve of page changes.')])], properties: [ApiMember(name: 'currentPage', signature: 'int', doc: 'The current page, rounded; the initial page while no carousel is\nattached.')], methods: [ApiMember(name: 'goTo', signature: 'goTo(int index, bool animate) → Future<void>', doc: 'Animates to page [index], or jumps there when [animate] is false.\n\nThe returned future completes when the change ends; it does nothing\nwhile no carousel is attached.')], values: []),
