  'Oito2ColorRoles': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'The handful of role colors a color theme family defines, from which\n[Oito2ColorTheme.fromRoles] derives a complete oito2 scheme.\n\nThe roles follow the vocabulary most theme families publish: a page\n[background], a [card] surface, a [secondary] surface, a [border], the\ntext colors and the accents. Values are taken as given; contrast\nadjustments happen in [Oito2ColorTheme.fromRoles].', signature: '', constructors: [ApiConstructor(name: 'Oito2ColorRoles', doc: 'Creates the role colors of a scheme.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'brightness', type: 'Brightness', isRequired: true, isNamed: true, defaultValue: '', doc: 'Whether the scheme is light or dark.'), ApiParameter(name: 'background', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The page background.'), ApiParameter(name: 'card', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The main surface of cards, panes and fields.'), ApiParameter(name: 'foreground', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The body text color.'), ApiParameter(name: 'primary', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The signature accent, used as the primary fill.'), ApiParameter(name: 'secondary', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'A surface one step above [card], such as a selected row.'), ApiParameter(name: 'mutedForeground', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Secondary text, such as captions and placeholders.'), ApiParameter(name: 'destructive', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The color of errors and destructive actions.'), ApiParameter(name: 'border', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Borders and dividers.'), ApiParameter(name: 'success', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The color of success states.'), ApiParameter(name: 'warning', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The color of warning states.'), ApiParameter(name: 'info', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The color of informational states.'), ApiParameter(name: 'syntax', type: 'Oito2SyntaxPalette', isRequired: true, isNamed: true, defaultValue: '', doc: 'The syntax highlighting colors.')])], properties: [], methods: [], values: []),
  'Oito2ColorScheme': ApiEntry(kind: 'abstract class', package: 'oito2_ui', doc: 'Material [ColorScheme]s of the oito2 schemes.\n\nShortcuts to [Oito2ColorTheme.colorScheme]; use [Oito2ColorTheme] when\nthe semantic, chrome or syntax colors are needed too.', signature: '', constructors: [ApiConstructor(name: 'Oito2ColorScheme', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [], methods: [ApiMember(name: 'light', signature: 'static light(Color? accent, bool highContrast) → ColorScheme', doc: 'The light oito2 base scheme with [accent] as the primary hue.'), ApiMember(name: 'dark', signature: 'static dark(Color? accent, bool highContrast) → ColorScheme', doc: 'The dark oito2 base scheme with [accent] as the primary hue.')], values: []),
  'Oito2ColorTheme': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'The complete, resolved colors of one oito2 scheme: the Material\n[colorScheme] plus the oito2 [semantic], [chrome] and [syntax] colors.\n\nBuild it with [Oito2ColorTheme.light] or [Oito2ColorTheme.dark] for the\noito2 base scheme, or with [Oito2ColorTheme.fromRoles] for any other\ncolor theme family, such as the presets of `oito2_ui_themes` or an\napp\'s own brand colors.\n\nText roles are guaranteed to reach WCAG AA: `onSurface`,\n`onSurfaceVariant` and every [semantic] and [syntax] color reach\n4.5:1 against every surface of the scheme and against [background], and\n`outline` reaches 3:1. With high contrast the targets rise to 7:1 and\n4.5:1.', signature: '', constructors: [ApiConstructor(name: 'Oito2ColorTheme', doc: 'Creates a color theme from resolved values.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'colorScheme', type: 'ColorScheme', isRequired: true, isNamed: true, defaultValue: '', doc: 'The Material color scheme.'), ApiParameter(name: 'background', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The page background, used as the scaffold background.'), ApiParameter(name: 'semantic', type: 'Oito2SemanticColors', isRequired: true, isNamed: true, defaultValue: '', doc: 'Text-safe accent and status colors.'), ApiParameter(name: 'chrome', type: 'Oito2ChromeColors', isRequired: true, isNamed: true, defaultValue: '', doc: 'Structural chrome colors.'), ApiParameter(name: 'syntax', type: 'Oito2SyntaxPalette', isRequired: true, isNamed: true, defaultValue: '', doc: 'Syntax highlighting colors.'), ApiParameter(name: 'highContrast', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether this theme uses the high-contrast targets.')]), ApiConstructor(name: 'Oito2ColorTheme.light', doc: 'The light oito2 base scheme: GTK-style neutrals with [accent] as the\nprimary hue.\n\n[accent] defaults to [Oito2AccentColor.fallback]. The primary fill\nkeeps white text: its lightness is lowered only as far as needed for\nwhite to reach 4.5:1 (7:1 with [highContrast]).', isConst: false, isFactory: true, parameters: [ApiParameter(name: 'accent', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'highContrast', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: '')]), ApiConstructor(name: 'Oito2ColorTheme.dark', doc: 'The dark oito2 base scheme: GTK-style neutrals with [accent] as the\nprimary hue.\n\nSee [Oito2ColorTheme.light] for how [accent] and [highContrast] apply.', isConst: false, isFactory: true, parameters: [ApiParameter(name: 'accent', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'highContrast', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: '')]), ApiConstructor(name: 'Oito2ColorTheme.fromRoles', doc: 'A scheme derived from the role colors of a theme family.\n\nThe primary fill keeps [Oito2ColorRoles.primary] as given, with black\nor white text, whichever contrasts more. The surface ladder runs from\nthe lower of the background and the card up to the secondary surface:\n\n- `surfaceContainerLowest` is whichever of `background` and `card`\n  sits lower (darker in a dark scheme, lighter in a light one);\n- `surfaceContainerLow` is halfway from it to `card`;\n- `surfaceContainer` and `surfaceContainerHigh` are one third and two\n  thirds of the way from `card` to `secondary`, and\n  `surfaceContainerHighest` is `secondary`;\n- the title bar is `surfaceContainer`;\n- `outline` is `border` mixed 35% toward `foreground`, and\n  `outlineVariant` is `border`.\n\nText, outline, semantic and syntax colors are then adjusted to reach\nWCAG AA against every surface, as for the base scheme, or AAA with\n[highContrast].', isConst: false, isFactory: true, parameters: [ApiParameter(name: 'roles', type: 'Oito2ColorRoles', isRequired: true, isNamed: false, defaultValue: '', doc: ''), ApiParameter(name: 'highContrast', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: '')])], properties: [ApiMember(name: 'brightness', signature: 'Brightness', doc: 'The brightness of this theme.'), ApiMember(name: 'surfaces', signature: 'List<Color>', doc: 'Every surface of this theme: [background], the chrome surfaces and\nall `ColorScheme` surface roles.')], methods: [], values: []),
  'Oito2ColumnWidth': ApiEntry(kind: 'abstract class', package: 'oito2_ui', doc: 'How wide an [Oito2TableColumn] is: a fixed width, or a share of the\nspace the fixed columns leave.', signature: '', constructors: [ApiConstructor(name: 'Oito2ColumnWidth', doc: '', isConst: true, isFactory: false, parameters: []), ApiConstructor(name: 'Oito2ColumnWidth.fixed', doc: 'A column [width] logical pixels wide.', isConst: true, isFactory: true, parameters: [ApiParameter(name: 'width', type: 'double', isRequired: true, isNamed: false, defaultValue: '', doc: '')]), ApiConstructor(name: 'Oito2ColumnWidth.flex', doc: 'A column that takes [flex] shares of the space the fixed columns\nleave, and at least [min] logical pixels.', isConst: true, isFactory: true, parameters: [ApiParameter(name: 'flex', type: 'double', isRequired: true, isNamed: false, defaultValue: '', doc: ''), ApiParameter(name: 'min', type: 'double', isRequired: false, isNamed: true, defaultValue: '', doc: '')])], properties: [ApiMember(name: 'resizeMin', signature: 'double', doc: 'The narrowest a resize can make the column: [min] for a flexible\ncolumn, and never less than [Oito2TableColumn.minResizeWidth].')], methods: [], values: []),
  'Oito2Command': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'An action the user can run by a keyboard shortcut or from the command\npalette.', signature: '', constructors: [ApiConstructor(name: 'Oito2Command', doc: 'Creates a command.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'id', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'A unique identifier; an inner [Oito2Commands] scope overrides an\nouter command with the same id.'), ApiParameter(name: 'label', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The name shown in the command palette.'), ApiParameter(name: 'onInvoke', type: 'VoidCallback', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called when the command runs, from its shortcut or the command\npalette.'), ApiParameter(name: 'shortcut', type: 'Oito2Shortcut?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The keyboard shortcut, if any; the command palette shows it.'), ApiParameter(name: 'alternateShortcuts', type: 'List<Oito2Shortcut>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: 'More shortcuts that also run the command; the shortcuts help lists\nthem after [shortcut].'), ApiParameter(name: 'description', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A longer explanation shown in the command palette.'), ApiParameter(name: 'group', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The palette group, such as "Navigation" or "View".'), ApiParameter(name: 'icon', type: 'IconData?', isRequired: false, isNamed: true, defaultValue: '', doc: 'An icon shown in the command palette.'), ApiParameter(name: 'keywords', type: 'List<String>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: 'Extra words the palette search matches.'), ApiParameter(name: 'enabled', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the command can run now; disabled commands neither react to\ntheir shortcuts nor appear in the command palette, and the shortcuts\nhelp shows them dimmed.')]), ApiConstructor(name: 'Oito2Command.shortcutsHelp', doc: 'Creates the command that opens the keyboard shortcuts help, bound to\n[shortcutsHelpShortcut] (F1) and [shortcutsHelpAlternateShortcut]\n(the primary modifier with Shift and `/`, which reads as Ctrl+? or\n⌘? on layouts that type `?` with Shift and the `/` key).\n\nNothing is bound until the app adds this command to an\n[Oito2Commands] scope. [onInvoke] usually calls\n`showOito2ShortcutsHelp`; [label] is usually the localized\n[Oito2Localizations.keyboardShortcuts]. The command shows in the\ncommand palette and in the help itself.', isConst: false, isFactory: true, parameters: [ApiParameter(name: 'label', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'onInvoke', type: 'VoidCallback', isRequired: true, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'id', type: 'String', isRequired: false, isNamed: true, defaultValue: 'shortcutsHelpId', doc: ''), ApiParameter(name: 'description', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'group', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'icon', type: 'IconData?', isRequired: false, isNamed: true, defaultValue: 'LucideIcons.keyboard', doc: ''), ApiParameter(name: 'keywords', type: 'List<String>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: ''), ApiParameter(name: 'enabled', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: '')])], properties: [ApiMember(name: 'shortcutsHelpId', signature: 'static String', doc: 'The default id of [Oito2Command.shortcutsHelp].'), ApiMember(name: 'shortcutsHelpShortcut', signature: 'static Oito2Shortcut', doc: 'The main shortcut of [Oito2Command.shortcutsHelp]: F1.'), ApiMember(name: 'shortcutsHelpAlternateShortcut', signature: 'static Oito2Shortcut', doc: 'The second shortcut of [Oito2Command.shortcutsHelp]: the primary\nmodifier with Shift and `/` (Ctrl+Shift+/ or ⇧⌘/), which is Ctrl+? or\n⌘? on layouts that type `?` with Shift and the `/` key, such as US\nEnglish and Brazilian ABNT2. Shortcuts match the key, not the\ncharacter it types, so on layouts where `?` sits elsewhere (such as\nGerman) only F1 opens the help.'), ApiMember(name: 'shortcuts', signature: 'List<Oito2Shortcut>', doc: 'Returns [shortcut], when set, followed by [alternateShortcuts].')], methods: [], values: []),
  'Oito2Commands': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Registers [commands] for the widgets below it: while keyboard focus is\ninside [child], their shortcuts run them, and the command palette lists\nthem.\n\nScopes nest: a shortcut first matches the commands of the innermost\nscope around the focus, then those of the enclosing scopes, and an\ninner command replaces an outer one with the same [Oito2Command.id].\nThe innermost scope matches the shortcuts of the whole chain at once,\nso an inner sequence such as `G H` doesn\'t hide an outer `G` or `G J`.\nSequences such as `G H` wait up to [sequenceTimeout] between chords.\nShortcuts without Control, Alt, Command or the primary modifier (such\nas `G H` or `Shift+/`) don\'t run while a text field has focus, so they\ndon\'t steal typing; those that start with a function key (F1 to F24)\nstill run, since function keys don\'t type text.', signature: '', constructors: [ApiConstructor(name: 'Oito2Commands', doc: 'Creates a command scope.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'commands', type: 'List<Oito2Command>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The commands of this scope.'), ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The widgets the commands apply to.'), ApiParameter(name: 'sequenceTimeout', type: 'Duration', isRequired: false, isNamed: true, defaultValue: 'const Duration(seconds: 1)', doc: 'The longest wait between the chords of a sequence.')])], properties: [], methods: [ApiMember(name: 'availableAt', signature: 'static availableAt(BuildContext context, bool includeDisabled) → List<Oito2Command>', doc: 'Returns the enabled commands available at [context]: those of every\nenclosing scope, the innermost first, with inner commands replacing\nouter ones of the same id.\n\nWhen [includeDisabled] is true, the disabled commands are returned\ntoo, and a disabled inner command replaces an outer one of the same\nid, as it does for shortcuts.'), ApiMember(name: 'conflicts', signature: 'static conflicts(List<Oito2Command> commands, TargetPlatform? platform) → List<(Oito2Command, Oito2Command)>', doc: 'Returns the pairs of [commands] whose shortcuts clash on [platform]\n(the current platform by default): the same shortcut, or one that is\na prefix of another (the longer one could never run). Every shortcut\nof a command counts, its [Oito2Command.alternateShortcuts] included.')], values: []),
  'Oito2ContextMenuController': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Opens and closes the menu of the [Oito2ContextMenuRegion] it is given\nto.', signature: '', constructors: [ApiConstructor(name: 'Oito2ContextMenuController', doc: 'Creates a controller that is not attached to a region yet.', isConst: false, isFactory: false, parameters: [])], properties: [ApiMember(name: 'isOpen', signature: 'bool', doc: 'Whether the menu is open.')], methods: [ApiMember(name: 'open', signature: 'open(Offset? globalPosition, bool? focusFirstItem) → void', doc: 'Opens the menu at [globalPosition], or over the center of the region\nwhen null. Does nothing when no enabled region uses this controller.\n\nWith [focusFirstItem] true the focus moves to the first item that can\ntake it, as when a key press asked for the menu; it defaults to\nwhether [globalPosition] is null.'), ApiMember(name: 'close', signature: 'close() → void', doc: 'Closes the menu when it is open.')], values: []),
  'Oito2ContextMenuRegion': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Opens a menu of [menuChildren] over [child] on a secondary click, a\nlong press, Shift+F10 or the menu key.\n\nThe menu is a `MenuAnchor`, so [menuChildren] are `MenuItemButton`s,\n`SubmenuButton`s for nested menus, `Oito2CheckedMenuItem`s and\ndividers. It opens where the pointer is, or over the center of\n[child] from the keyboard, which needs the focus inside [child] and\nmoves it to the first item that can take it. On\nthe web, the browser\'s own menu is turned off while the pointer is\nover [child]. A [controller] opens the menu from code, such as at the\nrow an `Oito2TreeView.onContextMenu` reports.', signature: '', constructors: [ApiConstructor(name: 'Oito2ContextMenuRegion', doc: 'Creates a context menu region.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The widget the menu belongs to.'), ApiParameter(name: 'menuChildren', type: 'List<Widget>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The menu items.'), ApiParameter(name: 'enabled', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the menu can open; when false, the browser\'s own menu stays\navailable on the web.'), ApiParameter(name: 'onOpen', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the menu opens.'), ApiParameter(name: 'onClose', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the menu closes.'), ApiParameter(name: 'controller', type: 'Oito2ContextMenuController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Opens and closes the menu from code.')])], properties: [], methods: [], values: []),
  'Oito2Contrast': ApiEntry(kind: 'abstract class', package: 'oito2_ui', doc: 'Color contrast helpers based on WCAG 2.2 relative luminance.', signature: '', constructors: [ApiConstructor(name: 'Oito2Contrast', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [ApiMember(name: 'textAA', signature: 'static double', doc: 'Minimum contrast ratio for normal text at WCAG level AA.'), ApiMember(name: 'nonTextAA', signature: 'static double', doc: 'Minimum contrast ratio for large text and for user interface\ncomponents and graphics at WCAG level AA.'), ApiMember(name: 'textAAA', signature: 'static double', doc: 'Minimum contrast ratio for normal text at WCAG level AAA.')], methods: [ApiMember(name: 'ratio', signature: 'static ratio(Color a, Color b) → double', doc: 'Returns the WCAG contrast ratio between [a] and [b], from 1 (no\ncontrast) to 21 (black on white). The alpha channel is ignored.'), ApiMember(name: 'foregroundFor', signature: 'static foregroundFor(Color background) → Color', doc: 'Returns black or white, whichever has the higher contrast ratio\nagainst [background].'), ApiMember(name: 'minRatio', signature: 'static minRatio(Color color, Iterable<Color> backgrounds) → double', doc: 'Returns the lowest contrast ratio between [color] and any of\n[backgrounds], or 21 when [backgrounds] is empty.'), ApiMember(name: 'ensure', signature: 'static ensure(Color color, Iterable<Color> backgrounds, double target) → Color', doc: 'Returns the color closest to [color] that reaches [target] contrast\nagainst every color in [backgrounds].\n\nKeeps hue, saturation and alpha and moves only the HSL lightness,\nsearching in steps of 0.005, darker before lighter at each distance,\nand returning the first lightness that satisfies [target]. Returns\n[color] unchanged when it already satisfies [target] or when\n[backgrounds] is empty. When no lightness satisfies it, returns black\nor white, whichever reaches the higher minimum ratio.')], values: []),
  'Oito2ControlAffinity': ApiEntry(kind: 'enum', package: 'oito2_ui', doc: 'Where the control of a toggle list tile sits.', signature: '', constructors: [], properties: [], methods: [], values: [ApiMember(name: 'leading', signature: '', doc: 'Before the title.'), ApiMember(name: 'trailing', signature: '', doc: 'After the title.'), ApiMember(name: 'platform', signature: '', doc: 'The usual side of the control: leading for check boxes and radios,\ntrailing for switches.')]),
  'Oito2CopyButton': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'An icon button that copies [text] to the clipboard.\n\nAfter a copy the icon turns into a check mark and the tooltip into\n"Copied" for [feedbackDuration], and assistive technologies hear the\nchange. When the platform refuses the copy, such as a browser without\nclipboard permission, the button shows a cross and "Couldn\'t copy"\ninstead, and [onError] receives the error.', signature: '', constructors: [ApiConstructor(name: 'Oito2CopyButton', doc: 'Creates a copy button.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'text', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The text copied.'), ApiParameter(name: 'tooltip', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The tooltip before copying; defaults to the localized "Copy".'), ApiParameter(name: 'onCopied', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called after each copy.'), ApiParameter(name: 'onError', type: 'ValueChanged<Object>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the error when the platform refuses a copy.'), ApiParameter(name: 'feedbackDuration', type: 'Duration', isRequired: false, isNamed: true, defaultValue: 'const Duration(milliseconds: 1500)', doc: 'How long the check mark and the "Copied" tooltip, or the failure,\nshow.')])], properties: [], methods: [], values: []),
  'Oito2CopyField': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A read-only field showing [value], such as a link or a token, with an\n[Oito2CopyButton] at its end.', signature: '', constructors: [ApiConstructor(name: 'Oito2CopyField', doc: 'Creates a copy field.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'value', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The text shown and copied.'), ApiParameter(name: 'labelText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The field label.'), ApiParameter(name: 'obscure', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the value shows as dots, such as for a secret.'), ApiParameter(name: 'onCopied', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called after each copy.'), ApiParameter(name: 'onError', type: 'ValueChanged<Object>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the error when the platform refuses a copy.')])], properties: [], methods: [], values: []),
  'Oito2DataTable': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A table of the items of [collection] in [columns], built on an\n[Oito2VirtualList]: only the rows in view are built, and it selects\nand responds to the keyboard as the list does, with the selection kept\nin [controller].\n\nA header row with the column labels stays above the rows. A resizable\ncolumn has a handle at the end of its header, and [onColumnResized]\nreports its width when a resize ends. A click, Enter or Space on the\nheader of a [Oito2TableColumn.sortable] column calls [onSortChanged]\nwith the next sort: ascending, then descending, then none. The header\nof the [sort] column shows an arrow. The table doesn\'t sort: the app\nsorts the items, or an [Oito2AsyncListController] reloads them, and\npasses them back with the new [sort].\n\nColumns wider in total than the table scroll sideways, with the header.\nThe first [pinnedColumns] shown columns stay in place while the others\nscroll, with a divider after them once the table has scrolled.\n\nThe user can choose the columns when the app handles the changes:\n\n* With [onHiddenColumnsChanged], a secondary click or a long press on\n  a header, or the menu key or Shift+F10 on a focused header, opens a\n  menu that shows or hides each column, keeping at least one shown and\n  never hiding a column whose [Oito2TableColumn.hideable] is false.\n  The table doesn\'t show the columns in [hiddenColumns].\n* With [onColumnsReordered], the user moves a column by dragging its\n  header with a mouse, by Alt with Left or Right on its focused header,\n  by the "Move column left" and "Move column right" items of the header\n  menu or by the accessibility actions of the same names. The table\n  shows the columns in [columnOrder]. Pinned columns move only among\n  themselves, and the others only after them. A drag ends without a\n  move on Escape.\n* With [onResetColumns], the header menu has a "Reset columns" item.\n\nThe table doesn\'t change [hiddenColumns] or [columnOrder]: the app\nkeeps the values it is called with and passes them back.\n\nAssistive technologies read the header labels as headers, with their\nsort state as the value of sortable ones, and each row as one item\nlabeled by [rowLabel], or by its cell texts in column order, with its\nposition among the rows.\n\nWith [onReorder], the user reorders the rows as in an\n[Oito2VirtualList], by dragging a whole row.\n\nThe table needs a bounded height, such as from a [SizedBox] or an\n[Expanded].', signature: '', constructors: [ApiConstructor(name: 'Oito2DataTable', doc: 'Creates a data table.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'collection', type: 'Oito2ListCollection<T>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The rows.'), ApiParameter(name: 'controller', type: 'Oito2SelectionController', isRequired: true, isNamed: true, defaultValue: '', doc: 'The selection over [collection].'), ApiParameter(name: 'columns', type: 'List<Oito2TableColumn<T>>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The columns. The first column shows the item label when its\n[Oito2TableColumn.cellBuilder] is null; other columns without one\nshow empty cells.'), ApiParameter(name: 'sort', type: 'Oito2SortDescriptor?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The current sort, by column id, or null.'), ApiParameter(name: 'onSortChanged', type: 'ValueChanged<Oito2SortDescriptor?>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the next sort when the header of a sortable column is\nactivated: ascending for a column the table isn\'t sorted by,\ndescending for an ascending one and null for a descending one.'), ApiParameter(name: 'onColumnResized', type: 'void Function(String, double)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with a column id and its new width when a resize of that\ncolumn ends; the app can keep the width and pass it back as an\n[Oito2ColumnWidth.fixed] width.'), ApiParameter(name: 'onActivate', type: 'ValueChanged<T>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called on Enter or a double click on an enabled row.'), ApiParameter(name: 'rowHeight', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The height of the rows and the header; the theme\'s control height\nwhen null, except that, where the theme pads tap targets (touch\nplatforms), the rows are then [Oito2Sizes.minTouchTarget] tall, as\nin an [Oito2VirtualList].\n\nA height set here is kept on every platform, even below the touch\ntarget size.'), ApiParameter(name: 'cacheExtent', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'How far beyond the visible area rows are built ahead of scrolling.'), ApiParameter(name: 'onReachEnd', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the last rows come near the view, as\n[Oito2VirtualList.onReachEnd].'), ApiParameter(name: 'asyncController', type: 'Oito2AsyncListController<Object?, Object?>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The controller the rows are loaded through, as\n[Oito2VirtualList.asyncController].'), ApiParameter(name: 'rowLabel', type: 'String Function(T)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Returns the accessibility label of a row; its cell texts when null.'), ApiParameter(name: 'showHeader', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the header row shows.'), ApiParameter(name: 'placeholder', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Shown when [collection] is empty and nothing is loading.'), ApiParameter(name: 'semanticLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label of the table.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the table takes the focus when shown.'), ApiParameter(name: 'onReorder', type: 'void Function(int, int)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the user moves a row, with its index in\n[Oito2ListCollection.items] and the index it ends at, counted once it\nis taken out of its place, as [Oito2VirtualList.onReorder] reports\nit: by dragging the row, by Alt with Up or Down on the active row, or\nby the "Move up" and "Move down" accessibility actions. The rows can\'t\nbe reordered when null.\n\nThe table doesn\'t move the row: the app does, and usually clears\n[sort], as the new order no longer follows it.'), ApiParameter(name: 'hiddenColumns', type: 'Set<String>', isRequired: false, isNamed: true, defaultValue: 'const {}', doc: 'The ids of the columns the table doesn\'t show. When every column is\nhidden, the first one in [columnOrder] shows.'), ApiParameter(name: 'onHiddenColumnsChanged', type: 'ValueChanged<Set<String>>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the ids of the columns to hide when the user shows or\nhides a column through the header menu; the columns can\'t be hidden\nwhen null.'), ApiParameter(name: 'columnOrder', type: 'List<String>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The order of the columns, by id; the columns it doesn\'t list follow\nin the order of [columns], and the ids of no column are ignored. The\norder of [columns] when null.'), ApiParameter(name: 'onColumnsReordered', type: 'ValueChanged<List<String>>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the ids of all the columns, hidden ones included, in\ntheir new order when the user moves a column; the columns can\'t be\nmoved when null.'), ApiParameter(name: 'onResetColumns', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the user picks "Reset columns" in the header menu, which\nshows that item only when this is set; the app puts back its 