  'Oito2DateEntry': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A date text field that accepts the locale\'s compact date format (such\nas mm/dd/yyyy) and offers a calendar picker button.\n\nParsing, the format hint and the error messages come from\n`MaterialLocalizations`, so they follow the app language. Errors show\nafter the field loses focus or is submitted, or at once after its\n[Oito2Form] found errors.', signature: '', constructors: [ApiConstructor(name: 'Oito2DateEntry', doc: 'Creates a date entry.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'participatesInForm', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the field registers with the closest [Oito2Form], taking\npart in its validation, error summary and dirty state; true by\ndefault. When false, the field shows its own errors as outside a\nform.'), ApiParameter(name: 'firstDate', type: 'DateTime', isRequired: true, isNamed: true, defaultValue: '', doc: 'The earliest accepted date.'), ApiParameter(name: 'lastDate', type: 'DateTime', isRequired: true, isNamed: true, defaultValue: '', doc: 'The latest accepted date.'), ApiParameter(name: 'initialDate', type: 'DateTime?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The date shown at start.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<DateTime?>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with each valid date, or null when the field is emptied.\n\nInvalid text doesn\'t call it, so the last valid date stays reported;\n[onErrorChanged] tells when the text doesn\'t parse.'), ApiParameter(name: 'onErrorChanged', type: 'ValueChanged<String?>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the error message when the text stops being a valid\ndate, and with null when it is valid again.\n\nIt reports only the parse errors, not those of [validator] or\n[required].'), ApiParameter(name: 'validator', type: 'String? Function(DateTime?)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Checks a valid date, or null for an empty field, and returns an\nerror message, or null to accept it.\n\nThe error shows like a parse error; [onChanged] still reports the\ndate.'), ApiParameter(name: 'required', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether an empty field shows the localized "This field is required"\nerror.'), ApiParameter(name: 'selectableDayPredicate', type: 'SelectableDayPredicate?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Decides which days between [firstDate] and [lastDate] are accepted;\nevery day is when null.'), ApiParameter(name: 'labelText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The field label; defaults to the localized "Enter Date".'), ApiParameter(name: 'acceptEmpty', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether an empty field is valid.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the field takes focus when shown.'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node; one is created when null.'), ApiParameter(name: 'showPickerButton', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the calendar picker button is shown.'), ApiParameter(name: 'currentDate', type: 'DateTime?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The day the calendar marks as today and opens on when no date is\nset; the current date by default.')])], properties: [], methods: [ApiMember(name: 'parseDate', signature: 'static parseDate(String text, MaterialLocalizations localizations, DateTime? reference) → DateTime?', doc: 'Parses [text] in the compact date format of [localizations] (such as\nmm/dd/yyyy), ignoring surrounding spaces.\n\nA year written with one or two digits is taken as the year with those\nlast digits that falls from 80 years before to 19 years after the\nyear of [reference] (today when null), so `26` reads as 2026 in 2026\nand `99` as 1999. A year written with three or more digits is used as\nwritten. Returns null when the text doesn\'t parse.')], values: []),
  'Oito2DatePicker': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A field-like button that shows a date, or a date range when\n[onRangeChanged] is set, and opens an [Oito2Calendar] in a popover to\nchange it.\n\nEnter, Space or Alt+Down opens the calendar, which takes the focus; a\npick closes it. The field is disabled when neither [onChanged] nor\n[onRangeChanged] is set.', signature: '', constructors: [ApiConstructor(name: 'Oito2DatePicker', doc: 'Creates a date picker.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'firstDate', type: 'DateTime', isRequired: true, isNamed: true, defaultValue: '', doc: 'The earliest date that can be picked.'), ApiParameter(name: 'lastDate', type: 'DateTime', isRequired: true, isNamed: true, defaultValue: '', doc: 'The latest date that can be picked.'), ApiParameter(name: 'value', type: 'DateTime?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The picked date, in single mode.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<DateTime>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with a picked date, in single mode.'), ApiParameter(name: 'range', type: 'DateTimeRange<DateTime>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The picked range, in range mode.'), ApiParameter(name: 'onRangeChanged', type: 'ValueChanged<DateTimeRange<DateTime>>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with a picked range; setting it turns on range mode.'), ApiParameter(name: 'labelText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The field label.'), ApiParameter(name: 'hintText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The text shown when nothing is picked; defaults to the localized\ndate format hint.'), ApiParameter(name: 'selectableDayPredicate', type: 'SelectableDayPredicate?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Decides which days between [firstDate] and [lastDate] can be picked;\nevery day can when null.'), ApiParameter(name: 'showWeekNumbers', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the calendar shows week numbers.')])], properties: [], methods: [], values: []),
  'Oito2DateTimeEntry': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A date entry and a time entry side by side that report one combined\n[DateTime]. An empty time means midnight.\n\nIn an [Oito2Form], the two entries take part as two fields.', signature: '', constructors: [ApiConstructor(name: 'Oito2DateTimeEntry', doc: 'Creates a date and time entry.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'participatesInForm', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the field registers with the closest [Oito2Form], taking\npart in its validation, error summary and dirty state; true by\ndefault. When false, the field shows its own errors as outside a\nform.'), ApiParameter(name: 'firstDate', type: 'DateTime', isRequired: true, isNamed: true, defaultValue: '', doc: 'The earliest accepted date.'), ApiParameter(name: 'lastDate', type: 'DateTime', isRequired: true, isNamed: true, defaultValue: '', doc: 'The latest accepted date.'), ApiParameter(name: 'initialDateTime', type: 'DateTime?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The date and time shown at start.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<DateTime?>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with each new valid combination, or null without a date.\n\nIt isn\'t called while either field holds invalid text; once both\nparse again, it reports the combination if it changed.\n[onErrorChanged] tells when one of them doesn\'t parse.'), ApiParameter(name: 'onErrorChanged', type: 'ValueChanged<String?>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the error message of the date field, or else of the time\nfield, when either stops parsing, and with null when both parse.\n\nIt reports only the parse errors, not those of [validator] or\n[required].'), ApiParameter(name: 'validator', type: 'String? Function(DateTime?)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Checks the combination of a valid date and time, or null without a\ndate, and returns an error message, shown under the date field, or\nnull to accept it.'), ApiParameter(name: 'required', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether an empty date field shows the localized "This field is\nrequired" error.'), ApiParameter(name: 'dateLabelText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The date field label; defaults to the localized "Enter Date".'), ApiParameter(name: 'timeLabelText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The time field label; defaults to the localized "Enter time".')])], properties: [], methods: [], values: []),
  'Oito2DesktopEnvironment': ApiEntry(kind: 'enum', package: 'oito2_ui', doc: 'A Linux desktop environment.', signature: '', constructors: [], properties: [], methods: [ApiMember(name: 'detect', signature: 'static detect(String? xdgCurrentDesktop, String? desktopSession) → Oito2DesktopEnvironment', doc: 'Detects the desktop environment from the values of the\n`XDG_CURRENT_DESKTOP` and `DESKTOP_SESSION` environment variables.\n\n`XDG_CURRENT_DESKTOP` is a colon-separated list (for example\n`Budgie:GNOME` or `ubuntu:GNOME`); its entries are checked in order and\nthe first recognized one wins. `DESKTOP_SESSION` is checked only when no\nentry is recognized. Matching ignores case. Returns [unknown] when\nneither value is recognized.')], values: [ApiMember(name: 'gnome', signature: '', doc: 'GNOME, including Ubuntu\'s and Pop!_OS\'s GNOME sessions.'), ApiMember(name: 'kde', signature: '', doc: 'KDE Plasma.'), ApiMember(name: 'xfce', signature: '', doc: 'Xfce.'), ApiMember(name: 'budgie', signature: '', doc: 'Budgie.'), ApiMember(name: 'cosmic', signature: '', doc: 'COSMIC.'), ApiMember(name: 'cinnamon', signature: '', doc: 'Cinnamon.'), ApiMember(name: 'mate', signature: '', doc: 'MATE.'), ApiMember(name: 'lxqt', signature: '', doc: 'LXQt.'), ApiMember(name: 'pantheon', signature: '', doc: 'Pantheon (elementary OS).'), ApiMember(name: 'unity', signature: '', doc: 'Unity.'), ApiMember(name: 'unknown', signature: '', doc: 'A desktop environment not recognized by [detect].')]),
  'Oito2DesktopPageTransitionsBuilder': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A desktop page transition: the incoming page fades in while sliding a\nshort distance from the end side, and the outgoing page fades out.', signature: '', constructors: [ApiConstructor(name: 'Oito2DesktopPageTransitionsBuilder', doc: 'Creates the desktop page transition builder.', isConst: true, isFactory: false, parameters: [])], properties: [ApiMember(name: 'slideFraction', signature: 'static double', doc: 'The fraction of the page width the incoming page travels; it moves\ntoward the start side, so it comes from the right in left-to-right\ntext and from the left in right-to-left text.')], methods: [], values: []),
  'Oito2DetailPage': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A detail page of an [Oito2MasterDetailPage]: a [Scaffold] whose bar\nshows a back button when the page can be popped, which happens in the\nnarrow layout. In the wide layout, where the master shows beside it,\nthe bar shows no back button, even when the route around the\nmaster-detail can be popped.', signature: '', constructors: [ApiConstructor(name: 'Oito2DetailPage', doc: 'Creates a detail page.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'title', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The title of the default bar.'), ApiParameter(name: 'actions', type: 'List<Widget>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: 'Actions of the default bar.'), ApiParameter(name: 'appBar', type: 'PreferredSizeWidget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Replaces the default bar.'), ApiParameter(name: 'body', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The page content.'), ApiParameter(name: 'floatingActionButton', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A floating action button.'), ApiParameter(name: 'backgroundColor', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The background; defaults to the scaffold background.')])], properties: [], methods: [], values: []),
  'Oito2DiagonalClip': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Clips [child] along a diagonal, keeping the triangle on the side of\n[corner]. Combine two of them to split an area diagonally, for example\nto preview light and dark themes in one swatch.', signature: '', constructors: [ApiConstructor(name: 'Oito2DiagonalClip', doc: 'Creates a diagonal clip.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'corner', type: 'Oito2DiagonalCorner', isRequired: true, isNamed: true, defaultValue: '', doc: 'The corner whose triangle is kept.'), ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The clipped content.')])], properties: [], methods: [], values: []),
