  'Oito2DialogTitleBar': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'The title bar of a dialog: a title and a close button that pops the\ndialog route.\n\nThe close button follows the system window control style, falling back\nto the GNOME style where the platform has none (web, touch and macOS),\nand the side of the close button in the system button layout.', signature: '', constructors: [ApiConstructor(name: 'Oito2DialogTitleBar', doc: 'Creates a dialog title bar.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'title', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The dialog title, usually a [Text].'), ApiParameter(name: 'leading', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A widget before the title, such as an [Icon] or an animated\n`Oito2AnimatedIcon` that tells what the dialog is about.'), ApiParameter(name: 'onClose', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the close button is pressed; defaults to popping the\ncurrent route.'), ApiParameter(name: 'labels', type: 'Oito2WindowControlLabels?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Override of the close button\'s accessibility label, which otherwise\ncomes from [Oito2Localizations].')])], properties: [ApiMember(name: 'preferredSize', signature: 'Size', doc: 'The size of the bar on pointer platforms.\n\nWhere the theme pads tap targets (touch platforms), the bar grows to\nfit a 48-pixel close button; size a [PreferredSize] around it with\n[Oito2TitleBar.preferredSizeOf] and [BorderSide.none] there.')], methods: [], values: []),
  'Oito2Draggable': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A widget the user can move inside a [Stack], with the pointer or, once\nfocused, with the arrow keys.\n\nIt must be a direct child of a [Stack]. The position is relative to\nthe stack\'s top-left corner. With [boundedByStack], the default, moves\nstop at the stack\'s edges, so the widget stays inside it.', signature: '', constructors: [ApiConstructor(name: 'Oito2Draggable', doc: 'Creates a draggable widget.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The content that moves.'), ApiParameter(name: 'initialPosition', type: 'Offset', isRequired: false, isNamed: true, defaultValue: 'Offset.zero', doc: 'The initial offset from the stack\'s top-left corner; later changes\nare ignored.'), ApiParameter(name: 'onDragStart', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when a pointer drag starts.'), ApiParameter(name: 'onDragEnd', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when a pointer drag ends.'), ApiParameter(name: 'onMoved', type: 'ValueChanged<Offset>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with each new position, after a pointer or keyboard move.'), ApiParameter(name: 'keyboardStep', type: 'double', isRequired: false, isNamed: true, defaultValue: '8', doc: 'How far one arrow key press, or one accessibility move action, moves\nthe widget, in logical pixels.'), ApiParameter(name: 'semanticLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The name assistive technologies read for the widget, which they also\ntell can be moved with the arrow keys or the move actions.'), ApiParameter(name: 'boundedByStack', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether moves keep the widget inside the [Stack]; when false, it can\nbe moved past the stack\'s edges.')])], properties: [], methods: [], values: []),
  'Oito2EdgeFocusInterceptor': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Keeps arrow-key focus navigation inside [child]: at the edges of the\ngroup the arrow keys stop instead of moving focus out of it.\n\nUseful for grids and toolbars navigated with the arrow keys, so the\nkeyboard user doesn\'t fall out of the group by accident. Tab and\nShift+Tab still move to the widgets around the group.', signature: '', constructors: [ApiConstructor(name: 'Oito2EdgeFocusInterceptor', doc: 'Creates an edge focus interceptor.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The group of focusable widgets.')])], properties: [], methods: [], values: []),
  'Oito2EditableLabel': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A text label that turns into a field to rename it in place.\n\nA double click, Enter or F2 starts editing with the text selected.\nEnter or leaving the field keeps the change, calling [onSubmitted]\nwith the trimmed text when it changed and isn\'t empty; Escape\nrestores the text. [onSubmitted] null makes the label read-only.', signature: '', constructors: [ApiConstructor(name: 'Oito2EditableLabel', doc: 'Creates an editable label.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'text', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The label text.'), ApiParameter(name: 'onSubmitted', type: 'ValueChanged<String>?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with the new, trimmed text after a change; null makes the\nlabel read-only.'), ApiParameter(name: 'style', type: 'TextStyle?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The text style; defaults to `bodyLarge`.'), ApiParameter(name: 'placeholder', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The text shown in the placeholder color while [text] is empty.'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node of the label; one is created when null.')])], properties: [], methods: [], values: []),
