  'Oito2Expandable': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A header that shows or hides [child] when activated.\n\nThe whole header row toggles the content, with keyboard support and the\nexpanded state exposed to assistive technologies.\n\nWith [onChanged], the state is controlled: activating the header only\ncalls [onChanged], and the content follows [isExpanded], so the parent\ndecides whether it changes. Without [onChanged], [isExpanded] is only\nthe initial state and the header toggles the content itself.', signature: '', constructors: [ApiConstructor(name: 'Oito2Expandable', doc: 'Creates an expandable section.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'header', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The always-visible header, usually a [Text].'), ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The content shown when expanded.'), ApiParameter(name: 'collapsedChild', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The content shown when collapsed, such as a summary.'), ApiParameter(name: 'isExpanded', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the content is shown; only the initial state when\n[onChanged] is null.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<bool>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the requested state when the header is activated; when\nset, the parent applies it through [isExpanded].'), ApiParameter(name: 'buttonPosition', type: 'Oito2ExpandButtonPosition', isRequired: false, isNamed: true, defaultValue: 'Oito2ExpandButtonPosition.end', doc: 'Where the expand button sits.'), ApiParameter(name: 'gap', type: 'double', isRequired: false, isNamed: true, defaultValue: 'Oito2Spacing.xs', doc: 'Space between the header and the content.')])], properties: [], methods: [], values: []),
  'Oito2ExpansionPanel': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A bordered stack of sections, each with a header that expands its\ncontent, as an accordion.\n\n[headers] and [children] pair up by index. With [collapseOnExpand],\nopening a section closes the others, so at most one is open. The open\nsections are kept by index: when the sections change, those past the\nnew end close, and turning [collapseOnExpand] on keeps only the first\nopen one.\n[onExpansionChanged] reports each section that opens or closes.', signature: '', constructors: [ApiConstructor(name: 'Oito2ExpansionPanel', doc: 'Creates an expansion panel.\n\nThrows an [AssertionError] in debug builds, when built, if [headers]\nand [children] differ in length.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'headers', type: 'List<Widget>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The section headers, usually [Text]s.'), ApiParameter(name: 'children', type: 'List<Widget>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The section contents, in the order of [headers]; one per header.'), ApiParameter(name: 'initiallyExpanded', type: 'Set<int>', isRequired: false, isNamed: true, defaultValue: 'const {}', doc: 'The indexes of the sections open at start; with [collapseOnExpand],\nonly the first of them opens.'), ApiParameter(name: 'collapseOnExpand', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether opening a section closes the others.'), ApiParameter(name: 'placeDividers', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether dividers separate the sections.'), ApiParameter(name: 'padding', type: 'EdgeInsetsGeometry', isRequired: false, isNamed: true, defaultValue: 'const EdgeInsets.symmetric(horizontal: Oito2Spacing.md, vertical: Oito2Spacing.sm)', doc: 'Space around each section.'), ApiParameter(name: 'onExpansionChanged', type: 'void Function(int, bool)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the index of each section that opens or closes and\nwhether it is now open, including the sections [collapseOnExpand]\ncloses, which are reported before the section that opened.')])], properties: [], methods: [], values: []),
