  'Oito2FloatingPanel': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A non-modal window inside the app, such as an inspector or a tool\npalette, that the user moves, resizes, minimizes and maximizes.\n\nPlace it in a [Stack]; it covers the stack to know its bounds but only\ntakes pointer events on itself. Dragging the title bar moves it and a\ndouble click maximizes or restores it; with [resizable] its right and\nbottom edges and corner resize it. Minimizing leaves only the title\nbar. With the focus on the title bar the arrow keys move the panel and\nShift with the arrows resizes it. The title bar keeps inside the\nstack. Minimized content keeps its state.\n\nPanels in the same [Stack] keep the stacking order of its children:\nclicking a panel doesn\'t bring it to the front, so the app reorders\nthe children when it wants that.', signature: '', constructors: [ApiConstructor(name: 'Oito2FloatingPanel', doc: 'Creates a floating panel.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'title', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The panel title.'), ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The panel content.'), ApiParameter(name: 'initialRect', type: 'Rect', isRequired: false, isNamed: true, defaultValue: 'const Rect.fromLTWH(40, 40, 360, 280)', doc: 'The position and size at start, in the stack\'s coordinates.'), ApiParameter(name: 'minSize', type: 'Size', isRequired: false, isNamed: true, defaultValue: 'const Size(220, 140)', doc: 'The smallest size the panel can be resized to.'), ApiParameter(name: 'resizable', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the edges resize the panel.'), ApiParameter(name: 'onClose', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called by the close button; the panel shows no close button when\nnull.'), ApiParameter(name: 'onRectChanged', type: 'ValueChanged<Rect>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the new rectangle on every move or resize step,\nincluding each step of a drag.'), ApiParameter(name: 'controlStyle', type: 'Oito2WindowControlStyle', isRequired: false, isNamed: true, defaultValue: 'Oito2WindowControlStyle.gnome', doc: 'The look of the title bar buttons.'), ApiParameter(name: 'keyboardStep', type: 'double', isRequired: false, isNamed: true, defaultValue: '16', doc: 'The distance, in logical pixels, one arrow key press moves or\nresizes the panel.')])], properties: [], methods: [], values: []),
  'Oito2FocusBorder': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Draws a 2-pixel ring in the text-safe primary tone around [child]\nwhile a widget inside it has keyboard focus.\n\nThe ring shows only in keyboard navigation mode, not after pointer\nclicks, and doesn\'t affect layout.', signature: '', constructors: [ApiConstructor(name: 'Oito2FocusBorder', doc: 'Creates a focus border.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The content the ring surrounds.'), ApiParameter(name: 'borderRadius', type: 'BorderRadius', isRequired: false, isNamed: true, defaultValue: 'Oito2Radius.mediumAll', doc: 'The ring corner radius.'), ApiParameter(name: 'focused', type: 'bool?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Forces the ring on or off; null follows keyboard focus and the\nhighlight mode.')])], properties: [], methods: [], values: []),
  'Oito2Form': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Groups fields under an [Oito2FormController].\n\nThe fields below it register with [controller], which validates them,\ntracks whether they changed and leads the user to the first invalid\none. Show the errors at the top of the form with an\n[Oito2FormErrorSummary].', signature: '', constructors: [ApiConstructor(name: 'Oito2Form', doc: 'Creates a form that registers the fields of [child] with\n[controller].', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'controller', type: 'Oito2FormController', isRequired: true, isNamed: true, defaultValue: '', doc: 'The controller the fields register with.'), ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The form content.')])], properties: [], methods: [ApiMember(name: 'maybeOf', signature: 'static maybeOf(BuildContext context) → Oito2FormController?', doc: 'Returns the controller of the closest enclosing [Oito2Form], or null\nwhen there is none, and rebuilds [context] when the controller\nnotifies its listeners.'), ApiMember(name: 'of', signature: 'static of(BuildContext context) → Oito2FormController', doc: 'Returns the controller of the closest enclosing [Oito2Form].\n\nThrows a [FlutterError] when there is none.')], values: []),
  'Oito2FormController': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Tracks the fields of an [Oito2Form]: validates them, leads the user to\nthe first invalid one and tells whether any value changed.\n\nFields register themselves while they sit below an [Oito2Form] that\nuses this controller: the oito2 entries do it on their own, and a\nFlutter `FormField` does it inside an [Oito2FormFieldAdapter]. A field\noutside any form behaves as on its own.\n\nErrors show under a field once it loses focus or is submitted; after a\n[validate] that finds errors, [showsErrors] turns true and every field\nshows its error at once, also while it is being fixed.\n\nListeners are notified when a field changes its value or error, when\nfields come and go, and after [validate], [markClean] and [reset].', signature: '', constructors: [ApiConstructor(name: 'Oito2FormController', doc: 'Creates a form controller.', isConst: false, isFactory: false, parameters: [])], properties: [ApiMember(name: 'showsErrors', signature: 'bool', doc: 'Whether every field shows its error now, which is true after a\n[validate] that found errors, until [reset].'), ApiMember(name: 'fields', signature: 'List<Oito2FormFieldMixin<StatefulWidget>>', doc: 'The registered fields, in the order of the widget tree as of the last\n[validate], followed by the fields registered since, in registration\norder.'), ApiMember(name: 'errors', signature: 'List<Oito2FormError>', doc: 'The current errors of the fields, in the order of [fields].\n\nEach error is computed from the field\'s current value, so a fixed\nfield leaves the list as soon as its value is valid.'), ApiMember(name: 'isDirty', signature: 'bool', doc: 'Whether any field holds a value other than its clean value: the\ninitial value, or the value of the last [markClean].')], methods: [ApiMember(name: 'validate', signature: 'validate(bool focusFirstError, bool announce) → bool', doc: 'Validates every field and returns whether all of them are valid.\n\nWhen some are not, every field shows its error, the first invalid\nfield in the order of the widget tree takes the focus and scrolls\ninto view, and assistive technologies politely hear the number of\nerrors. [focusFirstError] and [announce] turn those two steps off.'), ApiMember(name: 'submit', signature: 'submit(FutureOr<void> Function() onValid) → Future<bool>', doc: 'Validates the form and, when it is valid, calls [onValid] and waits\nfor it.\n\nReturns whether the form was valid.'), ApiMember(name: 'markClean', signature: 'markClean() → void', doc: 'Takes the current value of every field as its clean value, as after\nthe values are saved, so [isDirty] turns false.'), ApiMember(name: 'reset', signature: 'reset() → void', doc: 'Puts every field back to its clean value, where the field supports\nit, and hides the errors until the fields lose focus or the form is\nvalidated again.'), ApiMember(name: 'revealField', signature: 'revealField(Oito2FormFieldMixin<StatefulWidget> field) → void', doc: 'Scrolls [field] into view and focuses it.')], values: []),
  'Oito2FormError': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'The error of one field of an [Oito2Form].', signature: '', constructors: [], properties: [ApiMember(name: 'message', signature: 'String', doc: 'The error message.'), ApiMember(name: 'label', signature: 'String?', doc: 'The name of the field, or null when it has none.')], methods: [ApiMember(name: 'reveal', signature: 'reveal() → void', doc: 'Scrolls the field into view and focuses it.')], values: []),
  'Oito2FormErrorSummary': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'The errors of an [Oito2Form] in an [Oito2Alert] of the danger type,\nsuch as "Fix 2 errors to continue", with one link per error that\nscrolls to its field and focuses it.\n\nThe summary shows after a validation that found errors and goes away\nonce every error is fixed. It is a live region, so assistive\ntechnologies announce it when it appears.', signature: '', constructors: [ApiConstructor(name: 'Oito2FormErrorSummary', doc: 'Creates an error summary of [controller], or of the closest\n[Oito2Form] when it is null.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'controller', type: 'Oito2FormController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The form controller; defaults to the closest [Oito2Form].'), ApiParameter(name: 'title', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The headline; defaults to the localized "Fix N errors to continue".')])], properties: [], methods: [], values: []),
  'Oito2FormFieldAdapter': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Registers a Flutter `FormField`, such as a `TextFormField`, with the\nclosest [Oito2Form].\n\nThe adapter finds the first `FormField` in [child] and wraps it in a\nFlutter `Form` of its own, so the field reports its changes; a field\ninside it doesn\'t register with an outer `Form`. Its error comes from\nthe field\'s `validator`, its clean value is its value at start or at\nthe last `markClean`, and the form focuses the first focusable widget\nin [child].', signature: '', constructors: [ApiConstructor(name: 'Oito2FormFieldAdapter', doc: 'Creates an adapter for the form field in [child].', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'label', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The name of the field in the error summary.'), ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The subtree that holds the form field.')])], properties: [], methods: [], values: []),
  'Oito2FormFieldMixin': ApiEntry(kind: 'mixin', package: 'oito2_ui', doc: 'Lets the state of a field take part in an [Oito2Form].\n\nThe state registers with the closest [Oito2Form] while it is mounted\nand answers the form through the members it implements: its label,\nthe focus node to focus, its current error and whether its value\nchanged. A state outside any form keeps working on its own.\n\nCall [notifyFormFieldChanged] whenever the value or the error changes,\nso the form summary and the dirty state follow. Override\n[participatesInForm] to let the widget leave the form.\n\nThe state rebuilds when [formShowsErrors] changes, not on every change\nof the form, so a change in one field doesn\'t rebuild the others.', signature: '', constructors: [], properties: [ApiMember(name: 'form', signature: 'Oito2FormController?', doc: 'The controller of the form the field is registered with, or null\noutside a form.'), ApiMember(name: 'formFieldLabel', signature: 'String?', doc: 'The name of the field in the error summary, or null to show only the\nmessage.'), ApiMember(name: 'formFieldFocusNode', signature: 'FocusNode?', doc: 'The node focused when the form leads the user to the field.'), ApiMember(name: 'formFieldError', signature: 'String?', doc: 'The error of the current value, or null when it is valid.\n\nReading it doesn\'t change the field.'), ApiMember(name: 'isFormFieldDirty', signature: 'bool', doc: 'Whether the value differs from the clean value: the initial value,\nor the value at the last [markFormFieldClean].'), ApiMember(name: 'formShowsErrors', signature: 'bool', doc: 'Whether the form shows every error now, after a validation that\nfound errors; false outside a form.'), ApiMember(name: 'participatesInForm', signature: 'bool', doc: 'Whether the field registers with the closest [Oito2Form]; true by\ndefault.\n\nA field that doesn\'t take part is left out of validation, the error\nsummary and the dirty state, and shows its own errors as outside a\nform.')], methods: [ApiMember(name: 'showFormFieldError', signature: 'showFormFieldError() → void', doc: 'Makes the current error, if any, visible under the field; does\nnothing by default.'), ApiMember(name: 'resetFormField', signature: 'resetFormField() → void', doc: 'Puts the field back to its clean value; does nothing by default.'), ApiMember(name: 'markFormFieldClean', signature: 'markFormFieldClean() → void', doc: 'Takes the current value as the clean value; does nothing by default.'), ApiMember(name: 'notifyFormFieldChanged', signature: 'notifyFormFieldChanged() → void', doc: 'Tells the form that the value or the error of the field changed.')], values: []),
  'Oito2Format': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Locale-aware formatting of byte sizes, compact numbers and relative\ntimes, such as "1.5 MB", "1.23K" and "3 minutes ago".\n\nNumbers follow the [locale] through `intl`; relative times use the\n[strings] of [Oito2Localizations]. [Oito2Format.of] takes both from a\nwidget context. Plain numbers, dates and times are formatted with\n`intl` directly.', signature: '', constructors: [ApiConstructor(name: 'Oito2Format', doc: 'Creates a formatter for [locale], such as `en` or `pt_BR`, with the\nrelative-time [strings]; locales `intl` doesn\'t know fall back to\nEnglish number formats.', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'locale', type: 'String', isRequired: false, isNamed: true, defaultValue: '\'en\'', doc: ''), ApiParameter(name: 'strings', type: 'Oito2Localizations', isRequired: false, isNamed: true, defaultValue: 'const Oito2LocalizationsEn()', doc: 'The relative-time strings.')]), ApiConstructor(name: 'Oito2Format.of', doc: 'Creates a formatter for the locale and the [Oito2Localizations] of\n[context], with English when [context] has no locale.', isConst: false, isFactory: true, parameters: [ApiParameter(name: 'context', type: 'BuildContext', isRequired: true, isNamed: false, defaultValue: '', doc: '')])], properties: [], methods: [ApiMember(name: 'bytes', signature: 'bytes(int bytes, Oito2ByteUnits units, int fractionDigits) → String', doc: 'Formats a byte count in [units], such as `1536` as "1.5 kB" (or\n"1,5 kB" in Portuguese), with at most [fractionDigits] decimals.\n\nPicks the largest unit, up to petabytes, that keeps the value at\nleast 1; counts below one kilobyte keep no decimals. Negative counts\nkeep their sign.'), ApiMember(name: 'compactNumber', signature: 'compactNumber(num value) → String', doc: 'Formats [value] in compact form with three significant digits, such\nas `1234` as "1.23K" (or "1,23 mil" in Portuguese).'), ApiMember(name: 'relativeTime', signature: 'relativeTime(DateTime time, DateTime? now) → String', doc: 'Describes [time] relative to [now] (the current time by default),\nsuch as "3 minutes ago" or "in 2 days", with [strings].\n\nTimes within 45 seconds read as [Oito2Localizations.justNow]. Larger\ndifferences are rounded to minutes below 45 minutes, hours below 22\nhours, days below six and a half days, weeks below 30 days, months\n(of 30 days) below 365 days and years beyond.')], values: []),
  'Oito2FreedesktopIcons': ApiEntry(kind: 'enum', package: 'oito2_ui', doc: 'Icons named after the freedesktop.org Icon Naming Specification, drawn\nwith the Lucide icons oito2_ui uses.\n\nLinux integrations refer to icons by these names, for example in\n`.desktop` files, notifications and tray items; [byName] turns such a\nname into an icon, and [forMimeType] picks the icon of a file by its\nMIME type. Each value keeps its specification name in [iconName], such\nas `document-open`.\n\nBesides the names of the specification, a few names that icon themes\nwidely share are included, such as `application-x-generic`,\n`emblem-synchronizing` and `sync-error`.\n\n```dart\nIcon(Oito2FreedesktopIcons.documentOpen.icon);\nIcon(Oito2FreedesktopIcons.byName(\'dialog-warning\')?.icon);\nIcon(Oito2FreedesktopIcons.forMimeType(\'application/pdf\').icon);\n```', signature: '', constructors: [], properties: [], methods: [ApiMember(name: 'byName', signature: 'static byName(String name) → Oito2FreedesktopIcons?', doc: 'Returns the icon for a specification [name], such as\n`document-save`, or null when nothing matches.\n\nTrailing `-symbolic`, `-rtl` and `-ltr` suffixes are ignored, and a\nname without a mapping falls back, as the specification does, to the\nname without its last dash-separated part: `folder-documents` to\n`folder`.'), ApiMember(name: 'forMimeType', signature: 'static forMimeType(String mimeType) → Oito2FreedesktopIcons', doc: 'Returns the icon for a [mimeType], such as `application/pdf` or\n`image/png`; any parameters after a `;` and the case are ignored.\n\nOffice formats, such as the OpenDocument and Microsoft Office types,\nmap to the `x-office-*` icons and their templates, PDF and RTF to\n[xOfficeDocument], archives and packages to [packageXGeneric],\nprograms to [applicationXExecutable], scripts to [textXScript] and\n`inode/directory` to [folder]. Other types fall back to the icon of\ntheir top-level type, as `image/*` to [imageXGeneric], and then to\n[textXGeneric] for text and [applicationXGeneric] for the rest.')], values: [ApiMember(name: 'addressBookNew', signature: '', doc: '`address-book-new`.'), ApiMember(name: 'applicationExit', signature: '', doc: '`application-exit`.'), ApiMember(name: 'appointmentNew', signature: '', doc: '`appointment-new`.'), ApiMember(name: 'callStart', signature: '', doc: '`call-start`.'), ApiMember(name: 'callStop', signature: '', doc: '`call-stop`.'), ApiMember(name: 'contactNew', signature: '', doc: '`contact-new`.'), ApiMember(name: 'documentNew', signature: '', doc: '`document-new`.'), ApiMember(name: 'documentOpen', signature: '', doc: '`document-open`.'), ApiMember(name: 'documentOpenRecent', signature: '', doc: '`document-open-recent`.'), ApiMember(name: 'documentPageSetup', signature: '', doc: '`document-page-setup`.'), ApiMember(name: 'documentPrint', signature: '', doc: '`document-print`.'), ApiMember(name: 'documentPrintPreview', signature: '', doc: '`document-print-preview`.'), ApiMember(name: 'documentProperties', signature: '', doc: '`document-properties`.'), ApiMember(name: 'documentRevert', signature: '', doc: '`document-revert`.'), ApiMember(name: 'documentSave', signature: '', doc: '`document-save`.'), ApiMember(name: 'documentSaveAs', signature: '', doc: '`document-save-as`.'), ApiMember(name: 'documentSend', signature: '', doc: '`document-send`.'), ApiMember(name: 'editClear', signature: '', doc: '`edit-clear`.'), ApiMember(name: 'editCopy', signature: '', doc: '`edit-copy`.'), ApiMember(name: 'editCut', signature: '', doc: '`edit-cut`.'), ApiMember(name: 'editDelete', signature: '', doc: '`edit-delete`.'), ApiMember(name: 'editFind', signature: '', doc: '`edit-find`.'), ApiMember(name: 'editFindReplace', signature: '', doc: '`edit-find-replace`.'), ApiMember(name: 'editPaste', signature: '', doc: '`edit-paste`.'), ApiMember(name: 'editRedo', signature: '', doc: '`edit-redo`.'), ApiMember(name: 'editSelectAll', signature: '', doc: '`edit-select-all`.'), ApiMember(name: 