  'Oito2InfoBox': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A message box tinted by its [type], with an icon, a title, an optional\nsubtitle, extra content and a trailing widget.', signature: '', constructors: [ApiConstructor(name: 'Oito2InfoBox', doc: 'Creates an info box.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'type', type: 'Oito2InfoType', isRequired: true, isNamed: true, defaultValue: '', doc: 'The kind of message.'), ApiParameter(name: 'title', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The headline, in the type color.'), ApiParameter(name: 'subtitle', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The message text.'), ApiParameter(name: 'child', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Extra content below the subtitle.'), ApiParameter(name: 'trailing', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A widget at the end, such as a close or action button.'), ApiParameter(name: 'icon', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Replaces the type icon; unlike the default icon, it carries no kind\nlabel for assistive technologies.')])], properties: [], methods: [], values: []),
  'Oito2InfoType': ApiEntry(kind: 'enum', package: 'oito2_ui', doc: 'The kind of message shown by [Oito2InfoBox] and [Oito2InfoBadge].', signature: '', constructors: [], properties: [], methods: [ApiMember(name: 'labelIn', signature: 'labelIn(Oito2Localizations strings) → String', doc: 'Returns the localized name of this kind from [strings], such as\n"Warning", for assistive technologies.'), ApiMember(name: 'colorIn', signature: 'colorIn(Oito2SemanticColors colors) → Color', doc: 'Returns the color of this kind in [colors].')], values: [ApiMember(name: 'information', signature: '', doc: 'Neutral information.'), ApiMember(name: 'success', signature: '', doc: 'A successful or positive outcome.'), ApiMember(name: 'warning', signature: '', doc: 'Something that needs attention.'), ApiMember(name: 'danger', signature: '', doc: 'An error or a destructive consequence.'), ApiMember(name: 'important', signature: '', doc: 'Something the user should notice, in the accent color.')]),
