  'Oito2LinearProgressIndicator': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A linear progress indicator painted in the oito2 style.\n\nWith a [value] from 0 to 1, a bar fills the track from the start side.\nWithout one, a short segment glides back and forth along the track, as\nGNOME\'s pulse; when animations are disabled it stays still. The bar\nand the track have round ends and fill the available width, or 160\npixels when the width is unbounded.\n\nColors and height default to the theme\'s\n[Oito2ProgressIndicatorThemeData].', signature: '', constructors: [ApiConstructor(name: 'Oito2LinearProgressIndicator', doc: 'Creates a linear progress indicator.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'value', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The progress from 0 to 1, or null for indeterminate progress.'), ApiParameter(name: 'height', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The bar height.'), ApiParameter(name: 'color', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The progress color.'), ApiParameter(name: 'trackColor', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The track color.'), ApiParameter(name: 'semanticsLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label, such as what is loading.'), ApiParameter(name: 'semanticsValue', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility value; defaults to the percentage of [value].')])], properties: [], methods: [], values: []),
  'Oito2ListBox': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A list of the items of [collection] that the user selects from, with\nthe selection kept in [controller].\n\nThe list takes the focus as a whole and marks its active row. The\narrow keys, Home and End move the active row, which a single-selection\nlist also selects. In a multiple-selection list Space toggles the\nactive row, Shift with the arrows extends the selection and Control\n(Command on Apple platforms) with A selects all; clicks follow the\ndesktop conventions of [Oito2SelectionController.click]. Typing letters\njumps to the next matching label. Enter or a double click calls\n[onActivate]. Grouped items show under their group headings; disabled\nitems can\'t be selected or activated.\n\nWith [onReorder], the user reorders the items: Alt with Up or Down\nmoves the active row up or down by one, the rows offer "Move up" and\n"Move down" accessibility actions, and the rows can be dragged, with\na line between the rows marking the drop and the list scrolling when\nthe pointer nears its top or bottom edge; Escape cancels a drag. A\nmouse drags a row once it moves a few pixels and a touch after a long\npress, or, with [dragHandle], only the grip at the start of each row\ndrags it, with any pointer. Disabled items can\'t be dragged. The list\ndoesn\'t change [collection]: the app moves the item. A list whose\nitems fall in more than one group can\'t be reordered.\n\nEvery row is built, so it suits lists of up to a few hundred items;\n[Oito2VirtualList] builds only the rows in view, for longer lists.', signature: '', constructors: [ApiConstructor(name: 'Oito2ListBox', doc: 'Creates a list box.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'collection', type: 'Oito2ListCollection<T>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The items.'), ApiParameter(name: 'controller', type: 'Oito2SelectionController', isRequired: true, isNamed: true, defaultValue: '', doc: 'The selection over [collection].'), ApiParameter(name: 'itemBuilder', type: 'Oito2ListBoxItemBuilder<T>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Builds the content of a row; shows the item label when null.'), ApiParameter(name: 'onActivate', type: 'ValueChanged<T>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called on Enter or a double click on an enabled item.'), ApiParameter(name: 'maxHeight', type: 'double', isRequired: false, isNamed: true, defaultValue: 'double.infinity', doc: 'The largest height; the list scrolls beyond it.'), ApiParameter(name: 'semanticLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label of the list.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the list takes the focus when shown.'), ApiParameter(name: 'onReorder', type: 'void Function(int, int)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the user moves an item, with its index in\n[Oito2ListCollection.items] and the index it ends at, counted once it\nis taken out of its place: moving the first of three items to the end\nreports `(0, 2)`. The items can\'t be reordered when null.'), ApiParameter(name: 'dragHandle', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether only a grip at the start of each row drags it, instead of\nthe whole row, when [onReorder] is set.')])], properties: [], methods: [], values: []),
  'Oito2ListBoxItemBuilder': ApiEntry(kind: 'typedef', package: 'oito2_ui', doc: 'Builds the content of an [Oito2ListBox] row.', signature: 'Widget Function(BuildContext, T, bool)', constructors: [], properties: [], methods: [], values: []),
  'Oito2ListCollection': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'An immutable list of items with the accessors a list, select or\nautocomplete needs: a unique string value, a display label, a disabled\nflag and an optional group per item.\n\nNavigation methods skip disabled items. Methods that change the list\nreturn a new collection.', signature: '', constructors: [ApiConstructor(name: 'Oito2ListCollection', doc: 'Creates a collection of [items].\n\n[valueOf] gives each item\'s unique value and defaults to the item\nitself when it is a [String], or its `toString()` otherwise.\n[labelOf] defaults to [valueOf]. Items are enabled unless\n[isDisabled] says otherwise, and ungrouped unless [groupOf] returns\na group name.\n\nWith [groupOf], [items] keeps the items of each group together: the\ngroups follow the order in which each first appears, and the items of\na group keep their relative order. Keyboard navigation, typeahead and\nrange selection therefore follow the order the groups are shown in.\n\nThrows an [ArgumentError] when two items share a value.', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'items', type: 'Iterable<T>', isRequired: true, isNamed: false, defaultValue: '', doc: ''), ApiParameter(name: 'valueOf', type: 'String Function(T)?', isRequired: false, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'labelOf', type: 'String Function(T)?', isRequired: false, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'isDisabled', type: 'bool Function(T)?', isRequired: false, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'groupOf', type: 'String? Function(T)?', isRequired: false, isNamed: true, defaultValue: '', doc: '')])], properties: [ApiMember(name: 'length', signature: 'int', doc: 'The number of items.'), ApiMember(name: 'isEmpty', signature: 'bool', doc: 'Whether the collection has no items.'), ApiMember(name: 'values', signature: 'List<String>', doc: 'The values of every item, in order.'), ApiMember(name: 'firstValue', signature: 'String?', doc: 'The value of the first enabled item, or null.'), ApiMember(name: 'lastValue', signature: 'String?', doc: 'The value of the last enabled item, or null.'), ApiMember(name: 'groups', signature: 'List<({String? group, List<T> items})>', doc: 'The items grouped by [groupOf], in the order each group first\nappears; ungrouped items form a group named null.')], methods: [ApiMember(name: 'valueOf', signature: 'valueOf(T item) → String', doc: 'Returns the unique value of [item].'), ApiMember(name: 'labelOf', signature: 'labelOf(T item) → String', doc: 'Returns the display label of [item].'), ApiMember(name: 'isDisabled', signature: 'isDisabled(T item) → bool', doc: 'Whether [item] can\'t be selected or focused.'), ApiMember(name: 'groupOf', signature: 'groupOf(T item) → String?', doc: 'Returns the group of [item], or null when it has none.'), ApiMember(name: 'has', signature: 'has(String? value) → bool', doc: 'Whether an item has [value].'), ApiMember(name: 'indexOf', signature: 'indexOf(String? value) → int', doc: 'Returns the index of the item with [value], or -1 when there is none.'), ApiMember(name: 'find', signature: 'find(String? value) → T?', doc: 'Returns the item with [value], or null when there is none.'), ApiMember(name: 'isEnabled', signature: 'isEnabled(String? value) → bool', doc: 'Whether the item with [value] exists and is enabled.'), ApiMember(name: 'nextValue', signature: 'nextValue(String value, bool loop) → String?', doc: 'Returns the value of the first enabled item after [value], or null at\nthe end. With [loop], the search wraps around to the start.\n\nWhen [value] isn\'t in the collection, the search starts before the\nfirst item.'), ApiMember(name: 'previousValue', signature: 'previousValue(String value, bool loop) → String?', doc: 'Returns the value of the first enabled item before [value], or null\nat the start. With [loop], the search wraps around to the end.\n\nWhen [value] isn\'t in the collection, the search starts after the\nlast item.'), ApiMember(name: 'search', signature: 'search(String query, String? from) → String?', doc: 'Returns the value of the first enabled item whose label starts with\n[query], ignoring case and accents, searching after the item with\nvalue [from] (from the first item when [from] is null or unknown) and\nwrapping around; null when none matches or [query] is empty.\n\nIt implements typeahead: typing letters while a list has focus moves\nto the next matching item.'), ApiMember(name: 'copyWith', signature: 'copyWith(Iterable<T> items) → Oito2ListCollection<T>', doc: 'Returns a collection of [items] with the same accessors.\n\nThrows an [ArgumentError] when two of [items] share a value.'), ApiMember(name: 'where', signature: 'where(bool Function(T) test) → Oito2ListCollection<T>', doc: 'Returns a collection of the items for which [test] returns true.'), ApiMember(name: 'filter', signature: 'filter(String query) → Oito2ListCollection<T>', doc: 'Returns a collection of the items whose label contains [query],\nignoring case and accents.'), ApiMember(name: 'suggestions', signature: 'suggestions(String query, Set<String> exclude) → List<T>', doc: 'Returns the enabled items whose label contains [query], ignoring case\nand accents, in order, leaving out those whose label is in [exclude]:\nthe suggestions for a text typed in a field.'), ApiMember(name: 'reorder', signature: 'reorder(int from, int to) → Oito2ListCollection<T>', doc: 'Returns the collection with the item at [from] moved to [to].\n\nThrows a [RangeError] when either index is outside the items.')], values: []),
  'Oito2ListTile': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'An interactive row with a title, an optional subtitle and widgets on\nboth sides, styled for desktop lists and settings pages.\n\nUnlike [Oito2Tile], it is meant to be activated: it shows hover and\nselected states, takes keyboard focus with the oito2 focus ring and\nreads as a button to assistive technologies when it has [onTap]. Use\n[Oito2ListTile.square] inside an `Oito2TileList`, whose border already\nrounds the corners.\n\nThe row is at least 40 pixels tall (52 with a subtitle) on pointer\nplatforms and 56 (72) on touch platforms.', signature: '', constructors: [ApiConstructor(name: 'Oito2ListTile', doc: 'Creates a list tile with rounded corners.\n\nThrows an [AssertionError] in debug builds when both [title] and\n[titleText], or both [subtitle] and [subtitleText], are given.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'leading', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A widget before the title, usually an icon.'), ApiParameter(name: 'title', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The primary content.'), ApiParameter(name: 'titleText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The primary text, as a shortcut for a [Text] [title].'), ApiParameter(name: 'subtitle', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The secondary content below the title.'), ApiParameter(name: 'subtitleText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The secondary text, as a shortcut for a [Text] [subtitle].'), ApiParameter(name: 'trailing', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A widget after the title, such as a switch or a chevron.'), ApiParameter(name: 'onTap', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the row is activated; without it the ro