  'Oito2Marquee': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Scrolls [child] continuously when it is longer than the space it has,\nsuch as a news ticker or a long song title.\n\nThe child moves toward the start (up when vertical), or the other way\nwith [reverse], at [speed] logical pixels per second, followed by a\ncopy after [gap]. With [pauseOnHover], it stops while the pointer or\nthe focus is on it. A tap or a click pauses it and another one resumes\nit, and it takes the keyboard focus, where Enter or Space pause and\nresume it too, so it can always be stopped. It stays still at its\nstart when animations are disabled. [fadeEdges] fades the content at\nboth ends. A child that fits doesn\'t move; while it fits or animations\nare disabled, the marquee takes neither taps nor the focus. Assistive\ntechnologies read the child once.\n\nWhile it scrolls, [child] is built twice, side by side, so it must not\nhold a [GlobalKey], and each copy keeps its own state: a plain child,\nsuch as text or icons, fits best.', signature: '', constructors: [ApiConstructor(name: 'Oito2Marquee', doc: 'Creates a marquee.\n\nThrows an [AssertionError] in debug mode when [speed] is not greater\nthan zero.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The scrolling content.'), ApiParameter(name: 'axis', type: 'Axis', isRequired: false, isNamed: true, defaultValue: 'Axis.horizontal', doc: 'The direction of the scroll.'), ApiParameter(name: 'reverse', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the content moves toward the end (down when vertical).'), ApiParameter(name: 'speed', type: 'double', isRequired: false, isNamed: true, defaultValue: '40', doc: 'The speed in logical pixels per second.'), ApiParameter(name: 'gap', type: 'double', isRequired: false, isNamed: true, defaultValue: '32', doc: 'The space between the content and its copy.'), ApiParameter(name: 'pauseOnHover', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the pointer or the focus stops the scroll while on the\nmarquee; a tap, Enter or Space pause and resume it either way.'), ApiParameter(name: 'fadeEdges', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the content fades at both ends.'), ApiParameter(name: 'fadeExtent', type: 'double', isRequired: false, isNamed: true, defaultValue: '24', doc: 'The length of the fades.')])], properties: [], methods: [], values: []),
  'Oito2MasterDetailPage': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A list of items (the master) next to the page of the selected item\n(the detail), as in settings apps.\n\nAt or above [breakpoint] wide, the master is a resizable pane beside\nthe detail. Below it, the master fills the area and selecting an item\npushes its detail page on a nested navigator; going back clears the\nselection. The selection survives switching between the two layouts.\n\nUnder an [Oito2UnsavedChangesScope], picking another item while a\nguard of the shown page has unsaved changes asks first.', signature: '', constructors: [ApiConstructor(name: 'Oito2MasterDetailPage', doc: 'Creates a master-detail page.\n\nThrows an [AssertionError] in debug mode unless exactly one of\n[length] and [controller] is given.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'length', type: 'int?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The number of items, when no [controller] is given.'), ApiParameter(name: 'controller', type: 'Oito2PageController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Controls the number of items and the selection.'), ApiParameter(name: 'tileBuilder', type: 'Oito2MasterTileBuilder', isRequired: true, isNamed: true, defaultValue: '', doc: 'Builds the master list tiles, usually [Oito2MasterTile]s.'), ApiParameter(name: 'pageBuilder', type: 'IndexedWidgetBuilder', isRequired: true, isNamed: true, defaultValue: '', doc: 'Builds the detail page of an item, usually an [Oito2DetailPage].'), ApiParameter(name: 'emptyBuilder', type: 'WidgetBuilder?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Builds the content shown when there are no items, in place of the\nlist: [masterBar] and [masterFooter] stay, so a search that matches\nnothing can still be cleared.'), ApiParameter(name: 'initialIndex', type: 'int?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The item selected at start, when no [controller] is given.'), ApiParameter(name: 'onSelected', type: 'ValueChanged<int>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the user selects an item.'), ApiParameter(name: 'breakpoint', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The width at which the master and the detail are shown side by side;\ndefaults to the theme\'s [Oito2MasterDetailThemeData], then 620.'), ApiParameter(name: 'paneSize', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The initial master pane width; defaults to the theme, then 280.'), ApiParameter(name: 'minPaneSize', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The smallest master pane width; defaults to the theme, then 180.'), ApiParameter(name: 'minPageSize', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The smallest width left for the detail page; defaults to the theme,\nthen 320.'), ApiParameter(name: 'resizable', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the master pane can be resized.'), ApiParameter(name: 'masterBar', type: 'PreferredSizeWidget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A bar above the master list, such as a title bar with a search field.'), ApiParameter(name: 'masterFooter', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A widget below the master list.')])], properties: [], methods: [], values: []),
