  'Oito2MasterListView': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'The list of an [Oito2MasterDetailPage] master pane: one tile per item,\nbuilt by [builder], with undershoot shadows at the scroll edges.\n\nIt keeps the selected tile in view: when [selectedIndex] changes, or\non first show, the list scrolls just enough to reveal it, even if it\nstarts far below the visible part.', signature: '', constructors: [ApiConstructor(name: 'Oito2MasterListView', doc: 'Creates a master list.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'length', type: 'int', isRequired: true, isNamed: true, defaultValue: '', doc: 'The number of tiles.'), ApiParameter(name: 'selectedIndex', type: 'int', isRequired: true, isNamed: true, defaultValue: '', doc: 'The selected tile, or -1 for none.'), ApiParameter(name: 'builder', type: 'Oito2MasterTileBuilder', isRequired: true, isNamed: true, defaultValue: '', doc: 'Builds a tile; [Oito2MasterTile]s take their selection and tap action\nfrom the surrounding [Oito2MasterTileScope].'), ApiParameter(name: 'onTap', type: 'ValueChanged<int>', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with the index of an activated tile.'), ApiParameter(name: 'availableWidth', type: 'double', isRequired: true, isNamed: true, defaultValue: '', doc: 'The width of the pane, passed to [builder].'), ApiParameter(name: 'padding', type: 'EdgeInsetsGeometry?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Space around the list; defaults to 8 pixels.'), ApiParameter(name: 'tileSpacing', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Space between tiles; defaults to 4 pixels.')])], properties: [], methods: [], values: []),
