  'Oito2NavigationPage': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Top-level navigation between pages that adapts to the available width\nand the input.\n\n- On touch platforms below [compactBreakpoint] wide, two or more\n  destinations are a bottom [NavigationBar].\n- Otherwise they are an [Oito2NavigationRail] at the start side:\n  compact (icons only) below [compactBreakpoint] on pointer platforms,\n  labelled up to [extendedBreakpoint], and extended (labels beside the\n  icons) from it. [railStyle] forces one style.\n\nBreakpoints, the rail color and padding and the separator default to\nthe theme\'s [Oito2NavigationPageThemeData]. The selected page fades in\nwhen it changes.\n\nUnder an [Oito2UnsavedChangesScope], picking another destination while\na guard of the shown page has unsaved changes asks first.', signature: '', constructors: [ApiConstructor(name: 'Oito2NavigationPage', doc: 'Creates a navigation page.\n\nThrows an [AssertionError] in debug mode when [items] is empty.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'items', type: 'List<Oito2NavigationItem>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The destinations, in order; at least one.\n\nA single destination is shown in a rail also where two or more would\nbe a bottom bar, since a [NavigationBar] needs two destinations.'), ApiParameter(name: 'pageBuilder', type: 'IndexedWidgetBuilder', isRequired: true, isNamed: true, defaultValue: '', doc: 'Builds the page of a destination.'), ApiParameter(name: 'controller', type: 'Oito2PageController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Controls the selected destination; its length must match [items].\n\nThrows an [AssertionError] in debug mode, when the page builds, if its\nlength differs from the number of [items].'), ApiParameter(name: 'initialIndex', type: 'int', isRequired: false, isNamed: true, defaultValue: '0', doc: 'The destination selected at start, when no [controller] is given.'), ApiParameter(name: 'onSelected', type: 'ValueChanged<int>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the user selects a destination.'), ApiParameter(name: 'leading', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A widget above the rail destinations.\n\nWith the bottom bar, it moves to the title bar of the page: an\n[Oito2WindowTitleBar] in the page shows it before the title when the\nbar has no leading widget of its own. A page with another bar reads\nit with [titleBarWidgetsOf].'), ApiParameter(name: 'trailing', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A widget below the rail destinations.\n\nWith the bottom bar, it moves to the title bar of the page: an\n[Oito2WindowTitleBar] in the page shows it after its actions. A page\nwith another bar reads it with [titleBarWidgetsOf].'), ApiParameter(name: 'compactBreakpoint', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The width below which touch layouts use a bottom bar and pointer\nlayouts a compact rail; defaults to the theme, then 600.'), ApiParameter(name: 'extendedBreakpoint', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The width at which the rail shows labels beside the icons; defaults\nto the theme, where null never extends it.'), ApiParameter(name: 'railStyle', type: 'Oito2NavigationRailStyle?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Forces a rail style instead of choosing it by width.')])], properties: [], methods: [ApiMember(name: 'titleBarWidgetsOf', signature: 'static titleBarWidgetsOf(BuildContext context) → ({Widget? leading, Widget? trailing})?', doc: 'Returns the [leading] and [trailing] widgets of the closest\n[Oito2NavigationPage] while it shows the bottom bar, for the title\nbar of its page; null while it shows the rail, which holds them, or\noutside a navigation page.')], values: []),
