  'Oito2NavigationRailItem': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A destination button of an [Oito2NavigationRail].\n\nThe selected destination sits on a rounded pill in the secondary\ncontainer color. The button shows the keyboard focus ring and reads as\na selectable button with its label to assistive technologies.', signature: '', constructors: [ApiConstructor(name: 'Oito2NavigationRailItem', doc: 'Creates a rail item.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'item', type: 'Oito2NavigationItem', isRequired: true, isNamed: true, defaultValue: '', doc: 'The destination.'), ApiParameter(name: 'selected', type: 'bool', isRequired: true, isNamed: true, defaultValue: '', doc: 'Whether the destination is selected.'), ApiParameter(name: 'onTap', type: 'VoidCallback?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called when the destination is activated.'), ApiParameter(name: 'style', type: 'Oito2NavigationRailStyle', isRequired: true, isNamed: true, defaultValue: '', doc: 'How the item is laid out.')])], properties: [], methods: [], values: []),
  'Oito2NavigationRailStyle': ApiEntry(kind: 'enum', package: 'oito2_ui', doc: 'How an [Oito2NavigationRail] shows its destinations.', signature: '', constructors: [], properties: [], methods: [], values: [ApiMember(name: 'compact', signature: '', doc: 'Icons only, with the label as a tooltip.'), ApiMember(name: 'labelled', signature: '', doc: 'Icons with a small label below.'), ApiMember(name: 'labelledExtended', signature: '', doc: 'Icons with the label beside them, in a wider rail.')]),
  'Oito2NeutralPalette': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'The neutral GTK-style surface, text and border colors of the oito2 base\nscheme, for one brightness.\n\nSurfaces go from [surfaceContainerLowest] to [surfaceContainerHighest];\n[onSurface] and [onSurfaceVariant] reach a 4.5:1 contrast ratio on all\nof them, and [outline] reaches 3:1.', signature: '', constructors: [ApiConstructor(name: 'Oito2NeutralPalette', doc: 'Creates a neutral palette from explicit colors.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'brightness', type: 'Brightness', isRequired: true, isNamed: true, defaultValue: '', doc: 'The brightness this palette is designed for.'), ApiParameter(name: 'surface', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The default surface for content.'), ApiParameter(name: 'surfaceContainerLowest', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The lowest-emphasis container surface.'), ApiParameter(name: 'surfaceContainerLow', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'A low-emphasis container surface.'), ApiParameter(name: 'surfaceContainer', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The default container surface.'), ApiParameter(name: 'surfaceContainerHigh', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'A high-emphasis container surface.'), ApiParameter(name: 'surfaceContainerHighest', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The highest-emphasis container surface.'), ApiParameter(name: 'titleBar', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The window title bar background.'), ApiParameter(name: 'onSurface', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Primary text and icons on any surface.'), ApiParameter(name: 'onSurfaceVariant', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: '