  'Oito2NumberEntry': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A number field with decrease and increase buttons, like a GNOME spin\nbutton.\n\nIt shows [value] in the locale\'s number format with [decimals]\ndecimal places. Typed text is read when the field loses focus or on\nEnter, rounded, kept between [min] and [max], and reported through\n[onChanged]; text that isn\'t a number is replaced by the current\nvalue.\n\nWhile the entry is enabled, the Up and Down arrow keys change the value\nby [step], Page Up and Page Down by [pageStep], and Home and End jump to\n[min] and [max] when they are finite. With the focus in the field the\nmouse wheel steps too, and dragging sideways on the buttons scrubs the\nvalue one [step] per 4 pixels.\n\nThe error of [validator] shows after the field loses focus, or at once\nafter its [Oito2Form] found errors. In a form, resetting it calls\n[onChanged] with the clean value.', signature: '', constructors: [ApiConstructor(name: 'Oito2NumberEntry', doc: 'Creates a number entry.\n\n[pageStep] defaults to ten times [step]. Throws an [AssertionError] in\ndebug mode when [min] is greater than [max], when [step] is not\ngreater than zero, or when [decimals] is not between 0 and 20.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'participatesInForm', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the field registers with the closest [Oito2Form], taking\npart in its validation, error summary and dirty state; true by\ndefault. When false, the field shows its own errors as outside a\nform.'), ApiParameter(name: 'value', type: 'double', isRequired: true, isNamed: true, defaultValue: '', doc: 'The current value.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<double>?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with each new value; the entry is read-only when null.'), ApiParameter(name: 'min', type: 'double', isRequired: false, isNamed: true, defaultValue: 'double.negativeInfinity', doc: 'The smallest value.'), ApiParameter(name: 'max', type: 'double', isRequired: false, isNamed: true, defaultValue: 'double.infinity', doc: 'The largest value.'), ApiParameter(name: 'step', type: 'double', isRequired: false, isNamed: true, defaultValue: '1', doc: 'The change of the arrow keys, the buttons and the wheel.'), ApiParameter(name: 'pageStep', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'decimals', type: 'int', isRequired: false, isNamed: true, defaultValue: '0', doc: 'The number of decimal places shown and kept, from 0 to 20.'), ApiParameter(name: 'labelText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The field label.'), ApiParameter(name: 'hintText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The hint shown while the field is empty.'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node; one is created when null.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the field takes the focus when shown.'), ApiParameter(name: 'validator', type: 'String? Function(double)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Checks the value and returns an error message, or null to accept\nit.')])], properties: [], methods: [], values: []),
  'Oito2OptionButton': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A small square outlined button for secondary options, such as the\nbuttons next to a list. [Oito2OptionButton.color] shows a color swatch.', signature: '', constructors: [ApiConstructor(name: 'Oito2OptionButton', doc: 'Creates an option button showing [child], with an optional\n[label] used as tooltip and accessibility label.\n\nAn [Icon] child needs a [label], since an icon alone has no name for\nassistive technologies; an [AssertionError] is thrown in debug builds\nwhen it is missing.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'onPressed', type: 'VoidCallback?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called when the button is activated; null disables it.'), ApiParameter(name: 'child', type: 'Widget?', isRequired: true, isNamed: true, defaultValue: '', doc: 'The content, usually an [Icon].'), ApiParameter(name: 'label', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The tooltip and accessibility label.')]), ApiConstructor(name: 'Oito2OptionButton.color', doc: 'Creates an option button showing a [color] swatch, named by [label].', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'onPressed', type: 'VoidCallback?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called when the button is activated; null disables it.'), ApiParameter(name: 'color', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The swatch color of [Oito2OptionButton.color].'), ApiParameter(name: 'label', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The tooltip and accessibility label.')])], properties: [], methods: [], values: []),
