  'Oito2PageIndicator': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Dots showing the current page of a carousel or a paged view.\n\nThe current page is a wider pill in the text-safe primary tone. Each\ndot is a button when [onTap] is given. When the dots don\'t fit the\navailable width, the indicator shows "page / length" text instead.', signature: '', constructors: [ApiConstructor(name: 'Oito2PageIndicator', doc: 'Creates a page indicator.\n\nThrows an [AssertionError] in debug builds when [page] is not\nbetween 0 and [length] - 1.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'length', type: 'int', isRequired: true, isNamed: true, defaultValue: '', doc: 'The number of pages.'), ApiParameter(name: 'page', type: 'int', isRequired: true, isNamed: true, defaultValue: '', doc: 'The current page, from 0.'), ApiParameter(name: 'onTap', type: 'ValueChanged<int>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the index of the activated dot; the dots are not\ninteractive when null.'), ApiParameter(name: 'dotSize', type: 'double', isRequired: false, isNamed: true, defaultValue: '8', doc: 'The diameter of the dots.'), ApiParameter(name: 'spacing', type: 'double', isRequired: false, isNamed: true, defaultValue: 'Oito2Spacing.sm', doc: 'The space between dots; [layout] may reduce it.'), ApiParameter(name: 'layout', type: 'Oito2PageIndicatorLayout', isRequired: false, isNamed: true, defaultValue: 'Oito2PageIndicatorLayout.fixed', doc: 'How the dots are spaced.'), ApiParameter(name: 'pageLabel', type: 'String Function(int, int)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Builds the accessibility label of a dot from its 1-based page number\nand the page count; defaults to [Oito2Localizations.pageOf].'), ApiParameter(name: 'minTargetSize', type: 'double', isRequired: false, isNamed: true, defaultValue: '24', doc: 'The smallest width and height of an interactive dot\'s target; the\nspacing between dots absorbs as 