  'Oito2PanedView': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Splits its area between a [pane] and a [page], separated by a divider.\n\nWhen [resizable], the divider can be dragged with the pointer or moved\nwith the arrow keys once focused, and it is exposed to assistive\ntechnologies as an adjustable control. The pane never shrinks below\n[minPaneSize] and never leaves less than [minPageSize] for the page.', signature: '', constructors: [ApiConstructor(name: 'Oito2PanedView', doc: 'Creates a paned view.\n\nThrows an [AssertionError] in debug mode when the view is laid out\nwith an unbounded extent along the split: an unbounded width for a\npane at the start or end, or an unbounded height for one at the top\nor bottom.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'pane', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The side widget, such as a list.'), ApiParameter(name: 'page', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The main widget.'), ApiParameter(name: 'paneSide', type: 'Oito2PaneSide', isRequired: false, isNamed: true, defaultValue: 'Oito2PaneSide.start', doc: 'Which side the pane is on.'), ApiParameter(name: 'initialPaneSize', type: 'double', isRequired: false, isNamed: true, defaultValue: '280', doc: 'The initial pane width (or height, when stacked vertically).'), ApiParameter(name: 'minPaneSize', type: 'double', isRequired: false, isNamed: true, defaultValue: '180', doc: 'The smallest pane size.'), ApiParameter(name: 'minPageSize', type: 'double', isRequired: false, isNamed: true, defaultValue: '320', doc: 'The smallest size left for the page.'), ApiParameter(name: 'resizable', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the divider can be moved.'), ApiParameter(name: 'onPaneSizeChanged', type: 'ValueChanged<double>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the new pane size while it is resized.'), 