  'Oito2PropertyList': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Labels and values in two aligned columns, such as the details of a\nfile or an account.\n\nLabels are muted and aligned by [labelAlign]; their column is as wide\nas the widest label, up to 40% of the width. Text values can be\nselected. A copyable property shows an [Oito2CopyButton] while the\npointer is over its row or the button has the focus, and always when\nno mouse is connected. Narrower than [stackedBelow], each label sits\nabove its value.\n\nAssistive technologies read each property as "label: value".', signature: '', constructors: [ApiConstructor(name: 'Oito2PropertyList', doc: 'Creates a list of [properties] without groups.', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'properties', type: 'List<Oito2Property>', isRequired: true, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'labelAlign', type: 'TextAlign', isRequired: false, isNamed: true, defaultValue: 'TextAlign.start', doc: 'How labels align in their column: [TextAlign.start] or\n[TextAlign.end].'), ApiParameter(name: 'stackedBelow', type: 'double', isRequired: false, isNamed: true, defaultValue: '360', doc: 'The width below which labels stack above their values.')]), ApiConstructor(name: 'Oito2PropertyList.grouped', doc: 'Creates a list of [groups], each under its optional heading.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'groups', type: 'List<Oito2PropertyGroup>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The groups of properties.'), ApiParameter(name: 'labelAlign', type: 'TextAlign', isRequired: false, isNamed: true, defaultValue: 'TextAlign.start', doc: 'How labels align in their column: [TextAlign.start] or\n[TextAlign.end].'), ApiParameter(name: 'stackedBelow', type: 'double', isRequired: false, isNamed: true, defaultValue: '360', doc: 'The width below which labels stack above their values.')])], properties: [], methods: [], values: []),
