  'Oito2ScrollArea': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A scrollable box for a [child] larger than it, with the themed scroll\nbars on the axes it scrolls in.\n\nThe bars show while scrolling or, with [thumbVisibility], all the time.\nWith [undershoot], an [Oito2ScrollViewUndershoot] shadow marks the\nedges with more content beyond them; with\n[Oito2ScrollDirection.both], the shadows follow the vertical axis.', signature: '', constructors: [ApiConstructor(name: 'Oito2ScrollArea', doc: 'Creates a scroll area.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The content.'), ApiParameter(name: 'direction', type: 'Oito2ScrollDirection', isRequired: false, isNamed: true, defaultValue: 'Oito2ScrollDirection.vertical', doc: 'The directions the content scrolls in.'), ApiParameter(name: 'verticalController', type: 'ScrollController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The controller of the vertical scroll position; one is created when\nnull.'), ApiParameter(name: 'horizontalController', type: 'ScrollController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The controller of the horizontal scroll position; one is created when\nnull.'), ApiParameter(name: 'thumbVisibility', type: 'bool?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Whether the scroll bars always show; null follows the scroll bar\ntheme.'), ApiParameter(name: 'undershoot', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether a soft shadow marks the edges with more content beyond them.'), ApiParameter(name: 'padding', type: 'EdgeInsetsGeometry?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The space around [child], inside the scrolled content.')])], properties: [], methods: [], values: []),
  'Oito2ScrollDirection': ApiEntry(kind: 'enum', package: 'oito2_ui', doc: 'The directions an [Oito2ScrollArea] scrolls in.', signature: '', constructors: [], properties: [], methods: [], values: [ApiMember(name: 'vertical', signature: '', doc: 'Up and down.'), ApiMember(name: 'horizontal', signature: '', doc: 'Left and right.'), ApiMember(name: 'both', signature: '', doc: 'Both ways, with a scroll bar on each axis.')]),
  'Oito2ScrollViewUndershoot': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Fades a soft shadow in at the start and end edges of a scrollable\n[child] while there is more content beyond them.\n\nWorks with any scroll view below it; no controller is needed. With\n[pointerScrolling], a horizontal scroll view also scrolls with the\nvertical mouse wheel and with mouse drags, which Flutter leaves to\nShift+wheel and touch by default.', signature: '', constructors: [ApiConstructor(name: 'Oito2ScrollViewUndershoot', doc: 'Creates a scroll undershoot.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The scroll view.'), ApiParameter(name: 'start', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the shadow at the start edge is shown.'), ApiParameter(name: 'end', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the shadow at the end edge is shown.'), ApiParameter(name: 'extent', type: 'double', isRequired: false, isNamed: true, defaultValue: 'Oito2Spacing.md', doc: 'The depth of the shadows, in logical pixels.'), ApiParameter(name: 'pointerScrolling', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether a horizontal scroll view below scrolls with the vertical\nmouse wheel and with mouse drags.')])], properties: [], methods: [], values: []),
  'Oito2SearchField': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A search text field with a search icon and a clear button that appears\nwhile it has text.\n\nPressing Escape clears the text; pressing it again on an empty field\ncalls [onEscape], or lets the key reach the ancestors when [onEscape]\nis null. The hint and the clear button tooltip come from\n`MaterialLocalizations`, so they follow the app language.\n\nThe error of [validator] or [required] shows under the field after it\nloses focus, or at once after its [Oito2Form] found errors.', signature: '', constructors: [ApiConstructor(name: 'Oito2SearchField', doc: 'Creates a search field.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'participatesInForm', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the field registers with the closest [Oito2Form], taking\npart in its validation, error summary and dirty state; false by\ndefault, since a search usually filters the screen rather than\nholding form data. When false, the field shows its own errors as\noutside a form.'), ApiParameter(name: 'controller', type: 'TextEditingController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Controls the text; one is created when null.'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node of the text field.'), ApiParameter(name: 'hintText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The hint; defaults to the localized "Search".'), ApiParameter(name: 'onChanged', type: 'ValueChanged<String>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called whenever the text changes.'), ApiParameter(name: 'onSubmitted', type: 'ValueChanged<String>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the user submits the text.'), ApiParameter(name: 'onClear', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called after the clear button or Escape empties the field.'), ApiParameter(name: 'onEscape', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when Escape is pressed on an empty field.\n\nWhen null, Escape on an empty field is not handled by the field and\nreaches the ancestors, so an enclosing dialog, popover or sheet can\nclose.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the field takes focus when shown.'), ApiParameter(name: 'prefixIcon', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The widget before the text; defaults to a search icon.'), ApiParameter(name: 'validator', type: 'String? Function(String)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Checks the text and returns an error message, or null to accept it.'), ApiParameter(name: 'required', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether an empty field shows the localized "This field is required"\nerror; a text of only spaces counts as empty.')])], properties: [], methods: [], values: []),
  'Oito2SearchTitleField': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A title bar element that switches between a [title] and a search\nfield, with a toggle button, as in GNOME apps.\n\nThe element keeps the same size in both states: a box [fieldWidth]\nwide and as tall as a field, with the toggle button at its start.\nWhile the search is closed, the [title] follows the button; while it\nis open, the search field fills the box and the button serves as its\nsearch icon. Only the content fades, so the surrounding layout never\nmoves.\n\nEscape on an empty field closes the search and returns focus to the\ntoggle button. The toggle button reports its pressed state to\nassistive technologies.', signature: '', constructors: [ApiConstructor(name: 'Oito2SearchTitleField', doc: 'Creates a search title field.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'title', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'Shown while the search is closed.'), ApiParameter(name: 'searchActive', type: 'bool', isRequired: true, isNamed: true, defaultValue: '', doc: 'Whether the search field is shown.'), ApiParameter(name: 'onSearchActiveChanged', type: 'ValueChanged<bool>', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called to open or close the search.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<String>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called whenever the search text changes.'), ApiParameter(name: 'onSubmitted', type: 'ValueChanged<String>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the user submits the search text.'), ApiParameter(name: 'controller', type: 'TextEditingController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Controls the search text.'), ApiParameter(name: 'hintText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The search hint; defaults to the localized "Search".'), ApiParameter(name: 'fieldWidth', type: 'double', isRequired: false, isNamed: true, defaultValue: '260', doc: 'The width of the element, in both states.'), ApiParameter(name: 'toggleLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The tooltip of the toggle button; defaults to the localized\n"Search".')])], properties: [], methods: [], values: []),
