  'Oito2SegmentGroup': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A row (or column) of mutually exclusive choices on a recessed track,\nwith a raised marker that slides to the selected one.\n\nThe group is one stop in keyboard navigation: the arrow keys select the\nprevious or next enabled segment, wrapping at the ends, and Space or\nEnter selects the focused one. Assistive technologies read it as a\ngroup of radio buttons.', signature: '', constructors: [ApiConstructor(name: 'Oito2SegmentGroup', doc: 'Creates a segment group.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'segments', type: 'List<Oito2Segment<T>>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The choices, in order.'), ApiParameter(name: 'selected', type: 'T?', isRequired: true, isNamed: true, defaultValue: '', doc: 'The value of the selected segment, or null.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<T>?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with the value of a segment chosen; null disables the group.'), ApiParameter(name: 'orientation', type: 'Axis', isRequired: false, isNamed: true, defaultValue: 'Axis.horizontal', doc: 'Whether the segments run across or down.')])], properties: [], methods: [], values: []),
  'Oito2SegmentedEntry': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A row of short text fields joined by a [delimiter], for values like\nIP addresses or license keys.\n\nFocus moves to the next segment when one fills up or when the first\nvisible character of the delimiter is typed, and back to the previous\none on Backspace in an empty segment or on the arrow toward the start\nof the reading direction (the left arrow in left-to-right text) at its\nstart.\n\nWith [validator] or [required], an error shows below the segments once\nthe focus leaves the entry, or at once after its [Oito2Form] found\nerrors.', signature: '', constructors: [ApiConstructor(name: 'Oito2SegmentedEntry', doc: 'Creates a segmented entry.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'participatesInForm', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the field registers with the closest [Oito2Form], taking\npart in its validation, error summary and dirty state; true by\ndefault. When false, the field shows its own errors as outside a\nform.'), ApiParameter(name: 'segments', type: 'List<Oito2EntrySegment>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The segments, in order.'), ApiParameter(name: 'delimiter', type: 'String', isRequired: false, isNamed: true, defaultValue: '\'.\'', doc: 'The text drawn between segments; typing its first visible character,\nsuch as `-` for `\' - \'`, advances focus.'), ApiParameter(name: 'initialValues', type: 'List<String>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The text of each segment at start.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<List<String>>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the text of every segment whenever one changes.'), ApiParameter(name: 'validator', type: 'String? Function(List<String>)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Checks the text of every segment and returns an err