  'Oito2SelectionMode': ApiEntry(kind: 'enum', package: 'oito2_ui', doc: 'How many items an [Oito2SelectionController] can select.', signature: '', constructors: [], properties: [], methods: [], values: [ApiMember(name: 'none', signature: '', doc: 'Nothing can be selected.'), ApiMember(name: 'single', signature: '', doc: 'One item at most.'), ApiMember(name: 'multiple', signature: '', doc: 'Any number of items.')]),
  'Oito2SemanticColors': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Text-safe accent and status colors of an oito2 scheme.\n\nEvery color reaches at least a 4.5:1 contrast ratio (7:1 in a\nhigh-contrast scheme) against every surface of the scheme it belongs\nto, so it can color text, links, icons and focus indicators. The\n`ColorScheme.primary` and `ColorScheme.error` fills keep the scheme\'s\nown colors, which may not reach that ratio.', signature: '', constructors: [ApiConstructor(name: 'Oito2SemanticColors', doc: 'Creates semantic colors from explicit values.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'primaryText', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The primary accent hue, adjusted for text on surfaces.'), ApiParameter(name: 'errorText', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The error hue, adjusted for text on surfaces, such as validation\nmessages.'), ApiParameter(name: 'success', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Successful or positive outcomes.'), ApiParameter(name: 'warning', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Warnings that need attention.'), ApiParameter(name: 'info', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Neutral information.'), ApiParameter(name: 'link', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Hyperlinks.')])], properties: [], methods: [ApiMember(name: 'maybeOf', signature: 'static maybeOf(BuildContext context) → Oito2SemanticColors?', doc: 'Returns the semantic colors of the closest [Theme], or null when the\ntheme has none.')], values: []),
