  'Oito2ShortcutLabel': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Shows a keyboard shortcut as key caps, in the notation of the\nplatform: `⇧⌘K` on macOS and iOS, `Ctrl` `Shift` `K` elsewhere.\n\nAssistive technologies read the shortcut as text, such as\n"Ctrl+Shift+K".', signature: '', constructors: [ApiConstructor(name: 'Oito2ShortcutLabel', doc: 'Creates a shortcut label.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'shortcut', type: 'Oito2Shortcut', isRequired: true, isNamed: false, defaultValue: '', doc: 'The shortcut to show.'), ApiParameter(name: 'platform', type: 'TargetPlatform?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The platform whose notation is used; defaults to the theme\'s\n[ThemeData.platform].')])], properties: [], methods: [], values: []),
  'Oito2ShortcutRecorder': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A field that records a single-chord keyboard shortcut, as in keyboard\nsettings.\n\nClicking it, or pressing Enter or Space while it has focus, starts\nrecording; the next key with its modifiers becomes the shortcut. Escape\ncancels, and Backspace or Delete without modifiers clears the shortcut.\nA Command (Apple platforms) or Control (elsewhere) chord is stored with\nthe platform-neutral primary modifier, so it reads naturally on every\nplatform.', signature: '', constructors: [ApiConstructor(name: 'Oito2ShortcutRecorder', doc: 'Creates a shortcut recorder.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'value', type: 'Oito2Shortcut?', isRequired: true, isNamed: true, defaultValue: '', doc: 'The recorded shortcut, or null.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<Oito2Shortcut?>?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with the new shortcut, or null when it is cleared; the\nrecorder is disabled when this is null.'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node of the recording field; one is created and owned by\nthe recorder when null.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the recorder takes focus when first shown.')])], properties: [], methods: [], values: []),
  'Oito2ShortcutsHelpView': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'The searchable list of keyboard shortcuts that\n[showOito2ShortcutsHelp] shows in a dialog, for embedding in a page\nsuch as the app settings.\n\nEach command with a shortcut is a row with its label, its description\nand its shortcuts as [Oito2ShortcutLabel]s, under the heading of its\n[Oito2Command.group]; commands without a group go under the localized\n"General". Groups follow the order in which they first appear, and\nrows the order of [commands]. Disabled commands stay in place, dimmed,\nand assistive technologies read them as disabled. At least\n[wideWidth] wide, the groups flow into two columns.\n\nTyping in the search field keeps the commands whose label,\ndescription, group, keywords and key names (as shown, such as `Ctrl`\nor `F1`) contain every typed word, ignoring case and accents, and\nhighlights the matches in the labels and descriptions.\n\nThe Down arrow moves the focus from the search field to the first row\nand on to the next rows, the Up arrow back to the previous row and to\nthe search field, and Tab through the rows in the same order. Each row\nreads as its label and shortcuts, such as "Open settings, shortcut\nCtrl+,", with the description as its hint.\n\nWith a bounded height the rows scroll below the search field;\notherwise the view takes the height of all its rows.', signature: '', constructors: [ApiConstructor(name: 'Oito2ShortcutsHelpView', doc: 'Creates a shortcuts help view.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'commands', type: 'Iterable<Oito2Command>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The commands to list; defaults to those available at the view,\ndisabled ones included (see [Oito2Commands.availableAt]). Commands\nwithout a shortcut are left out.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the search field takes the focus when first shown.'), ApiParameter(name: 'onEscape', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when Escape is pressed on an empty search field or on a row.')])], properties: [ApiMember(name: 'wideWidth', signature: 'static double', doc: 'The narrowest width that shows two columns.')], methods: [], values: []),
