  'Oito2Skeleton': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A placeholder shape shown while content loads: lines of text, a\ncircle such as an avatar, or a rectangle such as an image.\n\nIt is filled with the scheme\'s highest surface container tone and\npulses gently; it stands still when animations are disabled. It has\nno semantics of its own: wrap a group of skeletons in an\n[Oito2SkeletonSwitcher], which announces "Loading" once for the group\nand swaps in the content when it is ready.', signature: '', constructors: [ApiConstructor(name: 'Oito2Skeleton.text', doc: 'Creates [lines] lines of text [lineHeight] tall that fill the\navailable width, 200 pixels when it is unbounded; with more than one\nline, the last one takes [lastLineWidthFactor] of the width.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'lines', type: 'int', isRequired: false, isNamed: true, defaultValue: '1', doc: 'The number of text lines.'), ApiParameter(name: 'lineHeight', type: 'double', isRequired: false, isNamed: true, defaultValue: '12', doc: 'The height of each text line.'), ApiParameter(name: 'lastLineWidthFactor', type: 'double', isRequired: false, isNamed: true, defaultValue: '0.6', doc: 'The fraction of the width the last text line takes when there is\nmore than one line.')]), ApiConstructor(name: 'Oito2Skeleton.circle', doc: 'Creates a circle [size] pixels across, such as an avatar.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'size', type: 'double', isRequired: false, isNamed: true, defaultValue: '40', doc: '')]), ApiConstructor(name: 'Oito2Skeleton.rect', doc: 'Creates a rectangle [width] by [height] with [borderRadius]\ncorners; without a [width] it fills the available width, 200 pixels\nwhen it is unbounded.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'width', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The width of a circle or a rectangle; null fills the available\nwidth.')