  'Oito2Sparkline': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A small, static chart of a series of values, such as a transfer speed\nover the last minute or the usage of a resource over time.\n\nThe values are drawn evenly spaced from the start to the end edge\n(right to left in right-to-left text) as a [Oito2SparklineType.line],\nan [Oito2SparklineType.area] or [Oito2SparklineType.bars]. The vertical\nrange runs from [min] to [max], which default to the lowest and highest\nvalues; bars default to a range that also includes zero. The area and\nthe bars start from zero, or from the range edge closest to zero when\nzero is outside the range. Values outside an explicit range are drawn\nat its edge.\n\nValues that aren\'t finite (NaN and the infinities) are skipped: the\nline joins the finite values around them and their bar is left empty.\nWithout finite values nothing is drawn. One value draws a dot or a\nsingle bar, and equal values a flat line across the middle.\n\n[showMin], [showMax] and [showLast] mark the first lowest, the first\nhighest and the last finite value with a dot.\n\nThe color is [color], or else the [tone] color of the theme raised to\n3:1 against the surface, or else the primary fill of selected controls.\n\nThe sparkline isn\'t interactive and doesn\'t take focus. Assistive\ntechnologies read one label with a summary of the values (minimum,\nmaximum, last value and trend, from [Oito2SparklineStats]), each\nformatted by [formatValue], after [semanticsLabel] when it is set, such\nas "Download speed, minimum 1.2 MB/s, maximum 8 MB/s, last 6.5 MB/s,\nrising". It doesn\'t animate value changes.', signature: '', constructors: [ApiConstructor(name: 'Oito2Sparkline', doc: 'Creates a sparkline of [values].\n\nThrows an [AssertionError] in debug mode when [min] or [max] is NaN\nor infinite, when [strokeWidth] isn\'t positive, or when [height] or\n[trendThreshold] is negative.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'values', type: 'List<double>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The values, oldest first.'), ApiParameter(name: 'type', type: 'Oito2SparklineType', isRequired: false, isNamed: true, defaultValue: 'Oito2SparklineType.line', doc: 'How the values are drawn.'), ApiParameter(name: 'tone', type: 'Oito2InfoType?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The semantic tone of the color, or null for the primary color.'), ApiParameter(name: 'color', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The color, used as is; overrides [tone].'), ApiParameter(name: 'min', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The value drawn at the bottom edge; defaults to the lowest value, or\nto zero for bars when it is lower.'), ApiParameter(name: 'max', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The value drawn at the top edge; defaults to the highest value, or\nto zero for bars when it is higher.'), ApiParameter(name: 'showMin', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether a dot marks the first lowest value.'), ApiParameter(name: 'showMax', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether a dot marks the first highest value.'), ApiParameter(name: 'showLast', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether a dot marks the last finite value.'), ApiParameter(name: 'strokeWidth', type: 'double', isRequired: false, isNamed: true, defaultValue: '2', doc: 'The thickness of the line.'), ApiParameter(name: 'width', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The width; when null, the sparkline fills the width the parent\nallows, or [defaultWidth] when the parent doesn\'t bound it.'), ApiParameter(name: 'height', type: 'double', isRequired: false, isNamed: true, defaultValue: '32', doc: 'The height.'), ApiParameter(name: 'formatValue', type: 'String Function(BuildContext, double)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Formats each value in the accessibility summary, such as\n"12 MB/s"; when null, values are numbers of the locale.'), ApiParameter(name: 'semanticsLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'What the values measure, read before the summary, such as\n"Download speed".'), ApiParameter(name: 'trendThreshold', type: 'double', isRequired: false, isNamed: true, defaultValue: 'Oito2SparklineStats.defaultTrendThreshold', doc: 'The trend threshold, as a fraction of the range of the values; see\n[Oito2SparklineStats.trendOf].')])], properties: [ApiMember(name: 'defaultWidth', signature: 'static double', doc: 'The width used when the parent doesn\'t bound it and [width] is null.')], methods: [], values: []),
  'Oito2SparklineStats': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'The minimum, maximum, first and last finite values of a series and its\ntrend, as an [Oito2Sparkline] summarizes them.\n\nValues that aren\'t finite (NaN and the infinities) are skipped: they\ncount for nothing here and an [Oito2Sparkline] draws nothing for them.', signature: '', constructors: [ApiConstructor(name: 'Oito2SparklineStats', doc: 'Creates the statistics of a series; [of] computes them from values.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'count', type: 'int', isRequired: true, isNamed: true, defaultValue: '', doc: 'The number of finite values.'), ApiParameter(name: 'min', type: 'double', isRequired: true, isNamed: true, defaultValue: '', doc: 'The lowest finite value.'), ApiParameter(name: 'max', type: 'double', isRequired: true, isNamed: true, defaultValue: '', doc: 'The highest finite value.'), ApiParameter(name: 'first', type: 'double', isRequired: true, isNamed: true, defaultValue: '', doc: 'The first finite value.'), ApiParameter(name: 'last', type: 'double', isRequired: true, isNamed: true, defaultValue: '', doc: 'The last finite value.'), ApiParameter(name: 'minIndex', type: 'int', isRequired: true, isNamed: true, defaultValue: '', doc: 'The position of the first [min] in the values.'), ApiParameter(name: 'maxIndex', type: 'int', isRequired: true, isNamed: true, defaultValue: '', doc: 'The position of the first [max] in the values.'), ApiParameter(name: 'lastIndex', type: 'int', isRequired: true, isNamed: true, defaultValue: '', doc: 'The position of [last] in the values.'), ApiParameter(name: 'trend', type: 'Oito2SparklineTrend', isRequired: true, isNamed: true, defaultValue: '', doc: 'The direction from [first] to [last].')])], properties: [ApiMember(name: 'defaultTrendThreshold', signature: 'static double', doc: 'The default trend threshold: a tenth of the range of the values.')], methods: [ApiMember(name: 'of', signature: 'static of(List<double> values, double trendThreshold) → Oito2SparklineStats?', doc: 'Returns the statistics of the finite [values], or null when none is\nfinite, with the trend from [trendOf] at [trendThreshold].\n\nThe indexes are positions in [values]; [minIndex] and [maxIndex] are\nthe first occurrences of the minimum and maximum.'), ApiMember(name: 'trendOf', signature: 'static trendOf(double first, double last, double min, double max, double threshold) → Oito2SparklineTrend', doc: 'Returns the trend of a series from its [first] to its [last] value,\nmeasured against its range from [min] to [max].\n\nThe series is [Oito2SparklineTrend.rising] when the last value\nexceeds the first by more than [threshold] times the range,\n[Oito2SparklineTrend.falling] when it is below the first by more\nthan that, and [Oito2SparklineTrend.steady] otherwise, which\nincludes a range of zero (one value, or all values equal). Being\nrelative to the range, the trend doesn\'t depend on the unit or the\nsign of the values.'), ApiMember(name: 'describe', signature: 'describe(Oito2Localizations strings, String Function(double)? format) → String', doc: 'Returns the text summary of the series in [strings], with each value\npassed through [format]: "Value 5" for one value, otherwise the\nminimum, maximum, last value and trend, such as "Minimum 3,\nmaximum 12, last 8, rising".\n\nWithout [format], values are decimal numbers of the locale of\n[strings].')], values: []),
  'Oito2SparklineTrend': ApiEntry(kind: 'enum', package: 'oito2_ui', doc: 'The direction of a series from its first to its last value.', signature: '', constructors: [], properties: [], methods: [], values: [ApiMember(name: 'rising', signature: '', doc: 'The last value is higher than the first by more than the threshold.'), ApiMember(name: 'steady', signature: '', doc: 'The first and last values are within the threshold of each other.'), ApiMember(name: 'falling', signature: '', doc: 'The last value is lower than the first by more than the threshold.')]),
