  'Oito2Splitter': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Panes side by side, or stacked when [axis] is vertical, with a\ndraggable divider between each two.\n\nA divider keeps both of its panes within their limits. From the\nkeyboard a focused divider moves by [keyboardStep] with the arrow\nkeys, Home and End take the pane before it to its smallest and largest\nsize, and Enter or Space collapses or restores the collapsible pane\nnext to it, as a double click does. Splitters nest. For a single\nresizable side pane, `Oito2PanedView` is simpler.', signature: '', constructors: [ApiConstructor(name: 'Oito2Splitter', doc: 'Creates a splitter.\n\nThrows an [AssertionError] in debug mode, when the splitter is first\nbuilt, if [panes] has fewer than two entries, and when it is laid out\nwith an unbounded extent along [axis], such as directly in a [Row]\nfor a horizontal splitter.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'panes', type: 'List<Oito2SplitterPane>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The panes, from the start (top when vertical); two or more.'), ApiParameter(name: 'axis', type: 'Axis', isRequired: false, isNamed: true, defaultValue: 'Axis.horizontal', doc: 'Whether the panes sit side by side or stacked.'), ApiParameter(name: 'onSizesChanged', type: 'ValueChanged<List<double>>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the pane sizes in logical pixels after a change.'), ApiParameter(name: 'keyboardStep', type: 'double', isRequired: false, isNamed: true, defaultValue: '16', doc: 'The change of one arrow key press.'), ApiParameter(name: 'resizeLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label of the dividers; defaults to the localized\n"Resize pane".')])], properties: [], methods: [], values: []),
