  'Oito2StatusPage': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A centered message for a page or pane without content to show, such\nas an empty folder, no search results or a failed load: a large\n[icon], a [title], a [description] and [actions].\n\nIt fills the available space and centers its content, which scrolls\nwhen it doesn\'t fit. [compact] uses a smaller icon and title, for\nsidebars and small panes.', signature: '', constructors: [ApiConstructor(name: 'Oito2StatusPage', doc: 'Creates a status page.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'title', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The headline, usually a [Text]; read as a header by assistive\ntechnologies.'), ApiParameter(name: 'icon', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The large icon above the title, usually an [Icon].'), ApiParameter(name: 'description', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The text below the title that explains the state or what to do.'), ApiParameter(name: 'actions', type: 'List<Widget>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: 'Buttons below the description, such as "Retry" or "New file".'), ApiParameter(name: 'child', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Extra content below the actions.'), ApiParameter(name: 'compact', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the page uses a smaller icon, title and spacing.')])], properties: [], methods: [], values: []),
