  'Oito2StatusPill': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A compact rounded label for the state of an item, such as "Synced" or\n"Offline", with a dot or an icon before the text.\n\nThe [type] tints it with a semantic color; without one it is neutral,\nin the surface tones. With [busy], a small spinner takes the place of\nthe dot or icon; it stands still when animations are disabled.\n\nAssistive technologies read [label], or [semanticLabel] when given,\nwith "Loading" as its value while [busy] and [tooltip] as a hint.', signature: '', constructors: [ApiConstructor(name: 'Oito2StatusPill', doc: 'Creates a status pill.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'label', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The status text.'), ApiParameter(name: 'type', type: 'Oito2InfoType?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The kind of status, which picks the color; neutral when null.'), ApiParameter(name: 'icon', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'An icon shown instead of the dot, usually an [Icon].'), ApiParameter(name: 'busy', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the status is in progress, shown by a spinner.'), ApiParameter(name: 'tooltip', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A message shown when the pointer rests on the pill or it is long\npressed, such as the time of the last sync.'), ApiParameter(name: 'semanticLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label; defaults to [label].')])], properties: [], methods: [], values: []),
