  'Oito2SystemSettings': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'The operating system preferences that shape an `oito2_ui` app: platform,\ndesktop environment, window controls, accent color, color scheme,\ncontrast, motion, text scaling and cursor size.\n\n[Oito2SystemSettings.fallback] derives every value from the platform\nalone. The `oito2_ui_settings` package reads the real values from the\noperating system.', signature: '', constructors: [ApiConstructor(name: 'Oito2SystemSettings', doc: 'Creates system settings from explicit values.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'platform', type: 'Oito2Platform', isRequired: true, isNamed: true, defaultValue: '', doc: 'The platform the app runs on.'), ApiParameter(name: 'windowControlStyle', type: 'Oito2WindowControlStyle', isRequired: true, isNamed: true, defaultValue: '', doc: 'The visual family of the window control buttons.'), ApiParameter(name: 'windowButtonLayout', type: 'Oito2WindowButtonLayout', isRequired: true, isNamed: true, defaultValue: '', doc: 'The order and side of the window control buttons.'), ApiParameter(name: 'desktopEnvironment', type: 'Oito2DesktopEnvironment?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The Linux desktop environment, or null outside native Linux.'), ApiParameter(name: 'accentColor', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The system accent color, or null when the system has none or it is\nunknown.'), ApiParameter(name: 'colorScheme', type: 'Brightness?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The light or dark scheme the system asks for, or null when it states\nno preference or the preference is unknown.'), ApiParameter(name: 'highContrast', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the system asks for high contrast.'), ApiParameter(name: 'reduceMotion', type: 'bool?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Wheth