  'Oito2TabBar': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A row of tabs with a rounded marker behind the selected one, a pill as\nin GNOME view switchers by default.\n\nIt drives a [TabController] like Material\'s `TabBar`: the [controller]\ngiven, or the closest `DefaultTabController`. The marker slides between\ntabs; [style] picks its look. Throws a [FlutterError] in debug builds\nwhen neither [controller] nor a `DefaultTabController` is available.', signature: '', constructors: [ApiConstructor(name: 'Oito2TabBar', doc: 'Creates a tab bar.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'tabs', type: 'List<Widget>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The tabs, usually [Oito2Tab]s.'), ApiParameter(name: 'controller', type: 'TabController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The tab controller; defaults to the closest `DefaultTabController`.'), ApiParameter(name: 'onTap', type: 'ValueChanged<int>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the index of a tapped tab.'), ApiParameter(name: 'isScrollable', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the tabs keep their own width and scroll, instead of sharing\nthe bar width equally. The [Oito2TabBarStyle.subtle] style always\nscrolls, whatever this value.'), ApiParameter(name: 'tabHeight', type: 'double', isRequired: false, isNamed: true, defaultValue: 'Oito2Sizes.minTouchTarget', doc: 'The tab height that [preferredSize] reserves: the 48-pixel touch\ntarget by default, which fits every platform. 36 pixels, the\n[Oito2Sizes.buttonHeight] and the indicator space, fit pointer\nplatforms exactly. The tabs size themselves from the theme\'s tap\ntarget size, not from this value.'), ApiParameter(name: 'style', type: 'Oito2TabBarStyle', isRequired: false, isNamed: true, defaultValue: 'Oito2TabBarStyle.pill', doc: 'The look of the selected tab marker.')])], properties: [], methods: []