  'Oito2TableColumn': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A column of a widget that shows rows of type [R] in columns, such as\nan [Oito2DataTable], or an [Oito2TreeView] with columns, where [R] is\nthe tree\'s node type.\n\nThe column has a header [label] and builds each row\'s cell with\n[cellBuilder].', signature: '', constructors: [ApiConstructor(name: 'Oito2TableColumn', doc: 'Creates a column.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'id', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The column\'s identifier, reported when it is resized.'), ApiParameter(name: 'label', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The text of the column header.'), ApiParameter(name: 'width', type: 'Oito2ColumnWidth', isRequired: false, isNamed: true, defaultValue: 'const Oito2ColumnWidth.flex(1)', doc: 'The width of the column.'), ApiParameter(name: 'alignment', type: 'AlignmentGeometry', isRequired: false, isNamed: true, defaultValue: 'AlignmentDirectional.centerStart', doc: 'How the header label and the cells are aligned in the column.'), ApiParameter(name: 'resizable', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the header has a handle that resizes the column.'), ApiParameter(name: 'sortable', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether a click on the header sorts by this column, in a widget that\nsorts, such as an [Oito2DataTable].'), ApiParameter(name: 'cellBuilder', type: 'Widget Function(BuildContext, R)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Builds the cell of a row; the cell is empty when null, except where\nthe widget showing the column documents a default content.'), ApiParameter(name: 'tooltip', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The tooltip of the column header.'), ApiParameter(name: 'hideable', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the user can hide the column, in a widget that lets the user\nchoose the columns, such as an [Oito2DataTable] with\n[Oito2DataTable.onHiddenColumnsChanged].')])], properties: [ApiMember(name: 'minResizeWidth', signature: 'static double', doc: 'The narrowest a resize makes any column, in logical pixels.')], methods: [ApiMember(name: 'resolveWidths', signature: 'static resolveWidths(List<Oito2TableColumn<R>> columns, double available, Map<String, double> overrides) → List<double>', doc: 'Returns the width of each of [columns] that fits in [available]\nlogical pixels: fixed columns keep their width, or the one in\n[overrides] by column id, and flexible ones share what is left,\neach at least its minimum.')], values: []),
  'Oito2TableOfContents': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A list of the sections of a scroll view that highlights the section in\nview and scrolls to a section when it is picked.\n\nThe current section is the last one whose heading has reached\n[activationOffset] pixels below the top of the viewport, or the last\nsection when the view is scrolled to the end. [controller] must be the\ncontroller of the scroll view that holds the [Oito2TocEntry.target]s.\n\nIn a lazily built scroll view, only built headings are measured: while\nnone is built the current section stays as it was, and picking a\nsection whose heading isn\'t built only calls [onSelected], which can\nscroll there.', signature: '', constructors: [ApiConstructor(name: 'Oito2TableOfContents', doc: 'Creates a table of contents.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'entries', type: 'List<Oito2TocEntry>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The sections, in document order.'), ApiParameter(name: 'controller', type: 'ScrollController', isRequired: true, isNamed: true, defaultValue: '', doc: 'The controller of the scroll view the sections are in.'), ApiParameter(name: 'activationOffset', type: 'double', isRequired: false, isNamed: true, defaultValue: '32', doc: 'How far below the top of the viewport, in logical pixels, a heading\nmakes its section current.'), ApiParameter(name: 'onSelected', type: 'ValueChanged<int>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the index of a picked section, before the view starts\nscrolling to it.')])], properties: [], methods: [], values: []),
  'Oito2TagsField': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A field of tags shown as chips, with a text input after them.\n\nEnter or a [delimiters] character adds the typed text, trimmed, as a\ntag; a pasted list is split on the delimiters. A tag is refused when it\nis empty, repeated (unless [allowDuplicates]), past [maxTags] or\nrejected by [tagValidator]. A typed tag that is refused stays in the input\nto be fixed; the refused tags of a pasted list are dropped.\n\nBackspace in the empty input, or the start arrow with the caret at the\nstart of the input, moves to the last tag; the arrow keys move between\ntags, and Backspace or Delete removes the\nfocused one. With [suggestions], matching items not yet added show\nbelow the input as it is typed. With [clearable], a button at the end\nremoves every tag at once.\n\nThe error of [validator] or [required] shows under the field after\nit loses focus, or at once after its [Oito2Form] found errors. In a\nform, resetting it calls [onChanged] with the clean tags.', signature: '', constructors: [ApiConstructor(name: 'Oito2TagsField', doc: 'Creates a tags field.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'participatesInForm', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the field registers with the closest [Oito2Form], taking\npart in its validation, error summary and dirty state; true by\ndefault. When false, the field shows its own errors as outside a\nform.'), ApiParameter(name: 'tags', type: 'List<String>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The tags, in order.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<List<String>>?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with the new tag list after tags are added or removed; the\nfield is read-only when null.'), ApiParameter(name: 'delimiters', type: 'List<String>', isRequired: false, isNamed: true, defaultValue: 'const [\',\']', doc: 'The strings that end a tag while typing or pasting; when empty, only\nEnter adds a tag.'), ApiParameter(name: 'maxTags', type: 'int?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The largest number of tags; once reached, the input turns read-only.\nUnlimited when null.'), ApiParameter(name: 'tagValidator', type: 'bool Function(String)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Decides whether a trimmed, non-empty tag is accepted; every such tag\nis accepted when null.'), ApiParameter(name: 'allowDuplicates', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the same tag can be added twice.'), ApiParameter(name: 'labelText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The field label.'), ApiParameter(name: 'hintText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The hint shown in the input while there are no tags.'), ApiParameter(name: 'suggestions', type: 'Oito2ListCollection<String>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The tags offered below the input while typing, excluding the tags\nalready added; no suggestions are shown when null.'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node of the text input; one is created when null.'), ApiParameter(name: 'style', type: 'Oito2TagsFieldStyle', isRequired: false, isNamed: true, defaultValue: 'Oito2TagsFieldStyle.filled', doc: 'The look of the tags.'), ApiParameter(name: 'clearable', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether a button at the end of the field removes every tag while the\nfield is editable and has tags.'), ApiParameter(name: 'validator', type: 'String? Function(List<String>)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Checks the whole tag list and returns an error message, or null to\naccept it; unlike [tagValidator], it doesn\'t refuse single tags.'), ApiParameter(name: 'required', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether a field without tags shows the localized "This field is\nrequired" error.')])], properties: [], methods: [], values: []),
  'Oito2TagsFieldStyle': ApiEntry(kind: 'enum', package: 'oito2_ui', doc: 'The look of the tags of an [Oito2TagsField].', signature: '', constructors: [], properties: [], methods: [], values: [ApiMember(name: 'filled', signature: '', doc: 'Tags filled with the secondary container color.'), ApiMember(name: 'subtle', signature: '', doc: 'Tags on a neutral fill with medium-weight text; the focused tag takes\na faint accent fill and accent text.')]),
  'Oito2Theme': ApiEntry(kind: 'abstract class', package: 'oito2_ui', doc: 'Builds the oito2 Material 3 [ThemeData].\n\nThe platform drives density, control sizes, tap targets, splash effects\nand page transitions. [light], [dark] and [fromColors] take it as an\noptional [Oito2Platform] that defaults to [Oito2Platform.current];\n[fromSystem] takes it from the settings.', signature: '', constructors: [ApiConstructor(name: 'Oito2Theme', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [], methods: [ApiMember(name: 'light', signature: 'static light(Color? accent, bool highContrast, Oito2Platform? platform) → ThemeData', doc: 'The light oito2 base theme with [accent] as the primary hue.'), ApiMember(name: 'dark', signature: 'static dark(Color? accent, bool highContrast, Oito2Platform? platform) → ThemeData', doc: 'The dark oito2 base theme with [accent] as the primary hue.'), ApiMember(name: 'fromSystem', signature: 'static fromSystem(Oito2SystemSettings settings, Brightness brightness, Color? accent) → ThemeData', doc: 'The theme that follows the system [settings] for [brightness].\n\nBuilds the base theme with [accent], falling back to the system\naccent color, and the system high-contrast preference. The platform\ncomes from [settings].'), ApiMember(name: 'fromColors', signature: 'static fromColors(Oito2ColorTheme colors, Oito2Platform? platform) → ThemeData', doc: 'The theme for already resolved [colors].\n\n[colors] provides the `ColorScheme`, the scaffold background and the\ncolor [ThemeExtension]s ([Oito2ColorTheme.semantic],\n[Oito2ColorTheme.chrome] and [Oito2ColorTheme.syntax] wrapped in\n[Oito2SyntaxTheme]); the theme also carries the navigation, progress\nand title bar extensions derived from them.\n\nCalls with an equal [colors] and platform return the same\n[ThemeData] instance while it stays among the 16 most recently used.')], values: []),
  'Oito2Tile': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A row with an optional leading widget, a title, a subtitle and a\ntrailing widget, as used in settings and property lists.\n\nWith [onTap] the whole row is a button. Without it, the tile is read\nas one element with its trailing control, such as a switch.', signature: '', constructors: [ApiConstructor(name: 'Oito2Tile', doc: 'Creates a tile.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'leading', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A widget before the text, usually an icon.'), ApiParameter(name: 'title', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The primary text.'), ApiParameter(name: 'subtitle', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The secondary text, below the title.'), ApiParameter(name: 'trailing', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A widget after the text, such as a switch or a value.\n\nWhen the tile has [onTap] and a [Text] title, a trailing widget other\nthan a [Text] or an [Icon] is read as a separate element labeled with\nthe title, so its action stays apart from the tile\'s.'), ApiParameter(name: 'onTap', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the tile is activated; null makes the tile static.'), ApiParameter(name: 'enabled', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the tile can be interacted with; disabled tiles are dimmed.'), ApiParameter(name: 'padding', type: 'EdgeInsetsGeometry', isRequired: false, isNamed: true, defaultValue: 'const EdgeInsets.symmetric(horizontal: Oito2Spacing.lg, vertical: Oito2Spacing.md)', doc: 'Space around the content.')])], properties: [], methods: [], values: []),
  'Oito2TileList': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A bordered list of [Oito2Tile]s separated by dividers.', signature: '', constructors: [ApiConstructor(name: 'Oito2TileList', doc: 'Creates a tile list.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'children', type: 'List<Widget>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The tiles, in order.')])], properties: [], methods: [], values: []),
  'Oito2TimeEntry': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A time text field that accepts `H:MM` and `HH:MM`, with an optional\nAM/PM suffix in 12-hour locales, and offers a clock picker button.\n\nThe display format follows the locale and the platform 24-hour\nsetting; the error message and the labels come from\n`MaterialLocalizations`. Errors show after the field loses focus or is\nsubmitted, or at once after its [Oito2Form] found errors.', signature: '', constructors: [ApiConstructor(name: 'Oito2TimeEntry', doc: 'Creates a time entry.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'participatesInForm', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the field registers with the closest [Oito2Form], taking\npart in its validation, error summary and dirty state; true by\ndefault. When false, the field shows its own errors as outside a\nform.'), ApiParameter(name: 'initialTime', type: 'TimeOfDay?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The time shown at start.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<TimeOfDay?>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with each valid time, or null when the field is emptied.\n\nInvalid text doesn\'t call it, so the last valid time stays reported;\n[onErrorChanged] tells when the text doesn\'t parse.'), ApiParameter(name: 'onErrorChanged', type: 'ValueChanged<String?>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the error message when the text stops being a valid\ntime, and with null when it is valid again.\n\nIt reports only the parse errors, not those of [validator] or\n[required].'), ApiParameter(name: 'validator', type: 'String? Function(TimeOfDay?)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Checks a valid time, or null for an empty field, and returns an\nerror message, or null to accept it.'), ApiParameter(name: 'required', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether an empty field shows the localized "This field is required"\nerror.'), ApiParameter(name: 'labelText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The field label; defaults to the localized "Enter time".'), ApiParameter(name: 'acceptEmpty', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether an empty field is valid.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the field takes focus when shown.'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node; one is created when null.'), ApiParameter(name: 'showPickerButton', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the clock picker button is shown.')])], properties: [], methods: [ApiMember(name: 'parseTime', signature: 'static parseTime(String text, String am, String pm) → TimeOfDay?', doc: 'Parses [text] as `H:MM` or `HH:MM` (also with `.` or `h` as the\nseparator), with an optional day-period marker before or after the\ntime, as the locale writes it (such as `9:30 PM`): [am] or [pm]\n(case-insensitive), `am`/`pm`, or the letters a/p.\n\nWithout a marker the hour must be 0 to 23; with one, 1 to 12. Returns\nnull for anything else.')], values: []),
  'Oito2TimeUnit': ApiEntry(kind: 'enum', package: 'oito2_ui', doc: 'The units of a relative time, from [second] to [year].', signature: '', constructors: [], properties: [], methods: [], values: [ApiMember(name: 'second', signature: '', doc: 'Seconds.'), ApiMember(name: 'minute', signature: '', doc: 'Minutes.'), ApiMember(name: 'hour', signature: '', doc: 'Hours.'), ApiMember(name: 'day', signature: '', doc: 'Days.'), ApiMember(name: 'week', signature: '', doc: 'Weeks.'), ApiMember(name: 'month', signature: '', doc: 'Months.'), ApiMember(name: 'year', signature: '', doc: 'Years.')]),
  'Oito2TimerController': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A stopwatch, or a countdown when [countdown] is set, that notifies its\nlisteners every [interval] while it runs.\n\nA countdown stops by itself at zero and calls [onComplete]. Time is\nmeasured from the clock [now], so it stays exact however late the ticks\narrive; the default clock is monotonic, unaffected by changes to the\nsystem time.', signature: '', constructors: [ApiConstructor(name: 'Oito2TimerController', doc: 'Creates a stopped timer at zero.\n\n[now] overrides the clock time is measured with, for example in tests.\nThrows an [AssertionError] in debug builds when [interval] is not\npositive.', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'countdown', type: 'Duration?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The length of a countdown, or null for a stopwatch.'), ApiParameter(name: 'interval', type: 'Duration', isRequired: false, isNamed: true, defaultValue: 'const Duration(seconds: 1)', doc: 'How often listeners are notified while the timer runs.'), ApiParameter(name: 'onTick', type: 'ValueChanged<Duration>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with [elapsed] on every tick, including the final tick of a\ncountdown.'), ApiParameter(name: 'onComplete', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when a countdown reaches zero, after the listeners are\nnotified.'), ApiParameter(name: 'now', type: 'DateTime Function()?', isRequired: false, isNamed: true, defaultValue: '', doc: '')])], properties: [ApiMember(name: 'elapsed', signature: 'Duration', doc: 'The time run so far, up to [countdown].'), ApiMember(name: 'remaining', signature: 'Duration?', doc: 'The time left of a countdown, or null for a stopwatch.'), ApiMember(name: 'isRunning', signature: 'bool', doc: 'Whether the timer is running.'), ApiMember(name: 'isCompleted', signature: 'bool', doc: 'Whether a countdown has reached zero.')], methods: [ApiMember(name: 'start', signature: 'start() → void', doc: 'Starts or resumes the timer; does nothing while it runs, after a\ncountdown completes (see [restart]) or once disposed.'), ApiMember(name: 'pause', signature: 'pause() → void', doc: 'Pauses the timer, keeping the time run so far; does nothing when it\nisn\'t running or after [dispose].'), ApiMember(name: 'reset', signature: 'reset() → void', doc: 'Stops the timer and sets it back to zero, clearing [isCompleted];\ndoes nothing after [dispose].'), ApiMember(name: 'restart', signature: 'restart() → void', doc: 'Sets the timer back to zero and starts it.')], values: []),
  'Oito2TimerText': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'The time of an [Oito2TimerController] as text: the remaining time of a\ncountdown or the elapsed time of a stopwatch, in tabular figures so the\ndigits don\'t shift.', signature: '', constructors: [ApiConstructor(name: 'Oito2TimerText', doc: 'Creates a timer text.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'controller', type: 'Oito2TimerController', isRequired: true, isNamed: true, defaultValue: '', doc: 'The timer shown.'), ApiParameter(name: 'style', type: 'TextStyle?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The text style, merged over tabular figures.'), ApiParameter(name: 'tenths', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether tenths of a second show; without them a countdown rounds up\nto the whole second.')])], properties: [], methods: [], values: []),
  'Oito2TitleBar': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A desktop header bar: a title, optional leading widget and actions, and\nwindow control buttons in the order of [buttonLayout].\n\nThe empty area of the bar moves the window when dragged, maximizes or\nrestores it on double click and opens the window menu on secondary\nclick, through [controller]. Without a controller the buttons render\ndisabled, unless [onClose] handles the close button.\n\nMost apps use [Oito2WindowTitleBar], which picks the control style,\nlayout and controller from the system automatically.', signature: '', constructors: [ApiConstructor(name: 'Oito2TitleBar', doc: 'Creates a title bar.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'title', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The title, usually a [Text].'), ApiParameter(name: 'leading', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A widget placed before the title, such as a back button.'), ApiParameter(name: 'actions', type: 'List<Widget>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: 'Widgets placed after the title, such as icon buttons.'), ApiParameter(name: 'centerTitle', type: 'bool?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Whether the title is centered; defaults to the theme, then true.'), ApiParameter(name: 'style', type: 'Oito2TitleBarStyle?', isRequired: false, isNamed: true, defaultValue: '', doc: 'How the bar is presented; defaults to the theme, then\n[Oito2TitleBarStyle.normal].'), ApiParameter(name: 'controlStyle', type: 'Oito2WindowControlStyle', isRequired: false, isNamed: true, defaultValue: 'Oito2WindowControlStyle.gnome', doc: 'The visual family of the window control buttons.'), ApiParameter(name: 'buttonLayout', type: 'Oito2WindowButtonLayout', isRequired: false, isNamed: true, defaultValue: 'const Oito2WindowButtonLayout(trailing: [Oito2WindowButton.minimize, Oito2WindowButton.maximize, Oito2WindowButton.close])', doc: 'Which window buttons appear and on which side.'), ApiParameter(name: 'controller', type: 'Oito2WindowController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The window controller that receives button presses and gestures.'), ApiParameter(name: 'onClose', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Replaces the controller\'s close action, for example to pop a route.'), ApiParameter(name: 'labels', type: 'Oito2WindowControlLabels?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Overrides of the window buttons\' accessibility labels, which\notherwise come from [Oito2Localizations].'), ApiParameter(name: 'leadingInset', type: 'double', isRequired: false, isNamed: true, defaultValue: '0', doc: 'Empty space kept at the leading edge, for native window buttons drawn\nby the operating system.'), ApiParameter(name: 'backgroundColor', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The background color; defaults to the theme.'), ApiParameter(name: 'foregroundColor', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The color of the title, icons and glyphs; defaults to the theme.'), ApiParameter(name: 'border', type: 'BorderSide?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The bottom border; defaults to the theme.'), ApiParameter(name: 'height', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The bar height; defaults to the [Oito2TitleBarThemeData] height, then\n[Oito2Sizes.titleBarHeight].\n\nWhere the theme pads tap targets (touch platforms) and the bar shows\nwindow buttons, the default grows to fit the\n[Oito2Sizes.minTouchTarget] buttons above the bottom border; a\nheight set here is kept.\n\n[preferredSize] has no context to read the theme from, so a\n[Scaffold] gives the bar [Oito2Sizes.titleBarHeight] unless [height]\nis set, and reserves it even when only the theme hides the bar. To\nfollow a themed height or style there, or the taller bar of touch\nplatforms, wrap the bar in a [PreferredSize] sized by\n[preferredSizeOf].'), ApiParameter(name: 'isDraggable', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether dragging the bar moves the window.'), ApiParameter(name: 'interactiveTitle', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether [title] takes pointer input, for a title such as tabs or a\nsearch field; otherwise pointer input over a title, such as a text,\nmoves the window like the rest of the bar.')])], properties: [ApiMember(name: 'preferredSize', signature: 'Size', doc: 'The size of the bar without reading the theme: zero tall when\n[style] is hidden, otherwise [height] or [Oito2Sizes.titleBarHeight].\n\nIt doesn\'t follow the themed height or style, nor the taller bar\nwhere the theme pads tap targets (touch platforms); use\n[preferredSizeOf] there.')], methods: [ApiMember(name: 'preferredSizeOf', signature: 'static preferredSizeOf(BuildContext context, Oito2TitleBarStyle? style, double? height, BorderSide? border) → Size', doc: 'Returns the size of a title bar with [style], [height] and the\nbottom [border] in [context]\'s theme, as the bar lays itself out when\nit shows window buttons: zero tall when hidden, otherwise [height],\nor the theme height or [Oito2Sizes.titleBarHeight], grown where the\ntheme pads tap targets (touch platforms) to fit\n[Oito2Sizes.minTouchTarget] buttons above the border.')], values: []),
