  'Oito2ToggleButton': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A compact row with a toggle [control] and a clickable [title] and\n[subtitle], as GNOME check and switch buttons.\n\nClicking anywhere on the row, or pressing Space or Enter while it has\nfocus, calls [onToggled]. The row takes keyboard focus as a whole (the\n[control] itself is kept out of focus traversal), shows the focus ring\naround itself and reads as one element to assistive technologies.\n[Oito2CheckButton], [Oito2RadioButton] and [Oito2SwitchButton] are\nbuilt on it.', signature: '', constructors: [ApiConstructor(name: 'Oito2ToggleButton', doc: 'Creates a toggle button.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'control', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The toggle, such as an [Oito2Checkbox], [Oito2Radio] or\n[Oito2Switch].'), ApiParameter(name: 'title', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The label, usually a [Text].'), ApiParameter(name: 'subtitle', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Secondary text below the label.'), ApiParameter(name: 'onToggled', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the row is tapped or activated with the keyboard; null\ndisables the row and dims its text. It does not disable [control],\nwhich takes its own callback.'), ApiParameter(name: 'controlAtEnd', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether [control] follows the text instead of preceding it.'), ApiParameter(name: 'padding', type: 'EdgeInsetsGeometry', isRequired: false, isNamed: true, defaultValue: 'const EdgeInsets.symmetric(horizontal: Oito2Spacing.xs, vertical: Oito2Spacing.xxs)', doc: 'Space around the row content.'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node of the row; one is created 