  'Oito2ToggleGroup': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A joined row (or column) of buttons that turn on and off, such as text\nformatting or alignment buttons.\n\nWith [multiple], each item turns on and off by itself; otherwise turning\none on turns the others off, and [deselectable] says whether the one\nthat is on can be turned off. Items that are on are raised from the\ntrack.\n\nThe group is one stop in keyboard navigation: the arrow keys move\nbetween the enabled items, wrapping at the ends, and Space or Enter\ntoggles the focused one.', signature: '', constructors: [ApiConstructor(name: 'Oito2ToggleGroup', doc: 'Creates a toggle group.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'items', type: 'List<Oito2ToggleItem<T>>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The items, in order.'), ApiParameter(name: 'selected', type: 'Set<T>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The values of the items that are on.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<Set<T>>?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with the new set of values that are on; null disables the\ngroup.'), ApiParameter(name: 'multiple', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether several items can be on at once.'), ApiParameter(name: 'deselectable', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the only item that is on can be turned off, leaving none on;\nignored when [multiple].'), ApiParameter(name: 'orientation', type: 'Axis', isRequired: false, isNamed: true, defaultValue: 'Axis.horizontal', doc: 'Whether the items run across or down.')])], properties: [], methods: [], values: []),
  'Oito2ToggleItem': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A button of an [Oito2ToggleGroup].', signature: '', constructors: [ApiConstructor(name: 'Oito2ToggleItem', doc: 'Creates a toggle item for [value].', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'value', type: 'T', isRequired: true, isNamed: true, defaultValue: '', doc: 'The value the item turns on and off.'), ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The item content: an [Icon], a [Text] or both.'), ApiParameter(name: 'tooltip', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The tooltip, also the accessibility label of an item showing only an\nicon.'), ApiParameter(name: 'enabled', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the item can be toggled and focused; a disabled item is\ndimmed.')])], properties: [], methods: [], values: []),
  'Oito2TouchTarget': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Pads the touch target of a control to [Oito2Sizes.minTouchTarget] on\neach axis when the closest theme pads tap targets, as `Oito2Theme` does\non touch platforms, the way Material buttons do with\n[MaterialTapTargetSize.padded].\n\nWhile padding, the box is at least 48 pixels wide and tall, with\n[child] centered and drawn at its own size; a touch in the transparent\nmargin around [child] goes to the nearest point of [child], and the box\nforms the semantics node of the control, so assistive technologies\nreport the padded size. With [mergeSemantics], the semantics of all\ndescendants, such as a button that forms its own node, merge into that\nnode; otherwise only the descendants that form no node of their own,\nsuch as a text field, join it, and a button inside the field keeps its\nown node.\n\nWhen the theme doesn\'t pad tap targets, as on pointer platforms, the\nbox takes the size of [child] and adds nothing to its layout, hit\ntesting or semantics.\n\nThe widgets of this library already pad their touch targets; wrap\nother controls with it, such as a plain [TextField], which the theme\nkeeps 40 pixels tall on touch platforms.', signature: '', constructors: [ApiConstructor(name: 'Oito2TouchTarget', doc: 'Creates a touch target around [child].', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'mergeSemantics', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the semantics of all descendants merge into the node of the\npadded box.'), ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The control.')])], properties: [], methods: [], values: []),
  'Oito2Tour': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A guided tour over [child]: each step of the [controller] dims the\nwindow around its target, scrolls it into view and shows a card with\nthe step text, its position, and back, next and skip buttons.\n\nThe card takes the focus and is announced to assistive technologies;\nwhen the tour ends, the focus returns to where it was before. While the\ncard has focus, the arrow keys move between steps and Escape skips the\ntour. Taps outside the spotlight are blocked; taps inside reach the\ntarget, which moves a [Oito2TourStep.waitForTap] step on.', signature: '', constructors: [ApiConstructor(name: 'Oito2Tour', doc: 'Creates a tour.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'controller', type: 'Oito2TourController', isRequired: true, isNamed: true, defaultValue: '', doc: 'The steps and the current position.'), ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The content the tour runs over.'), ApiParameter(name: 'onFinished', type: 'ValueChanged<bool>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the tour ends, with true when it was completed and false\nwhen it was skipped.')])], properties: [], methods: [], values: []),
  'Oito2TourController': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Runs an [Oito2Tour] through its [steps], notifying its listeners on\nevery step change and when the tour ends.', signature: '', constructors: [ApiConstructor(name: 'Oito2TourController', doc: 'Creates a tour controller that isn\'t running yet.\n\nThrows an [AssertionError] in debug builds when [steps] is empty.', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'steps', type: 'List<Oito2TourStep>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The steps, in order.')])], properties: [ApiMember(name: 'index', signature: 'int?', doc: 'The index of the current step, or null when the tour isn\'t running.'), ApiMember(name: 'step', signature: 'Oito2TourStep?', doc: 'The current step, or null when the tour isn\'t running.'), ApiMember(name: 'isActive', signature: 'bool', doc: 'Whether the tour is running.'), ApiMember(name: 'completed', signature: 'bool', doc: 'Whether the last run reached the end, rather than being skipped;\nfalse while a run is in progress.')], methods: [ApiMember(name: 'start', signature: 'start(int index) → void', doc: 'Starts the tour, or restarts it, at the step at [index].\n\nThrows an [AssertionError] in debug builds when [index] is out of\nrange.'), ApiMember(name: 'goTo', signature: 'goTo(int index) → void', doc: 'Shows the step at [index], starting the tour when it isn\'t running.\n\nThrows an [AssertionError] in debug builds when [index] is out of\nrange.'), ApiMember(name: 'next', signature: 'next() → void', doc: 'Moves to the next step, or completes the tour after the last; does\nnothing when the tour isn\'t running.'), ApiMember(name: 'previous', signature: 'previous() → void', doc: 'Moves to the previous step; does nothing on the first step or when\nthe tour isn\'t running.'), ApiMember(name: 'skip', signature: 'skip() → void', doc: 'Ends the tour without completing it; does nothing when it isn\'t\nrunning.')], values: []),
  'Oito2TourStep': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'One step of an [Oito2Tour].', signature: '', constructors: [ApiConstructor(name: 'Oito2TourStep', doc: 'Creates a tour step.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'title', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The heading of the step card.'), ApiParameter(name: 'target', type: 'GlobalKey<State<StatefulWidget>>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The key of the widget the step points at; the card is centered in\nthe tour layer when null or when the widget isn\'t built.'), ApiParameter(name: 'description', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The body text of the step card, below [title].'), ApiParameter(name: 'placement', type: 'Oito2PopoverPlacement', isRequired: false, isNamed: true, defaultValue: 'Oito2PopoverPlacement.bottom', doc: 'The side of the target where the card opens.'), ApiParameter(name: 'waitForTap', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the step waits for a tap on the target instead of offering\na next button. The tap reaches the target, then the tour moves on.\nWhile the target isn\'t on screen, or while an assistive technology\nasks for accessible navigation, which can\'t reach the target behind\nthe tour, the next button shows instead.'), ApiParameter(name: 'spotlightPadding', type: 'double', isRequired: false, isNamed: true, defaultValue: '6', doc: 'The space around the target inside the spotlight, in logical\npixels.')])], properties: [], methods: [], values: []),
  'Oito2TreeCollection': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'An immutable tree of [Oito2TreeNode]s with the queries a tree view\nneeds: lookups by value and index path, parents and siblings, the\nvisible order for a set of expanded branches, filtering and copies with\nnodes inserted, removed, moved or replaced.\n\nAn index path lists the child indexes from the top level down, such as\n`[0, 2]` for the third child of the first top-level node.', signature: '', constructors: [ApiConstructor(name: 'Oito2TreeCollection', doc: 'Creates a tree with the top-level [roots].\n\nThrows an [ArgumentError] when two nodes share a value.', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'roots', type: 'Iterable<Oito2TreeNode<T>>', isRequired: true, isNamed: false, defaultValue: '', doc: '')]), ApiConstructor(name: 'Oito2TreeCollection.fromPaths', doc: 'Builds a tree from [paths] split by [separator], such as file paths:\neach segment becomes a branch and the last one a leaf, unless another\npath continues below it. Empty segments are skipped. Node values are\nthe paths up to each node, joined by [separator], and labels are the\nsegment names.', isConst: false, isFactory: true, parameters: [ApiParameter(name: 'paths', type: 'Iterable<String>', isRequired: true, isNamed: false, defaultValue: '', doc: ''), ApiParameter(name: 'separator', type: 'String', isRequired: false, isNamed: true, defaultValue: '\'/\'', doc: '')])], properties: [ApiMember(name: 'values', signature: 'List<String>', doc: 'The values of every node, in depth-first order.'), ApiMember(name: 'branchValues', signature: 'List<String>', doc: 'The values of every branch.')], methods: [ApiMember(name: 'has', signature: 'has(String? value) → bool', doc: 'Whether a node has [value].'), ApiMember(name: 'indexPathOf', signature: 'indexPathOf(String value) → List<int>?', doc: 'Returns the index path of the node with [value], or null when there is\nnone.'), ApiMember(name: 'nodeAt', signature: 'nodeAt(List<int> indexPath) → Oito2TreeNode<T>?', doc: 'Returns the node at [indexPath], or null when the path is empty or\ndoesn\'t exist.'), ApiMember(name: 'find', signature: 'find(String? value) → Oito2TreeNode<T>?', doc: 'Returns the node with [value], or null when there is none.'), ApiMember(name: 'parentOf', signature: 'parentOf(String value) → String?', doc: 'Returns the value of the parent of [value], or null for a top-level\nor unknown node.'), ApiMember(name: 'childrenOf', signature: 'childrenOf(String value) → List<Oito2TreeNode<T>>', doc: 'Returns the children of [value]; empty for a leaf or a missing node.'), ApiMember(name: 'siblingsOf', signature: 'siblingsOf(String value) → List<Oito2TreeNode<T>>', doc: 'Returns the nodes that share a parent with [value], including it; the\ntop-level nodes for an unknown value.'), ApiMember(name: 'ancestorsOf', signature: 'ancestorsOf(String value) → List<String>', doc: 'Returns the values of the ancestors of [value], from the top level\ndown.'), ApiMember(name: 'depthOf', signature: 'depthOf(String value) → int', doc: 'Returns the depth of [value]: 0 at the top level, and also 0 for an\nunknown value.'), ApiMember(name: 'flatten', signature: 'flatten() → List<({int depth, List<int> indexPath, Oito2TreeNode<T> node})>', doc: 'Returns every node in depth-first order with its depth and index\npath.'), ApiMember(name: 'visible', signature: 'visible(Set<String> expanded) → List<({int depth, List<int> indexPath, Oito2TreeNode<T> node})>', doc: 'Returns the nodes a tree view shows when the branches in [expanded]\nare open, in display order.'), ApiMember(name: 'descendantsOf', signature: 'descendantsOf(String value) → List<String>', doc: 'Returns the values of every node below [value], in depth-first order.'), ApiMember(name: 'leavesOf', signature: 'leavesOf(String value) → List<String>', doc: 'Returns the values of the leaves below [value], or [value] itself when\nit is a leaf; empty for an unknown value. Empty branches do