  'Oito2UnsavedChangesController': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Collects the [Oito2UnsavedChangesGuard]s with unsaved changes below an\n[Oito2UnsavedChangesScope], so a shell that switches pages without\npopping a route can ask them first.\n\n[Oito2MasterDetailPage] and [Oito2NavigationPage] ask the closest scope\nbefore they switch to another item; call [confirmLeave] before other\nswitches, such as from a command or an address change.', signature: '', constructors: [ApiConstructor(name: 'Oito2UnsavedChangesController', doc: 'Creates a controller with no handlers.', isConst: false, isFactory: false, parameters: [])], properties: [ApiMember(name: 'hasUnsavedChanges', signature: 'bool', doc: 'Whether a guard with unsaved changes is registered.')], methods: [ApiMember(name: 'addHandler', signature: 'addHandler(Oito2LeaveHandler handler) → void', doc: 'Adds [handler], asked by [confirmLeave].'), ApiMember(name: 'removeHandler', signature: 'removeHandler(Oito2LeaveHandler handler) → void', doc: 'Removes [handler], added by [addHandler].'), ApiMember(name: 'confirmLeave', signature: 'confirmLeave() → Future<bool>', doc: 'Asks every handler, the last added first, until one refuses.\n\nReturns true when there are no handlers or all of them allow\nleaving.')], values: []),
  'Oito2UnsavedChangesGuard': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Asks before the user leaves [child] while it has unsaved changes.\n\nThe changes come from [form], dirty while any of its fields changed,\nor from [isDirty]. While there are changes, the guard:\n\n- blocks popping its route, such as with a back button, and asks with\n  [showOito2UnsavedChangesDialog] instead, popping only when the user\n  discards the changes or [onSave] saves them;\n- registers with the closest [Oito2UnsavedChangesScope], which page\n  switchers ask before switching;\n- registers with the window controller of the closest\n  [Oito2WindowScope] when it implements [Oito2WindowCloseGuard], so\n  closing the window asks too.\n\nWith [onSave], the dialog offers "Save": the guard calls it and leaves\nonly when it completes with true, so a save that fails validation\nkeeps the page.', signature: '', constructors: [ApiConstructor(name: 'Oito2UnsavedChangesGuard', doc: 'Creates a guard over [child].\n\nThrows an [AssertionError] in debug mode unless exactly one of [form]\nand [isDirty] is given.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'form', type: 'Oito2FormController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The form whose changes are guarded.'), ApiParameter(name: 'isDirty', type: 'ValueListenable<bool>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Tells whether there are unsaved changes, in place of [form].'), ApiParameter(name: 'onSave', type: 'Future<bool> Function()?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Saves the changes and completes with whether they were saved; the\ndialog offers "Save" only when it is given.'), ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The guarded content.')])], properties: [], methods: [], values: []),
  'Oito2UnsavedChangesScope': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Provides an [Oito2UnsavedChangesController] to the guards and the\npage switchers below it.', signature: '', constructors: [ApiConstructor(name: 'Oito2UnsavedChangesScope', doc: 'Creates a scope that provides [controller] to [child].', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'controller', type: 'Oito2UnsavedChangesController', isRequired: true, isNamed: true, defaultValue: '', doc: 'The controller the guards register with.'), ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: '')])], properties: [], methods: [ApiMember(name: 'maybeOf', signature: 'static maybeOf(BuildContext context, bool listen) → Oito2UnsavedChangesController?', doc: 'Returns the controller of the closest enclosing scope, or null when\nthere is none.\n\nWith [listen], [context] rebuilds when the scope gets another\ncontroller.')], values: []),
  'Oito2UsageBar': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A bar that shows how much of a quota is used, such as the storage of\nan account, with a title and a "1.2 GB of 15 GB" label.\n\nThe bar fills by [value] over [total]. From [warningAt] of the total it\nturns to the warning tone, and from [dangerAt] to the danger tone, as\ndoes the label; above the total (over quota) the bar stays full in the\ndanger tone. The [compact] variant puts a thin bar over one line of\nsmall text, for navigation rails and side panes.\n\nAssistive technologies read the title and the label, with the used\npercentage as the value.', signature: '', constructors: [ApiConstructor(name: 'Oito2UsageBar', doc: 'Creates a usage bar of [value] over [total]; with the default total\nof 1, [value] is a fraction and the label is a percentage.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'value', type: 'double', isRequired: true, isNamed: true, defaultValue: '', doc: 'The amount used.'), ApiParameter(name: 'total', type: 'double', isRequired: false, isNamed: true, defaultValue: '1', doc: 'The quota; [value] is a fraction when it is 1.'), ApiParameter(name: 'title', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The name of what is measured, such as an account or a drive, usually\na [Text].'), ApiParameter(name: 'label', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Replaces the "X of Y" label, usually a [Text].'), ApiParameter(name: 'formatValue', type: 'String Function(BuildContext, double)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Formats [value] and [total] in the default label; when null, a\nfraction shows as a percentage and other totals as locale numbers.'), ApiParameter(name: 'warningAt', type: 'double', isRequired: false, isNamed: true, defaultValue: '0.7', doc: 'The used fraction from which the bar shows the warning tone.'), ApiParameter(name: 'dangerAt', type: 'double', isRequired: false, isNamed: true, defaultValue: '0.9', doc: 'The used fraction from which the bar shows the danger tone.'), ApiParameter(name: 'compact', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the bar is thin with one line of small text below.'), ApiParameter(name: 'semanticsLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label; defaults to the text of [title] and the\nlabel.')]), ApiConstructor(name: 'Oito2UsageBar.bytes', doc: 'Creates a usage bar of [used] over [total] bytes, labelled with\n[Oito2Format.bytes] in [units] for the locale, such as "1.2 GB of\n15 GB".', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'used', type: 'int', isRequired: true, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'total', type: 'int', isRequired: true, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'units', type: 'Oito2ByteUnits', isRequired: false, isNamed: true, defaultValue: 'Oito2ByteUnits.si', doc: ''), ApiParameter(name: 'title', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The name of what is measured, such as an account or a drive, usually\na [Text].'), ApiParameter(name: 'label', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Replaces the "X of Y" label, usually a [Text].'), ApiParameter(name: 'warningAt', type: 'double', isRequired: false, isNamed: true, defaultValue: '0.7', doc: 'The used fraction from which the bar shows the warning tone.'), ApiParameter(name: 'dangerAt', type: 'double', isRequired: false, isNamed: true, defaultValue: '0.9', doc: 'The used fraction from which the bar shows the danger tone.'), ApiParameter(name: 'compact', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the bar is thin with one line of small text below.'), ApiParameter(name: 'semanticsLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '',