  'Oito2VerticalTabBar': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A column of tabs with a rounded marker that slides to the selected one,\nfor side navigation between views of the same content.\n\nIt drives a [TabController] like [Oito2TabBar]: the [controller] given,\nor the closest `DefaultTabController`; [style] picks the marker look.\nThe tabs take the full width and line up at the leading edge. The\nselected tab is the bar\'s one stop in keyboard navigation, and the up\nand down arrows, Home and End move the selection. Throws a\n[FlutterError] in debug builds when neither [controller] nor a\n`DefaultTabController` is available.', signature: '', constructors: [ApiConstructor(name: 'Oito2VerticalTabBar', doc: 'Creates a vertical tab bar.\n\nThrows an [AssertionError] in debug builds when the controller\'s\nlength differs from the number of [tabs].', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'tabs', type: 'List<Widget>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The tabs, usually [Oito2Tab]s.'), ApiParameter(name: 'controller', type: 'TabController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The tab controller; defaults to the closest `DefaultTabController`.'), ApiParameter(name: 'onTap', type: 'ValueChanged<int>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the index of a tab selected by a tap or a key.'), ApiParameter(name: 'style', type: 'Oito2TabBarStyle', isRequired: false, isNamed: true, defaultValue: 'Oito2TabBarStyle.pill', doc: 'The look of the selected tab marker.')])], properties: [], methods: [], values: []),
  'Oito2VerticalTabs': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Vertical tabs beside the content of the selected one: an\n[Oito2VerticalTabBar] at the start side and the matching child of\n[children] filling the rest.\n\nLike the bar, it uses the [controller] given or the closest\n`DefaultTabController`. The tab column scrolls when the tabs don\'t fit\nits height.', signature: '', constructors: [ApiConstructor(name: 'Oito2VerticalTabs', doc: 'Creates vertical tabs.\n\nThrows an [AssertionError] in debug builds when [tabs] and\n[children] differ in length.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'tabs', type: 'List<Widget>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The tabs, usually [Oito2Tab]s.'), ApiParameter(name: 'children', type: 'List<Widget>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The content of each tab, in the order of [tabs].'), ApiParameter(name: 'controller', type: 'TabController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The tab controller; defaults to the closest `DefaultTabController`.'), ApiParameter(name: 'onTap', type: 'ValueChanged<int>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the index of a tab selected by a tap or a key.'), ApiParameter(name: 'style', type: 'Oito2TabBarStyle', isRequired: false, isNamed: true, defaultValue: 'Oito2TabBarStyle.pill', doc: 'The look of the selected tab marker.'), ApiParameter(name: 'tabBarWidth', type: 'double', isRequired: false, isNamed: true, defaultValue: '200', doc: 'The width of the tab column.')])], properties: [], methods: [], values: []),
  'Oito2VirtualList': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A scrolling list of the items of [collection] that builds only the\nrows in view, for lists of thousands of items, with the selection kept\nin [controller].\n\nIt selects and responds to the keyboard as an [Oito2ListBox]: the list\ntakes the focus as a whole and marks its active row; the arrow keys,\nHome, End, Page Up and Page Down move the active row, which a\nsingle-selection list also selects. In a multiple-selection list Space\ntoggles the active row, Shift with the movement keys extends the\nselection and Control (Command on Apple platforms) with A selects all;\nclicks follow the desktop conventions of\n[Oito2SelectionController.click]. Typing letters jumps to the next\nmatching label. Enter or a double click calls [onActivate]. Disabled\nitems can\'t be selected or activated. Groups aren\'t shown as headings.\n\nWith [onReorder], the user reorders the items as in an\n[Oito2ListBox]: Alt with Up or Down moves the active row, the rows\noffer "Move up" and "Move down" accessibility actions, and the rows\ncan be dragged, by the whole row or, with [dragHandle], by a grip at\nthe start, with a line marking the drop and the list scrolling near\nits top or bottom edge. The list doesn\'t change [collection]: the app\nmoves the item.\n\nEvery row is [itemExtent] tall, or as tall as its content with\n[variableHeight]. Rows are keyed by their item value, so a row keeps\nits state when items move. The list rebuilds the rows in view when it\nrebuilds; to update a single row often, such as a progress, build its\nchanging part from a listenable of that item, such as with a\n[ValueListenableBuilder] in [itemBuilder], so only that row rebuilds.\n\n[onReachEnd] runs when the end of the list comes within\n[reachEndThreshold] of the view, once until the user scrolls away from\nthe end or the number of items changes. With [asyncController], it\nalso loads the next page, and the list ends with a loading row while a\npage loads, or with an error row and a retry button when it failed;\nthe app builds [collection] from the controller\'s items.\n\nThe list needs a bounded height, such as from a [SizedBox] or an\n[Expanded].', signature: '', constructors: [ApiConstructor(name: 'Oito2VirtualList', doc: 'Creates a virtual list.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'collection', type: 'Oito2ListCollection<T>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The items.'), ApiParameter(name: 'controller', type: 'Oito2SelectionController', isRequired: true, isNamed: true, defaultValue: '', doc: 'The selection over [collection].'), ApiParameter(name: 'itemBuilder', type: 'Oito2ListBoxItemBuilder<T>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Builds the content of a row; shows the item label when null. It is\ncalled only for the rows being built, so it must be cheap.'), ApiParameter(name: 'onActivate', type: 'ValueChanged<T>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called on Enter or a double click on an enabled item.'), ApiParameter(name: 'itemExtent', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The height of every row; the theme\'s control height when null, or,\nwhere the theme pads tap targets (touch platforms), a height that\nmakes each row [Oito2Sizes.minTouchTarget] tall. With\n[variableHeight], the estimated height of the rows not built yet.\n\nA height set here is kept on every platform, even below the touch\ntarget size.'), ApiParameter(name: 'variableHeight', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether each row is as tall as its content, instead of [itemExtent].\n\nA row is at least 30 pixels tall, or [Oito2Sizes.minTouchTarget]\nwhere the theme pads tap targets. Each row is then laid out as it\nscrolls into view, and moving the\nactive row to one far away scrolls to an estimated position first.'), ApiParameter(name: 'cacheExtent', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'How far beyond the visible area rows are built ahead of scrolling,\nin logical pixels; the scroll view\'s default when null.'), ApiParameter(name: 'onReachEnd', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the end of the list comes within [reachEndThreshold] of\nthe view, such as to load more items.'), ApiParameter(name: 'reachEndThreshold', type: 'double', isRequired: false, isNamed: true, defaultValue: '200', doc: 'How close to the end of the list, in logical pixels, [onReachEnd]\nruns.'), ApiParameter(name: 'asyncController', type: 'Oito2AsyncListController<Object?, Object?>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The controller the items are loaded through: the list loads its next\npage when the end comes near, and shows its loading and error states\nafter the last row.'), ApiParameter(name: 'header', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Shown above the first row, scrolling with the rows.'), ApiParameter(name: 'footer', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Shown after the last row, scrolling with the rows.'), ApiParameter(name: 'placeholder', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Shown when [collection] is empty and nothing is loading; a "no\nitems" text when null.'), ApiParameter(name: 'showCheckmarks', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether rows of a multiple-selection list show a check mark when\nselected.'), ApiParameter(name: 'semanticLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label of the list.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the list takes the focus when shown.'), ApiParameter(name: 'onReorder', type: 'void Function(int, int)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the user moves an item, with its index in\n[Oito2ListCollection.items] and the index it ends at, counted once it\nis taken out of its place: moving the first of three items to the end\nreports `(0, 2)`. The items can\'t be reordered when null.'), ApiParameter(name: 'dragHandle', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether only a grip at the start of each row drags it, instead of\nthe whole row, when [onReorder] is set.')])], properties: [], methods: [], values: []),
  'Oito2Watermark': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Places a faint [watermark] behind [child], for example a large icon\nin an empty page. The watermark is hidden from assistive technologies\nand ignores pointer events.\n\nThe watermark covers the area [child] takes; to watermark a whole page,\ngive [child] the full size, for example with [Center] or [Align].', signature: '', constructors: [ApiConstructor(name: 'Oito2Watermark', doc: 'Creates a watermarked area.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'watermark', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The decorative widget.'), ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The content drawn over the watermark.'), ApiParameter(name: 'alignment', type: 'AlignmentGeometry', isRequired: false, isNamed: true, defaultValue: 'AlignmentDirectional.centerEnd', doc: 'Where the watermark sits.'), ApiParameter(name: 'padding', type: 'EdgeInsetsGeometry', isRequired: false, isNamed: true, defaultValue: 'const EdgeInsets.all(Oito2Spacing.page)', doc: 'Space between the watermark and the edges.'), ApiParameter(name: 'opacity', type: 'double', isRequired: false, isNamed: true, defaultValue: '0.1', doc: 'The watermark opacity, from 0 to 1.')])], properties: [], methods: [], values: []),
  'Oito2WeekScheduleGrid': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A week of time slots, one row per day, each holding one of [values],\nsuch as when a sync runs at full speed, limited or paused.\n\nThe [schedule] is a flat list of `7 × slotsPerDay` values, day after\nday: the value of [day] at [slot] is at `day * slotsPerDay + slot`\n(see [indexOf]). Days count from Monday (0) to Sunday (6), as\n`DateTime.weekday - 1`; the rows start at the first day of the week of\nthe locale\'s [MaterialLocalizations.firstDayOfWeekIndex]. A day has\n[slotsPerDay] slots, 24 hours by default, or 48 half hours for\nexample.\n\nThe legend below the grid picks the value painted (the brush). A click\npaints a cell and a drag paints the rectangle from the first cell to\nthe current one, previewed while dragging; [onChanged] receives the\nnew schedule. The grid takes the focus as a whole: the arrow keys move\nthe active cell, Home and End to the start and end of the day, Shift\nwith them extends a rectangular selection, Space or Enter paints the\nselection or the active cell, Escape clears the selection, and the\ndigits 1 to 9 pick a value of the legend. Without [onChanged] the grid\nis read-only.\n\nCells shrink with the width down to [minCellWidth]; below that the\ngrid scrolls sideways. Hour labels skip slots when they don\'t fit.\nAssistive technologies read each cell as its day, time range and\nvalue, such as "Monday 14:00–15:00, Limited".', signature: '', constructors: [ApiConstructor(name: 'Oito2WeekScheduleGrid', doc: 'Creates a week schedule grid.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'values', type: 'List<Oito2ScheduleValue<T>>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The values cells can hold, in legend order.'), ApiParameter(name: 'schedule', type: 'List<T>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The value of every cell, `7 × slotsPerDay` values from Monday\'s first\nslot to Sunday\'s last.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<List<T>>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the new schedule after painting; the grid is read-only\nwhen null.'), ApiParameter(name: 'paintValue', type: 'T?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The value painted; the grid keeps its own choice, starting at the\nfirst of [values], when null.'), ApiParameter(name: 'onPaintValueChanged', type: 'ValueChanged<T>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the legend or a digit key picks another value to paint.'), ApiParameter(name: 'slotsPerDay', type: 'int', isRequired: false, isNamed: true, defaultValue: '24', doc: 'The number of slots in a day.\n\nWhen it changes, the active cell moves to the last slot of the new\nday if it is beyond it, and the selection is dropped.'), ApiParameter(name: 'slotLabel', type: 'String Function(BuildContext, int)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Returns the header text of [slot]; by default the start time of the\nslots that start on the hour, such as "14" or "2 PM".'), ApiParameter(name: 'minCellWidth', type: 'double', isRequired: false, isNamed: true, defaultValue: '16', doc: 'The narrowest cell before the grid scrolls sideways.'), ApiParameter(name: 'cellHeight', type: 'double', isRequired: false, isNamed: true, defaultValue: '28', doc: 'The height of a day row.'), ApiParameter(name: 'showLegend', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the legend shows below the grid.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the grid takes the focus when shown.'), ApiParameter(name: 'semanticsLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label of the grid; defaults to the localized\n"Weekly schedule".')])], properties: [], methods: [ApiMember(name: 'indexOf', signature: 'static indexOf(int day, int slot, int slotsPerDay) → int', doc: 'Returns the index in a schedule of [day] (Monday 0) at [slot], with\n[slotsPerDay] slots a day.'), ApiMember(name: 'dayOfRow', signature: 'static dayOfRow(int row, int firstDayOfWeekIndex) → int', doc: 'Returns the day, Monday 0, shown on [row] of a grid whose first row\nis [firstDayOfWeekIndex], counted from Sunday 0 as\n[MaterialLocalizations.firstDayOfWeekIndex] is.')], values: []),
  'Oito2WindowButton': ApiEntry(kind: 'enum', package: 'oito2_ui', doc: 'A button that controls the native window.', signature: '', constructors: [], properties: [], methods: [], values: [ApiMember(name: 'minimize', signature: '', doc: 'Minimizes the window.'), ApiMember(name: 'maximize', signature: '', doc: 'Maximizes or restores the window.'), ApiMember(name: 'close', signature: '', doc: 'Closes the window.')]),
  'Oito2WindowButtonLayout': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'The order and side of the window control buttons in a title bar.', signature: '', constructors: [ApiConstructor(name: 'Oito2WindowButtonLayout', doc: 'Creates a layout with [leading] buttons before the title and\n[trailing] buttons after it.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'leading', type: 'List<Oito2WindowButton>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: 'The buttons placed before the title, in display order.'), ApiParameter(name: 'trailing', type: 'List<Oito2WindowButton>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: 'The buttons placed after the title, in display order.')]), ApiConstructor(name: 'Oito2WindowButtonLayout.parseGnome', doc: 'Parses the GNOME `button-layout` format used by GNOME, Budgie,\nCinnamon, MATE and Pantheon, for example\n`appmenu:minimize,maximize,close`.\n\nNames before the colon are leading, names after it are trailing.\nEntries other than `minimize`, `maximize` and `close` are ignored, and\neach button is kept only at its first position.', isConst: false, isFactory: true, parameters: [ApiParameter(name: 'value', type: 'String', isRequired: true, isNamed: false, defaultValue: '', doc: '')]), ApiConstructor(name: 'Oito2WindowButtonLayout.parseKde', doc: 'Parses the KDE KWin `ButtonsOnLeft` and `ButtonsOnRight` values, for\nexample `MS` and `HIAX`.\n\nRecognizes `I` (minimize), `A` (maximize) and `X` (close); other\nletters are ignored, and each button is kept only at its first\nposition.', isConst: false, isFactory: true, parameters: [ApiParameter(name: 'buttonsOnLeft', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'buttonsOnRight', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: '')]), ApiConstructor(name: 'Oito2WindowButtonLayout.parseXfwm', doc: 'Parses the Xfce xfwm4 `button_layout` format, for example `O|HMC`.\n\nLetters before the `|` title marker are leading, letters after it are\ntrailing. Recognizes `H` (minimize), `M` (maximize) and `C` (close);\nother letters are ignored, and each button is kept only at its first\nposition.', isConst: false, isFactory: true, parameters: [ApiParameter(name: 'value', type: 'String', isRequired: true, isNamed: false, defaultValue: '', doc: '')]), ApiConstructor(name: 'Oito2WindowButtonLayout.defaultFor', doc: 'The default layout for [style]: leading close, minimize and maximize\nfor [Oito2WindowControlStyle.macos], no buttons for\n[Oito2WindowControlStyle.none], and trailing minimize, maximize and\nclose otherwise.', isConst: false, isFactory: true, parameters: [ApiParameter(name: 'style', type: 'Oito2WindowControlStyle', isRequired: true, isNamed: false, defaultValue: '', doc: '')])], properties: [ApiMember(name: 'isEmpty', signature: 'bool', doc: 'Whether the layout has no buttons at all.')], methods: [], values: []),
  'Oito2WindowButtonSides': ApiEntry(kind: 'enum', package: 'oito2_ui', doc: 'Which side\'s window buttons an [Oito2WindowTitleBar] shows.\n\nA window split into a sidebar and a content area can give each its own\ntitle bar, as GNOME apps do: the sidebar bar shows the [leading]\nbuttons of the system layout and the content bar the [trailing] ones.', signature: '', constructors: [], properties: [], methods: [], values: [ApiMember(name: 'both', signature: '', doc: 'Both sides of the system button layout.'), ApiMember(name: 'leading', signature: '', doc: 'Only the leading side, such as macOS buttons or a left-side close.'), ApiMember(name: 'trailing', signature: '', doc: 'Only the trailing side.')]),
  'Oito2WindowCloseGuard': ApiEntry(kind: 'abstract class', package: 'oito2_ui', doc: 'A window controller that asks handlers before the window closes, such\nas the handler of an `Oito2UnsavedChangesGuard` with unsaved changes.\n\nWhile at least one handler is added, a request to close the window,\nfrom the title bar, the keyboard or the window manager, waits for the\nhandlers, the last added first, and closes the window only when every\none of them completes with true. Without handlers the window closes as\nusual.\n\nAn [Oito2WindowController] may also implement this interface; widgets\ncheck for it with `is`.', signature: '', constructors: [ApiConstructor(name: 'Oito2WindowCloseGuard', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [], methods: [ApiMember(name: 'addCloseHandler', signature: 'addCloseHandler(Oito2WindowCloseHandler handler) → void', doc: 'Adds [handler], asked before the window closes.'), ApiMember(name: 'removeCloseHandler', signature: 'removeCloseHandler(Oito2WindowCloseHandler handler) → void', doc: 'Removes [handler], added by [addCloseHandler].')], values: []),
  'Oito2WindowCloseHandler': ApiEntry(kind: 'typedef', package: 'oito2_ui', doc: 'Asked before the window closes; completes with whether the window may\nclose.', signature: 'Future<bool> Function()', constructors: [], properties: [], methods: [], values: []),
  'Oito2WindowControl': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A single window control button drawn in the visual family of [style].\n\nThe button stays out of keyboard focus traversal on purpose, as native\nwindow buttons do: Tab skips it, and keyboard users reach the same\nactions through the platform\'s window shortcuts. It exposes its\n[label] to assistive technologies.\n\nWhere the theme pads tap targets (touch platforms), the button takes a\nbox of at least [Oito2Sizes.minTouchTarget] on each axis, with its\nshape drawn at the same size in the middle, and the whole box takes\ntaps.', signature: '', constructors: [ApiConstructor(name: 'Oito2WindowControl', doc: 'Creates a window control button.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'type', type: 'Oito2WindowControlType', isRequired: true, isNamed: true, defaultValue: '', doc: 'The action and glyph.'), ApiParameter(name: 'style', type: 'Oito2WindowControlStyle', isRequired: true, isNamed: true, defaultValue: '', doc: 'The visual family. [Oito2WindowControlStyle.none] draws nothing.'), ApiParameter(name: 'onPressed', type: 'VoidCallback?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called when the button is activated; null disables it.'), ApiParameter(name: 'label', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label; defaults to the localized label of [type].'), ApiParameter(name: 'foregroundColor', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The glyph color; defaults to the theme\'s `onSurface`.'), ApiParameter(name: 'height', type: 'double', isRequired: false, isNamed: true, defaultValue: 'Oito2Sizes.titleBarHeight', doc: 'The title bar height, which the full-height Windows buttons fill;\nother styles are [Oito2Sizes.windowControlSize] tall.'), ApiParameter(name: 'isActive', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the window is active; inactive macOS buttons turn grey.')])], properties: [ApiMember(name: 'macosWidth', signature: 'static double', doc: 'The width of a macOS-style button where the theme doesn\'t pad tap\ntargets: the native 20-pixel pitch of the traffic lights.')], methods: [ApiMember(name: 'widthFor', signature: 'static widthFor(Oito2WindowControlStyle style, double height) → double', doc: 'Returns the width this button takes for [style] where the theme\ndoesn\'t pad tap targets; every style has a fixed width, so [height]\ndoesn\'t change it. macOS-style buttons follow the native pitch\n([macosWidth]); the others are [Oito2Sizes.windowControlSize] wide,\nor [Oito2Sizes.windowsWindowControlWidth] for the Windows style.')], values: []),
  'Oito2WindowControlLabels': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Accessibility labels of the window control buttons that override the\n[Oito2Localizations] strings.\n\nA null label keeps the localized string.', signature: '', constructors: [ApiConstructor(name: 'Oito2WindowControlLabels', doc: 'Creates window control label overrides.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'minimize', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Label of [Oito2WindowControlType.minimize].'), ApiParameter(name: 'maximize', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Label of [Oito2WindowControlType.maximize].'), ApiParameter(name: 'restore', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Label of [Oito2WindowControlType.restore].'), ApiParameter(name: 'close', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Label of [Oito2WindowControlType.close].')])], properties: [], methods: [ApiMember(name: 'of', signature: 'of(Oito2WindowControlType type) → String?', doc: 'Returns the override for [type], or null when there is none.'), ApiMember(name: 'resolve', signature: 'static resolve(BuildContext context, Oito2WindowControlType type, Oito2WindowControlLabels? labels) → String', doc: 'Returns the label for [type]: the override from [labels] when there\nis one, otherwise the [Oito2Localizations] string of [context].')], values: []),
  'Oito2WindowControlStyle': ApiEntry(kind: 'enum', package: 'oito2_ui', doc: 'The visual family used to draw window control buttons.', signature: '', constructors: [], properties: [], methods: [ApiMember(name: 'resolve', signature: 'static resolve(Oito2Platform platform, Oito2DesktopEnvironment? desktopEnvironment) → Oito2WindowControlStyle', doc: 'Resolves the control style for [platform] and, on Linux, for the\n[desktopEnvironment].\n\nReturns [none] on the web and on touch platforms. Linux desktop\nenvironments without their own style use [gnome].')], values: [ApiMember(name: 'gnome', signature: '', doc: 'Round buttons on a neutral background, as in GNOME and its relatives.'), ApiMember(name: 'breeze', signature: '', doc: 'Flat glyph buttons, as in KDE Plasma\'s Breeze decoration.'), ApiMember(name: 'xfwm', signature: '', doc: 'Compact glyph buttons, as in Xfce\'s window manager.'), ApiMember(name: 'cosmic', signature: '', doc: 'Round buttons, as in COSMIC.'), ApiMember(name: 'windows', signature: '', doc: 'Rectangular buttons with a red close hover, as in Windows.'), ApiMember(name: 'macos', signature: '', doc: 'The native macOS traffic lights.'), ApiMember(name: 'none', signature: '', doc: 'No window controls: the browser or the mobile system owns the window.')]),
  'Oito2WindowControlType': ApiEntry(kind: 'enum', package: 'oito2_ui', doc: 'The action and glyph of a window control button.', signature: '', constructors: [], properties: [], methods: [], values: [ApiMember(name: 'minimize', signature: '', doc: 'Minimizes the window.'), ApiMember(name: 'maximize', signature: '', doc: 'Maximizes the window.'), ApiMember(name: 'restore', signature: '', doc: 'Restores a maximized window.'), ApiMember(name: 'close', signature: '', doc: 'Closes the window.')]),
  'Oito2WindowController': ApiEntry(kind: 'abstract class', package: 'oito2_ui', doc: 'Controls the native window that hosts the app.\n\n`oito2_ui` only defines this contract; the `oito2_ui_window` package\nimplements it on Linux, Windows and macOS.', signature: '', constructors: [ApiConstructor(name: 'Oito2WindowController', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [ApiMember(name: 'state', signature: 'ValueListenable<Oito2WindowState>', doc: 'The current window state, updated as the window changes.')], methods: [ApiMember(name: 'minimize', signature: 'minimize() → Future<void>', doc: 'Minimizes the window.'), ApiMember(name: 'toggleMaximize', signature: 'toggleMaximize() → Future<void>', doc: 'Maximizes the window, or restores it when it is maximized.'), ApiMember(name: 'close', signature: 'close() → Future<void>', doc: 'Asks the window to close.'), ApiMember(name: 'startDrag', signature: 'startDrag() → Future<void>', doc: 'Starts moving the window with the pointer that is currently pressed.'), ApiMember(name: 'showMenu', signature: 'showMenu() → Future<void>', doc: 'Shows the native window menu, when [Oito2WindowState.canShowMenu] is\ntrue.')], values: []),
  'Oito2WindowScope': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Exposes an [Oito2WindowController] to the widgets below it.', signature: '', constructors: [ApiConstructor(name: 'Oito2WindowScope', doc: 'Creates a scope that provides [controller] to [child].', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'controller', type: 'Oito2WindowController?', isRequired: true, isNamed: true, defaultValue: '', doc: 'The controller provided to descendant widgets, or null when the app\ndoesn\'t control its window (for example on the web).'), ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: '')])], properties: [], methods: [ApiMember(name: 'maybeOf', signature: 'static maybeOf(BuildContext context) → Oito2WindowController?', doc: 'Returns the controller of the closest enclosing [Oito2WindowScope], or\nnull when there is none.')], values: []),
  'Oito2WindowState': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'The state of the native window, as shown by the title bar.', signature: '', constructors: [ApiConstructor(name: 'Oito2WindowState', doc: 'Creates a window state.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'isMaximized', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the window fills the work area.'), ApiParameter(name: 'isFullScreen', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the window is in full-screen mode.'), ApiParameter(name: 'isActive', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the window has the input focus.'), ApiParameter(name: 'canShowMenu', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the platform can show the native window menu.')])], properties: [], methods: [ApiMember(name: 'copyWith', signature: 'copyWith(bool? isMaximized, bool? isFullScreen, bool? isActive, bool? canShowMenu) → Oito2WindowState', doc: 'Returns a copy with the given fields replaced.')], values: []),
  'Oito2WindowTitleBar': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'The app window\'s title bar, adapted to the platform.\n\n- On native Linux and Windows it is an [Oito2TitleBar] with the window\n  control style and button layout of [Oito2SystemScope], driven by the\n  [Oito2WindowScope] controller.\n- On native macOS it keeps room for the native traffic lights instead\n  of drawing its own buttons.\n- On the web it shows the title and actions without window buttons,\n  since the browser owns the page lifecycle.\n- On touch platforms it is a regular [AppBar], which handles the\n  status bar safe area. Inside an [Oito2NavigationPage] that shows its\n  bottom bar, the page\'s leading widget fills an empty [leading] and\n  its trailing widget follows the [actions].', signature: '', constructors: [ApiConstructor(name: 'Oito2WindowTitleBar', doc: 'Creates an adaptive window title bar.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'title', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The title, usually a [Text].'), ApiParameter(name: 'leading', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A widget placed before the title.'), ApiParameter(name: 'leadingWidth', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The width given to [leading] on touch platforms, where the bar is an\n[AppBar]; defaults to the AppBar\'s square leading slot. Set it when\n[leading] holds more than one button. Desktop and web bars size\n[leading] to its content and ignore it.'), ApiParameter(name: 'actions', type: 'List<Widget>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: 'Widgets placed after the title.'), ApiParameter(name: 'centerTitle', type: 'bool?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Whether the title is centered; defaults to the theme.'), ApiParameter(name: 'style', type: 'Oito2TitleBarStyle?', isRequired: false, isNamed: true, defaultValue: '', doc: 'How the bar is presented on desktop platforms; defaults to the theme.'), ApiParameter(name: 'controller', type: 'Oito2WindowController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The window controller; defaults to the closest [Oito2WindowScope].'), ApiParameter(name: 'labels', type: 'Oito2WindowControlLabels?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Overrides of the window buttons\' accessibility labels, which\notherwise come from [Oito2Localizations].'), ApiParameter(name: 'platform', type: 'Oito2Platform?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The platform used to compute [preferredSize], which is read before\nthe widget has a context; defaults to [Oito2Platform.current]. The\nlayout itself follows [Oito2SystemScope], and [preferredSize] ignores\na themed title bar height.'), ApiParameter(name: 'buttonSides', type: 'Oito2WindowButtonSides', isRequired: false, isNamed: true, defaultValue: 'Oito2WindowButtonSides.both', doc: 'Which side\'s window buttons the bar shows, for split title bars.'), ApiParameter(name: 'backgroundColor', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The bar background on desktop and the web; defaults to the theme.'), ApiParameter(name: 'border', type: 'BorderSide?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The bottom border on desktop and the web; defaults to the theme.'), ApiParameter(name: 'interactiveTitle', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether [title] takes pointer input; see\n[Oito2TitleBar.interactiveTitle].')])], properties: [], methods: [], values: []),
  'oito2ColorFromHex': ApiEntry(kind: 'function', package: 'oito2_ui', doc: 'Parses [text] as `#RGB`, `#RRGGBB` or `#RRGGBBAA`, with or without\n`#` and surrounding whitespace.\n\nReturns null when [text] is not one of these forms.', signature: 'oito2ColorFromHex(String text) → Color?', constructors: [], properties: [], methods: [], values: []),
  'oito2ColorToHex': ApiEntry(kind: 'function', package: 'oito2_ui', doc: 'Returns [color] formatted as `#RRGGBB`, or `#RRGGBBAA` when it is\ntranslucent and [withAlpha] is set.', signature: 'oito2ColorToHex(Color color, bool withAlpha) → String', constructors: [], properties: [], methods: [], values: []),
  'oito2FormatDuration': ApiEntry(kind: 'function', package: 'oito2_ui', doc: 'Formats [duration] as `m:ss`, or `h:mm:ss` from an hour, with tenths\nof a second (truncated) when [tenths] is set.\n\nA negative [duration] gets a leading minus sign.', signature: 'oito2FormatDuration(Duration duration, bool tenths) → String', constructors: [], properties: [], methods: [], values: []),
  'oito2Initials': ApiEntry(kind: 'function', package: 'oito2_ui', doc: 'Returns the initials of [name]: the first letters of its first and\nlast words, in upper case, or an empty string when [name] is blank.\n\nA letter is a whole user-perceived character, so decomposed accents\nand emoji sequences stay intact.', signature: 'oito2Initials(String name) → String', constructors: [], properties: [], methods: [], values: []),
  'oito2IsoWeekNumber': ApiEntry(kind: 'function', package: 'oito2_ui', doc: 'Returns the ISO 8601 week number of [date]: weeks start on Monday and week 1\nholds the year\'s first Thursday.', signature: 'oito2IsoWeekNumber(DateTime date) → int', constructors: [], properties: [], methods: [], values: []),
  'oito2JsonTree': ApiEntry(kind: 'function', package: 'oito2_ui', doc: 'Returns the tree of decoded JSON [data]: objects and lists become\nbranches, other values leaves, and the top node is labeled\n[rootLabel]. Node values are JSON paths, such as `\$.items[0].name`.', signature: 'oito2JsonTree(Object? data, String rootLabel) → Oito2TreeCollection<({String key, Object? value})>', constructors: [], properties: [], methods: [], values: []),
  'oito2PageTransitionsTheme': ApiEntry(kind: 'function', package: 'oito2_ui', doc: 'Returns the page transitions for every platform:\n[Oito2DesktopPageTransitionsBuilder] on Linux and Windows, and the\nMaterial defaults elsewhere (Cupertino transitions on iOS and macOS,\npredictive back on Android).', signature: 'oito2PageTransitionsTheme() → PageTransitionsTheme', constructors: [], properties: [], methods: [], values: []),
  'oito2PaginationItems': ApiEntry(kind: 'function', package: 'oito2_ui', doc: 'The page numbers a pagination shows for [page] of [count], with null\nfor an ellipsis.\n\nIt keeps [boundaryCount] pages at each end and [siblingCount] pages on\neach side of [page], and always returns the same number of items for a\ngiven [count], so the buttons don\'t shift as the page changes. An\nellipsis never stands for a single page. Pages count from 1, and a\n[count] of zero or less gives an empty list.\n\nThrows an [AssertionError] in debug mode when [siblingCount] or\n[boundaryCount] is negative.', signature: 'oito2PaginationItems(int page, int count, int siblingCount, int boundaryCount) → List<int?>', constructors: [], properties: [], methods: [], values: []),
  'oito2UsesCommandKey': ApiEntry(kind: 'function', package: 'oito2_ui', doc: 'Whether [platform] uses Command, rather than Control, as the primary\nshortcut modifier: macOS and iOS.', signature: 'oito2UsesCommandKey(TargetPlatform platform) → bool', constructors: [], properties: [], methods: [], values: []),
  'showOito2CommandPalette': ApiEntry(kind: 'function', package: 'oito2_ui', doc: 'Opens the command palette over [context]: a search field above the\ncommands available at [context] (or [commands] when given), each with\nits shortcut. Disabled commands are left out, [commands] included.\n\nTyping filters the commands to those whose label, description, group\nand keywords contain every typed word, ignoring case and accents.\nCommands whose label starts with the first word come first, then those\nwhose label contains every word. The arrow keys move the highlight,\nEnter or a click closes the palette and runs a command, and Escape\ncloses it.', signature: 'showOito2CommandPalette(BuildContext context, List<Oito2Command>? commands) → Future<void>', constructors: [], properties: [], methods: [], values: []),
  'showOito2Sheet': ApiEntry(kind: 'function', package: 'oito2_ui', doc: 'Shows a sheet built by [builder] sliding in from [side], usually with\nan [Oito2Sheet] as its content, and completes with the value it is\nclosed with.\n\nA [modal] sheet dims the page and keeps the focus and assistive\ntechnologies inside it; a tap on the dimmed page closes it when\n[dismissible]. A non-modal sheet leaves the page usable beside it.\nEither closes on Escape and, when [dismissible], when dragged toward\nits edge.\n\nA side sheet is [size] wide (360 by default). A bottom sheet is as\ntall as its content, up to 90% of the window, unless [snapPoints]\ngives the heights it rests at as fractions of the window height,\nascending, starting at the [initialSnap] index; its handle then moves\nbetween them by drag, by the arrow keys, or by a tap, Enter or Space,\nwhich cycle to the next height.\n\nThrows an [AssertionError] in debug mode when [snapPoints] is given for\na side sheet, or when it is empty or [initialSnap] does not index it.', signature: 'showOito2Sheet(BuildContext context, WidgetBuilder builder, Oito2SheetSide side, bool modal, bool dismissible, double? size, List<double>? snapPoints, int initialSnap, String? semanticLabel) → Future<T?>', constructors: [], properties: [], methods: [], values: []),
  'showOito2ShortcutsHelp': ApiEntry(kind: 'function', package: 'oito2_ui', doc: 'Opens the keyboard shortcuts help over [context]: a dialog titled\n[title] (the localized "Keyboard shortcuts" by default) with an\n[Oito2ShortcutsHelpView] of [commands].\n\n[commands] defaults to the commands available at [context], disabled\nones included (see [Oito2Commands.availableAt]). Only commands with a\nshortcut are listed. The search field has the focus when the dialog\nopens; Escape on an empty search field or on a row closes the dialog,\nas does the close button.\n\nWhile a help dialog opened by this function is showing on the same\nroot `Navigator`, another call opens nothing and returns the future of\nthe open dialog, so pressing\nF1 again, with an [Oito2Commands] scope above the `Navigator`, doesn\'t\nstack a second help.\n\nReturns a future that completes when the dialog closes.', signature: 'showOito2ShortcutsHelp(BuildContext context, Iterable<Oito2Command>? commands, String? title) → Future<void>', constructors: [], properties: [], methods: [], values: []),
  'showOito2UnsavedChangesDialog': ApiEntry(kind: 'function', package: 'oito2_ui', doc: 'Asks whether to leave unsaved changes, in a dialog with the localized\n"Keep editing" and "Discard" buttons and, when [canSave], "Save".\n\n"Keep editing" takes the focus, so Enter doesn\'t drop the changes.\nReturns the picked action, or [Oito2UnsavedChangesAction.keepEditing]\nwhen the dialog is dismissed.', signature: 'showOito2UnsavedChangesDialog(BuildContext context, bool canSave) → Future<Oito2UnsavedChangesAction>', constructors: [], properties: [], methods: [], values: []),
  'Oito2NativeWindowController': ApiEntry(kind: 'class', package: 'oito2_ui_window', doc: 'The [Oito2WindowController] of the app\'s native window on Linux, Windows\nand macOS, backed by `window_manager`.\n\n`Oito2Window.ensureInitialized` creates it; the app keeps it, hands it\nto an [Oito2WindowScope] and may [dispose] it. It forwards the window\nactions to the native window and keeps [state] in sync with its\nmaximize, focus and full-screen events.\n\nAs an [Oito2WindowCloseGuard], it holds every native close request while\nclose handlers are added: the request asks the handlers and goes through\nonce every one of them allows it, or keeps the window open otherwise.', signature: '', constructors: [], properties: [], methods: [ApiMember(name: 'refresh', signature: 'refresh() → Future<void>', doc: 'Reads the maximized, full-screen and focus state from the window.\n\nThe last known state stays when the window can\'t be queried, when a\nwindow event arrives meanwhile, or after [dispose].'), ApiMember(name: 'dispose', signature: 'dispose() → void', doc: 'Stops listening to window events, which lets the native close through\nagain when close handlers held it back, forgets the close handlers\nand releases [state].\n\nCalling it again does nothing.')], values: []),
  'Oito2Window': ApiEntry(kind: 'abstract class', package: 'oito2_ui_window', doc: 'Entry point for native window integration.', signature: '', constructors: [ApiConstructor(name: 'Oito2Window', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [], methods: [ApiMember(name: 'ensureInitialized', signature: 'static ensureInitialized(String? title, Size? size, Size? minimumSize, bool center) → Future<Oito2WindowController?>', doc: 'Hides the native title bar, applies the initial window options, shows\nthe window and returns an [Oito2WindowController] for it.\n\n[title] sets the window title, [size] the initial size and\n[minimumSize] the smallest size the user can resize it to; when\n[center] is true the window opens centered on the screen.\n\nCall it in `main` before `runApp`, and provide the result through an\n[Oito2WindowScope]. Returns null on the web, Android and iOS, where\nthe app doesn\'t own a desktop window, and when no native window can\nbe found; `Oito2WindowTitleBar` then adapts on its own. On\ndesktop the controller is an [Oito2NativeWindowController], which the\napp can dispose when it no longer needs it; it is only created here.\n\nOn macOS the native traffic lights stay visible over the hidden\ntitle bar.')], values: []),
  'Oito2AccentSource': ApiEntry(kind: 'abstract class', package: 'oito2_ui_settings', doc: 'Reads the accent color the operating system or the toolkit theme\nexposes.', signature: '', constructors: [ApiConstructor(name: 'Oito2AccentSource', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [], methods: [ApiMember(name: 'read', signature: 'read() → Future<Color?>', doc: 'Returns the accent color, or null when none is available.'), ApiMember(name: 'changes', signature: 'changes() → Stream<void>', doc: 'Emits whenever the accent color changes.'), ApiMember(name: 'close', signature: 'close() → Future<void>', doc: 'Releases the connections the source holds.')], values: []),
