  'Oito2ConfigFileSource': ApiEntry(kind: 'abstract class', package: 'oito2_ui_settings', doc: 'Reads text files from the user\'s configuration directory\n(`\$XDG_CONFIG_HOME`, by default `~/.config`).', signature: '', constructors: [ApiConstructor(name: 'Oito2ConfigFileSource', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [], methods: [ApiMember(name: 'read', signature: 'read(String relativePath) → Future<String?>', doc: 'Returns the content of the file at [relativePath], or null when it\ndoesn\'t exist or can\'t be read.'), ApiMember(name: 'changes', signature: 'changes(String relativePath) → Stream<void>', doc: 'Emits whenever the file at [relativePath] changes.')], values: []),
  'Oito2ConfigParsers': ApiEntry(kind: 'abstract class', package: 'oito2_ui_settings', doc: 'Parsers for the configuration file formats of Linux desktops.', signature: '', constructors: [ApiConstructor(name: 'Oito2ConfigParsers', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [], methods: [ApiMember(name: 'iniValue', signature: 'static iniValue(String content, String group, String key) → String?', doc: 'Returns the value of [key] in [group] of the INI-style [content], such\nas KDE\'s `kwinrc` and `kdeglobals`, or null when it is missing.\n\nGroup headers are `[name]`; nested KDE groups like `[a][b]` match the\nname `a][b`. Lines starting with `#` or `;` are comments. Keys with\na locale or KDE flag suffix (`key[\$e]`) are ignored.'), ApiMember(name: 'xfconfProperty', signature: 'static xfconfProperty(String content, String name) → String?', doc: 'Returns the `value` attribute of the `<property name="[name]">`\nelement in the xfconf channel file [content], such as `xfwm4.xml`, or\nnull when it is missing. XML entities in the value are decoded.'), ApiMember(name: 'cosmicBool', signature: 'static cosmicBool(String content) → bool?', doc: 'Parses [content] as a `true`/`false` file, as COSMIC stores its\nboolean settings.\n\nReturns null for any other content.'), ApiMember(name: 'cosmicOptionalInt', signature: 'static cosmicOptionalInt(String content) → int?', doc: 'Parses [content] as a COSMIC optional integer, such as `Some(48)` or a\nbare `48`.\n\nReturns null for `None` and for any other content.'), ApiMember(name: 'kdeColor', signature: 'static kdeColor(String value) → Color?', doc: 'Parses [value] as a KDE `r,g,b` color, such as the value of\n`AccentColor=61,174,233`, or returns null when it isn\'t one with\nthree components from 0 to 255.')], values: []),
  'Oito2EmptySource': ApiEntry(kind: 'class', package: 'oito2_ui_settings', doc: 'A source with no values and no changes, used where a platform has no\nsuch store.', signature: '', constructors: [ApiConstructor(name: 'Oito2EmptySource', doc: 'Creates an empty source.', isConst: true, isFactory: false, parameters: [])], properties: [], methods: [], values: []),
  'Oito2GSettingsSource': ApiEntry(kind: 'abstract class', package: 'oito2_ui_settings', doc: 'Reads values from GSettings, the settings store of GNOME and the\ndesktops derived from it.', signature: '', constructors: [ApiConstructor(name: 'Oito2GSettingsSource', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [], methods: [ApiMember(name: 'read', signature: 'read(String schema, String key) → Future<Object?>', doc: 'Returns the value of [key] in [schema] as a Dart value (`String`,\n`bool`, `int`, ...), or null when the schema or key doesn\'t exist.'), ApiMember(name: 'changes', signature: 'changes(String schema) → Stream<void>', doc: 'Emits whenever a key in [schema] changes.'), ApiMember(name: 'close', signature: 'close() → Future<void>', doc: 'Releases the connections the source holds.')], values: []),
  'Oito2ReducedMotionSource': ApiEntry(kind: 'abstract class', package: 'oito2_ui_settings', doc: 'Reads whether the desktop asks for reduced motion.', signature: '', constructors: [ApiConstructor(name: 'Oito2ReducedMotionSource', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [], methods: [ApiMember(name: 'read', signature: 'read() → Future<bool?>', doc: 'Returns true when the desktop asks for reduced motion, false when it\nstates no such preference, or null when none is available.'), ApiMember(name: 'changes', signature: 'changes() → Stream<void>', doc: 'Emits whenever the preference changes.'), ApiMember(name: 'close', signature: 'close() → Future<void>', doc: 'Releases the connections the source holds.')], values: []),
  'Oito2Settings': ApiEntry(kind: 'abstract class', package: 'oito2_ui_settings', doc: 'Entry point for reading the operating system preferences.', signature: '', constructors: [ApiConstructor(name: 'Oito2Settings', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [], methods: [ApiMember(name: 'reader', signature: 'static reader(Oito2Platform? platform) → Oito2SystemSettingsReader', doc: 'Creates the reader for [platform] (default [Oito2Platform.current])\nbacked by the real system stores.'), ApiMember(name: 'load', signature: 'static load(Oito2Platform? platform) → Future<Oito2SystemSettings>', doc: 'Reads the current system settings of [platform] once, then releases\nthe reader.'), ApiMember(name: 'watch', signature: 'static watch(Oito2Platform? platform) → Stream<Oito2SystemSettings>', doc: 'Emits the current system settings of [platform], then every change.\n\nThe reader, with its system connections, is created when the stream\nis listened to and released when the subscription is cancelled, so a\nstream that is never listened to opens nothing.')], values: []),
  'Oito2SystemSettingsReader': ApiEntry(kind: 'class', package: 'oito2_ui_settings', doc: 'Builds [Oito2SystemSettings] from the system stores of the current\nplatform.\n\nOn native Linux it detects the desktop environment from [environment]\nand reads the window button layout per desktop:\n\n- GNOME, Budgie, Pantheon, Unity and unknown desktops:\n  `org.gnome.desktop.wm.preferences button-layout`.\n- Cinnamon: `org.cinnamon.desktop.wm.preferences button-layout`.\n- MATE: `org.mate.Marco.general button-layout`.\n- KDE Plasma: `ButtonsOnLeft` and `ButtonsOnRight` in the\n  `[org.kde.kdecoration2]` group of `kwinrc`.\n- Xfce: `button_layout` in `xfwm4.xml`.\n- COSMIC: `com.system76.CosmicTk/v1/show_minimize` and\n  `show_maximize`.\n\nThe accent comes from [portalAccent], the desktop portal\'s\n`org.freedesktop.appearance accent-color`. Without a portal accent, KDE\nPlasma reads `AccentColor` in the `[General]` group of `kdeglobals` and\nGNOME reads `org.gnome.desktop.interface accent-color`; other desktops,\nand these two when their key is missing, use the toolkit theme through\n[accent]. Cinnamon and MATE read again when their own interface schema\nchanges, such as when the GTK theme changes.\n\nKDE Plasma reads high contrast from a `kdeglobals` color scheme whose\nname contains "contrast"; every other desktop from\n`org.gnome.desktop.a11y.interface high-contrast` or a `HighContrast` GTK\ntheme.\n\nThe color scheme comes from [colorScheme], the desktop portal\'s\n`org.freedesktop.appearance color-scheme`. When the portal states no\npreference, the desktop store decides: `org.gnome.desktop.interface\ncolor-scheme` (`prefer-dark` or `prefer-light`) on the GNOME family,\nCinnamon and MATE; a `kdeglobals` color scheme or look-and-feel package\nwhose name contains "dark" on KDE Plasma; the\n`com.system76.CosmicTheme.Mode/v1/is_dark` flag on COSMIC. Xfce and\nLXQt have no store beyond the portal.\n\nReduced motion is true when [reducedMotion], the desktop portal\'s\n`org.freedesktop.appearance reduced-motion`, or a desktop key asks for\nit: `org.gnome.desktop.interface enable-animations` turned off or\n`org.gnome.desktop.a11y.interface reduced-motion` set to `reduce` on\nthe GNOME family; `org.cinnamon.desktop.interface enable-animations`\nor `org.cinnamon desktop-effects-workspace` turned off on Cinnamon;\n`org.mate.interface enable-animations` or `gtk-enable-animations`\nturned off on MATE; `AnimationDurationFactor=0` in the `[KDE]` group of\n`kdeglobals` on KDE Plasma. It is false when a source states no such\npreference, and null when none is available, as on Xfce, LXQt and\nCOSMIC without a portal that reports it.\n\nThe text scale factor comes from `text-scaling-factor` in\n`org.gnome.desktop.interface` (GNOME family) or\n`org.cinnamon.desktop.interface` (Cinnamon); from a font DPI divided by\n96 elsewhere: `org.mate.font-rendering dpi` on MATE (null while it is\n0, the automatic DPI), `forceFontDPI` in the `[General]` group of\n`kcmfonts` on KDE Plasma on X11 (1.0 while it isn\'t forced, and always\n1.0 in a Wayland session, where Plasma doesn\'t apply it) and `Xft/DPI` in\n`xsettings.xml` on Xfce (1.0 without the property, null for the\nautomatic DPI). COSMIC and LXQt have no text scaling setting.\n\nThe cursor size comes from `cursor-size` in\n`org.gnome.desktop.interface` (GNOME family),\n`org.cinnamon.desktop.interface` (Cinnamon) or\n`org.mate.peripherals-mouse` (MATE); from `cursorSize` in the `[Mouse]`\ngroup of `kcminputrc` on KDE Plasma (24 without it),\n`Gtk/CursorThemeSize` in `xsettings.xml` on Xfce,\n`com.system76.CosmicComp/v1/cursor_size` on COSMIC and `cursor_size` in\nthe `[Mouse]` group of `lxqt/session.conf` on LXQt. Sizes of 0 or less\nmean the cursor theme\'s default and read as null.\n\nMissing values fall back to each desktop\'s defaults. On other\nplatforms the accent comes from [accent], the color scheme from\n[platformBrightness], reduced motion from [platformReduceMotion] and\nthe text scale factor from [platformTextScaleFactor]; the cursor size\nis null. [platformHighContrast] is combined with the desktop preference\non every platform, and [platformReduceMotion] with the desktop\npreference on native Linux.', signature: '', constructors: [ApiConstructor(name: 'Oito2SystemSettingsReader', doc: 'Creates a reader for [platform] over the given sources.\n\nEvery source defaults to an [Oito2EmptySource], [platformHighContrast]\nto a function that returns false and [platformBrightness],\n[platformReduceMotion] and [platformTextScaleFactor] to functions that\nreturn null.', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'platform', type: 'Oito2Platform', isRequired: true, isNamed: true, defaultValue: '', doc: 'The platform the settings are read for.'), ApiParameter(name: 'environment', type: 'Map<String, String>', isRequired: false, isNamed: true, defaultValue: 'const {}', doc: 'The process environment variables.'), ApiParameter(name: 'gsettings', type: 'Oito2GSettingsSource', isRequired: false, isNamed: true, defaultValue: 'const Oito2EmptySource()', doc: 'The GSettings store.'), ApiParameter(name: 'configFiles', type: 'Oito2ConfigFileSource', isRequired: false, isNamed: true, defaultValue: 'const Oito2EmptySource()', doc: 'The user\'s configuration files.'), ApiParameter(name: 'accent', type: 'Oito2AccentSource', isRequired: false, isNamed: true, defaultValue: 'const Oito2EmptySource()', doc: 'The toolkit or operating system accent color.'), ApiParameter(name: 'portalAccent', type: 'Oito2AccentSource', isRequired: false, isNamed: true, defaultValue: 'const Oito2EmptySource()', doc: 'The desktop portal\'s accent color, read first on native Linux.'), ApiParameter(name: 'colorScheme', type: 'Oito2ColorSchemeSource', isRequired: false, isNamed: true, defaultValue: 'const Oito2EmptySource()', doc: 'The desktop portal\'s color scheme preference.'), ApiParameter(name: 'reducedMotion', type: 'Oito2ReducedMotionSource', isRequired: false, isNamed: true, defaultValue: 'const Oito2EmptySource()', doc: 'The desktop portal\'s reduced motion preference.'), ApiParameter(name: 'platformHighContrast', type: 'bool Function()', isRequired: false, isNamed: true, defaultValue: '', doc: 'Whether the platform accessibility settings ask for high contrast.'), ApiParameter(name: 'platformBrightness', type: 'Brightness? Function()', isRequired: false, isNamed: true, defaultValue: '', doc: 'The light or dark scheme the platform reports outside native Linux,\nor null when it reports none.'), ApiParameter(name: 'platformReduceMotion', type: 'bool? Function()', isRequired: false, isNamed: true, defaultValue: '', doc: 'Whether the platform asks for reduced motion, or null when it doesn\'t\nreport the preference.'), ApiParameter(name: 'platformTextScaleFactor', type: 'double? Function()', isRequired: false, isNamed: true, defaultValue: '', doc: 'The text scale factor the platform reports, or null when it reports\nnone.'), ApiParameter(name: 'debounce', type: 'Duration', isRequired: false, isNamed: true, defaultValue: 'const Duration(milliseconds: 150)', doc: 'How long [watch] waits after a change before reading again, so a\nburst of changes produces one update.'), ApiParameter(name: 'onClose', type: 'Future<void> Function()?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called by [close] after the sources are closed, to release what the\nsources share, such as D-Bus connections passed to them.')])], properties: [ApiMember(name: 'portalTimeout', signature: 'static Duration', doc: 'How long [read] waits for each desktop portal setting before it\ntakes the setting as missing.'), ApiMember(name: 'desktopEnvironment', signature: 'Oito2DesktopEnvironment?', doc: 'The detected desktop environment, or null outside native Linux.')], methods: [ApiMember(name: 'read', signature: 'read() → Future<Oito2SystemSettings>', doc: 'Reads the current settings from every source.\n\nA source that fails to read counts as missing, so its value falls\nback to the desktop default. On native Linux the independent\nsettings are read at the same time, each configuration file is read\nonce, and a desktop portal setting that doesn\'t answer within\n[portalTimeout] counts as missing; [watch] reads again when the\nportal reports a change.'), ApiMember(name: 'watch', signature: 'watch() → Stream<Oito2SystemSettings>', doc: 'Emits the current settings, then the new settings whenever a source\nreports a change that alters them.\n\nA read that a newer one overtakes is dropped, and a failed read is\nemitted as an error.'), ApiMember(name: 'close', signature: 'close() → Future<void>', doc: 'Releases the connections the system stores hold, such as the D-Bus\nconnections of GSettings and of the desktop portal. The reader can\'t\nbe used afterwards.')], values: []),
  'Oito2SystemSettingsScope': ApiEntry(kind: 'class', package: 'oito2_ui_settings', doc: 'Keeps an [Oito2SystemScope] in sync with the operating system.\n\nShows [initialSettings] (or the platform fallback) until the first read\ncompletes, then rebuilds [child] whenever the desktop environment\nsettings, the accent color, the platform brightness, the text scale or\nthe accessibility preferences change.\n\nIt also applies two preferences to the [MediaQuery] of [child]:\n\n- When [Oito2SystemSettings.reduceMotion] is true,\n  [MediaQueryData.disableAnimations] becomes true. It is never turned\n  off, so a platform that already disables animations keeps them off.\n- On native Linux desktops whose text scale Flutter doesn\'t read (KDE\n  Plasma, Xfce, Cinnamon, MATE, COSMIC and LXQt), a known\n  [Oito2SystemSettings.textScaleFactor] replaces the text scaler\n  Flutter derives from GNOME\'s `text-scaling-factor`. The factor\n  replaces that scaler instead of multiplying it, so text is scaled\n  once. On the GNOME family (GNOME, Budgie, Pantheon, Unity and unknown\n  desktops) and on other platforms, Flutter already applies the\n  system text scale and the scaler is left as is. A scaler that an\n  ancestor [MediaQuery] changed is also left as is.\n\nThe cursor size is only exposed: the cursor theme and its size are\napplied by the toolkit and the compositor.', signature: '', constructors: [ApiConstructor(name: 'Oito2SystemSettingsScope', doc: 'Creates a scope that watches the system settings for [child].', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'initialSettings', type: 'Oito2SystemSettings?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The settings shown before the first read, typically the result of\n[Oito2Settings.load] awaited in `main`.'), ApiParameter(name: 'reader', type: 'Oito2SystemSettingsReader?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The reader to watch; defaults to [Oito2Settings.reader].'), ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The widget below the scope.')])], properties: [], methods: [], values: []),
  'Oito2CodeBlock': ApiEntry(kind: 'class', package: 'oito2_ui_syntax', doc: 'A read-only, selectable block of highlighted code on the theme\'s\ncontainer surface, with optional line numbers, highlighted lines and a\ncopy button.\n\nThe colors come from the theme\'s [Oito2SyntaxTheme], or from the oito2\nbase scheme of the current brightness when the theme has none. Long\nlines scroll horizontally instead of wrapping.\n\nCode up to [backgroundHighlightLength] is highlighted on the UI thread\nas the block builds. Longer code, up to [maxHighlightLength], first\nshows as plain text in the foreground color, with a small notice in the\ntop end corner, while another isolate highlights it; the colors then\nreplace the plain text with the same layout. Code longer than\n[maxHighlightLength] stays plain text.\n\nCreating the block throws an [AssertionError] when [maxHighlightLength]\nor [backgroundHighlightLength] is negative.', signature: '', constructors: [ApiConstructor(name: 'Oito2CodeBlock', doc: 'Creates a code block.\n\nThrows an [AssertionError] when [maxHighlightLength] or\n[backgroundHighlightLength] is negative.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'code', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The source code.'), ApiParameter(name: 'language', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The language name or alias, such as `dart`; null or an unregistered\nname shows plain text.'), ApiParameter(name: 'highlighter', type: 'Oito2Highlighter?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The highlighter; defaults to [Oito2Highlighter.instance].'), ApiParameter(name: 'showLineNumbers', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether line numbers are shown.'), ApiParameter(name: 'highlightedLines', type: 'Set<int>', isRequired: false, isNamed: true, defaultValue: 'const {}', doc: 'The lines drawn on a tint of the primary color with a bar along\ntheir leading edge, counted from 1; numbers outside the code are\nignored.\n\nThe tint is drawn behind the text only, so the semantics of the\nblock don\'t change.'), ApiParameter(name: 'showCopyButton', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the copy button is shown.'), ApiParameter(name: 'textStyle', type: 'TextStyle?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The code text style; defaults to [Oito2CodeBlock.defaultTextStyle].'), ApiParameter(name: 'padding', type: 'EdgeInsetsGeometry', isRequired: false, isNamed: true, defaultValue: 'const EdgeInsets.all(Oito2Spacing.lg)', doc: 'Space around the code.'), ApiParameter(name: 'maxHighlightLength', type: 'int', isRequired: false, isNamed: true, defaultValue: 'defaultMaxHighlightLength', doc: 'The longest code, in UTF-16 code units, that is highlighted; longer\ncode shows as plain text in the foreground color.\n\nDefaults to [defaultMaxHighlightLength]. Highlighting takes time in\nproportion to the length of the code and blocks the UI meanwhile, so\nraise it only for code known to be short enough on the slowest\ntarget device.'), ApiParameter(name: 'backgroundHighlightLength', type: 'int', isRequired: false, isNamed: true, defaultValue: 'defaultBackgroundHighlightLength', doc: 'The longest code, in UTF-16 code units, that is highlighted on the UI\nthread; longer code, up to [maxHighlightLength], is highlighted in\nanother isolate.\n\nDefaults to [defaultBackgroundHighlightLength]. While the other\nisolate works, the code shows as plain text in the foreground color\nwith a notice that highlighting is being applied, announced once to\nassistive technologies. A value of [maxHighlightLength] or more\nhighlights everything on the UI thread.\n\nOn the web there are no other isolates, so the highlighting runs on\nthe UI thread after the plain text shows, and blocks the UI\nmeanwhile.')])], properties: [ApiMember(name: 'defaultMaxHighlightLength', signature: 'static int', doc: 'The default [maxHighlightLength]: 20 000 code units, which\nhighlight in about 50 milliseconds on a desktop computer.'), ApiMember(name: 'defaultBackgroundHighlightLength', signature: 'static int', doc: 'The default [backgroundHighlightLength]: 5 000 code units, which\nhighlight in under 10 milliseconds on a desktop computer.'), ApiMember(name: 'debugBackgroundTokenizer', signature: 'static Future<Oito2HighlightTokens?> Function(Oito2Highlighter, String, String)?', doc: 'Replaces the isolate that highlights long code, for tests; null runs\n[Oito2Highlighter.tokenize] with `compute`.\n\nThe function receives the block\'s highlighter, code and language and\nreturns the tokens, or null to keep the plain text.'), ApiMember(name: 'fontFamily', signature: 'static String', doc: 'The family name of JetBrains Mono as bundled by this package,\nincluding the package prefix.'), ApiMember(name: 'monospaceFallback', signature: 'static List<String>', doc: 'System monospace families used for glyphs the bundled font lacks, in\norder.'), ApiMember(name: 'defaultTextStyle', signature: 'static TextStyle', doc: 'The default code text style: 13-point bundled JetBrains Mono with\n1.45 line height.')], methods: [], values: []),
  'Oito2GitignoreMatch': ApiEntry(kind: 'class', package: 'oito2_ui_syntax', doc: 'The rule that decides whether a path is ignored, returned by\n[Oito2GitignoreMatcher.match].', signature: '', constructors: [ApiConstructor(name: 'Oito2GitignoreMatch', doc: 'Creates a match of [rule] on [path].', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'rule', type: 'Oito2GitignoreRule', isRequired: true, isNamed: false, defaultValue: '', doc: 'The last rule that matches [path].'), ApiParameter(name: 'path', type: 'String', isRequired: true, isNamed: false, defaultValue: '', doc: 'The path [rule] matches: the path asked about, or a directory that\nholds it and is ignored, since nothing inside an ignored directory\ncan be re-included.')])], properties: [ApiMember(name: 'isIgnored', signature: 'bool', doc: 'Whether the path asked about is ignored: false when [rule] is a\nnegated rule that re-includes it.')], methods: [], values: []),
  'Oito2GitignoreMatcher': ApiEntry(kind: 'class', package: 'oito2_ui_syntax', doc: 'Tells whether paths are ignored by the rules of a gitignore file,\nfollowing git\'s documented semantics.\n\n[parse] reads the rules: blank lines and lines starting with `#` are\nskipped; trailing spaces are dropped unless escaped with a backslash;\na leading `!` negates the rule, and a backslash makes `#` and `!`\nliteral; a trailing `/` matches only directories; a `/` at the start\nor in the middle anchors the rule to the gitignore file\'s directory,\notherwise it matches a name at any depth. In a pattern, `*` matches\nanything but `/`, `?` one character but `/`, and `[...]` one character\nof a class with ranges, `!` or `^` negation and POSIX classes such as\n`[:digit:]`. A leading `**/` matches in all directories, a trailing\n`/**` everything inside, and a middle `/**/` zero or more directories;\nother runs of asterisks act as `*`.\n\n[match] finds the rule that decides a path: the last matching rule\nwins, and a file inside an ignored directory can\'t be re-included.', signature: '', constructors: [ApiConstructor(name: 'Oito2GitignoreMatcher', doc: 'Creates a matcher with [rules], in the order they were written.', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'rules', type: 'Iterable<Oito2GitignoreRule>', isRequired: true, isNamed: false, defaultValue: '', doc: '')]), ApiConstructor(name: 'Oito2GitignoreMatcher.parse', doc: 'Returns a matcher with the rules written in [text], one a line.\n\nWith [ignoreCase], letters match in any case, as with git\'s\n`core.ignoreCase`.', isConst: false, isFactory: true, parameters: [ApiParameter(name: 'text', type: 'String', isRequired: true, isNamed: false, defaultValue: '', doc: ''), ApiParameter(name: 'ignoreCase', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: '')])], properties: [], methods: [ApiMember(name: 'match', signature: 'match(String path, bool isDirectory) → Oito2GitignoreMatch?', doc: 'Returns the rule that decides whether [path] is ignored, or null when\nno rule matches it.\n\n[path] is slash-separated and relative to the gitignore file\'s\ndirectory; it is a directory when [isDirectory] or when it ends with\n`/`. The directories that hold it are checked first, from the\noutermost: when one is ignored, the result is its rule and its\n[Oito2GitignoreMatch.path].'), ApiMember(name: 'isIgnored', signature: 'isIgnored(String path, bool isDirectory) → bool', doc: 'Returns whether [path] is ignored, as decided by [match].')], values: []),
  'Oito2GitignoreRule': ApiEntry(kind: 'class', package: 'oito2_ui_syntax', doc: 'One rule of a gitignore file, as parsed by\n[Oito2GitignoreMatcher.parse].', signature: '', constructors: [], properties: [ApiMember(name: 'line', signature: 'int', doc: 'The line of the rule in the gitignore text, counted from 1.'), ApiMember(name: 'pattern', signature: 'String', doc: 'The rule as written, without its unescaped trailing spaces, such as\n`!release.log` or `/build/`.'), ApiMember(name: 'negated', signature: 'bool', doc: 'Whether the rule starts with `!` and re-includes what it matches.'), ApiMember(name: 'directoryOnly', signature: 'bool', doc: 'Whether the rule ends with `/` and matches only directories.'), ApiMember(name: 'anchored', signature: 'bool', doc: 'Whether the rule has a `/` at its start or in its middle and matches\nonly paths relative to the gitignore file\'s directory; otherwise it\nmatches a name at any depth.'), ApiMember(name: 'isValid', signature: 'bool', doc: 'Whether the pattern is well formed; a rule with an unclosed `[` or a\ntrailing lone backslash matches nothing, as in git.')], methods: [ApiMember(name: 'matches', signature: 'matches(String path, bool isDirectory) → bool', doc: 'Returns whether the rule matches [path], a slash-separated path\nrelative to the gitignore file\'s directory, which is a directory\nwhen [isDirectory].\n\nOnly the path itself is compared: [Oito2GitignoreMatcher.match] also\nlooks at the directories that hold it. The time it takes grows with\nthe length of the pattern times the length of [path], whatever the\npattern.'), ApiMember(name: 'trimTrailingSpaces', signature: 'static trimTrailingSpaces(String line) → String', doc: 'Returns [line] without its trailing spaces, keeping a space escaped\nwith a backslash and dropping a carriage return.')], values: []),
  'Oito2HighlightTokens': ApiEntry(kind: 'class', package: 'oito2_ui_syntax', doc: 'The tokens of a piece of code: consecutive runs of text, each with the\nhighlight.js scope of the innermost token it belongs to, or none.\n\nMade by [Oito2Highlighter.tokenize]. The tokens hold no colors, so the\nsame tokens are colored with any palette by [toSpan], and they can be\nsent between isolates.', signature: '', constructors: [], properties: [ApiMember(name: 'code', signature: 'String', doc: 'The tokenized code.'), ApiMember(name: 'length', signature: 'int', doc: 'The number of runs.')], methods: [ApiMember(name: 'textAt', signature: 'textAt(int index) → String', doc: 'Returns the text of run [index], counted from 0.'), ApiMember(name: 'scopeAt', signature: 'scopeAt(int index) → String?', doc: 'Returns the highlight.js scope of run [index], counted from 0, such as\n`keyword` or `title.function`, or null for plain text.'), ApiMember(name: 'toSpan', signature: 'toSpan(Oito2SyntaxPalette palette, TextStyle? style) → TextSpan', doc: 'Returns the code colored with [palette] on top of [style] (whose\ncolor is replaced by the palette foreground), drawn the same as\n[Oito2Highlighter.highlight] draws it.\n\nThe span is flat: one child per run, each with its scope style or\nnone, under a parent with the base style.')], values: []),
  'Oito2Highlighter': ApiEntry(kind: 'class', package: 'oito2_ui_syntax', doc: 'Turns source code into a [TextSpan] colored with a\n[Oito2SyntaxPalette].\n\nTokenizing runs synchronously in pure Dart, with no native code and no\nasset loading.', signature: '', constructors: [ApiConstructor(name: 'Oito2Highlighter', doc: 'Creates a highlighter that knows [languages] (by default\n[oito2DefaultLanguages]).', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'languages', type: 'Map<String, Mode>?', isRequired: false, isNamed: true, defaultValue: '', doc: '')])], properties: [ApiMember(name: 'instance', signature: 'static Oito2Highlighter', doc: 'A shared highlighter with the default languages.')], methods: [ApiMember(name: 'supports', signature: 'supports(String language) → bool', doc: 'Whether [language] is registered, by name or by one of its aliases\n(such as `js` or `yml`), in any letter case.'), ApiMember(name: 'modeOf', signature: 'modeOf(String language) → Mode?', doc: 'Returns the grammar registered for [language], a name or alias in any\nletter case, or null when none is.'), ApiMember(name: 'highlight', signature: 'highlight(String code, Oito2SyntaxPalette palette, String? language, TextStyle? style, bool autoDetect) → TextSpan', doc: 'Returns [code] highlighted as [language] with [palette], on top of\n[style] (whose color is replaced by the palette foreground).\n\n[language] is a registered name or alias, in any letter case. When it\nisn\'t registered, or is null and [autoDetect] is false, the code is\nreturned unhighlighted in the foreground color. With [autoDetect], a\nnull [language] is guessed among the registered ones.'), ApiMember(name: 'tokenize', signature: 'tokenize(String code, String? language, bool autoDetect) → Oito2HighlightTokens?', doc: 'Returns the tokens of [code] as [language], to be colored later with\n[Oito2HighlightTokens.toSpan].\n\n[language] is a registered name or alias, in any letter case; with\n[autoDetect], a null [language] is guessed among the registered ones.\nReturns null when [language] isn\'t registered, or is null and\n[autoDetect] is false.\n\nThe highlighter and the result can be sent to another isolate, so\nthis can run off the UI thread, as `Oito2CodeBlock` does for long\ncode.')], values: []),
  'Oito2HighlighterTheme': ApiEntry(kind: 'abstract class', package: 'oito2_ui_syntax', doc: 'Builds `re_highlight` themes from a [Oito2SyntaxPalette].\n\nThe highlighter tokenizes code with highlight.js grammars, whose token\nscopes (such as `keyword`, `title.function` or `selector-tag`) are\nmapped here to the 11 palette roles. Scopes not listed render in the\nforeground color.', signature: '', constructors: [ApiConstructor(name: 'Oito2HighlighterTheme', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [ApiMember(name: 'scopeRoles', signature: 'static Map<String, Oito2SyntaxRole>', doc: 'The palette role of every highlight.js scope the theme colors.')], methods: [ApiMember(name: 'fromPalette', signature: 'static fromPalette(Oito2SyntaxPalette palette) → Map<String, TextStyle>', doc: 'Returns the scope styles for [palette]: every scope of [scopeRoles]\nin its role color, comments in italics, plus italic `emphasis` and\nbold `strong` for markup.')], values: []),
  'Oito2LineHighlight': ApiEntry(kind: 'class', package: 'oito2_ui_syntax', doc: 'The look of a highlighted code line: a light tint of the scheme\'s\nprimary color across the line and a bar in the text-safe primary tone\nalong its leading edge.\n\n`Oito2CodeBlock.highlightedLines` draws its lines with it; widgets that\nlay out code themselves, such as a code editor, call [paint] for each\nhighlighted line to draw them the same way.', signature: '', constructors: [ApiConstructor(name: 'Oito2LineHighlight', doc: 'Creates a line highlight with the [tint] and [bar] colors.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'tint', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The fill across the line.'), ApiParameter(name: 'bar', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The color of the bar along the leading edge.')]), ApiConstructor(name: 'Oito2LineHighlight.of', doc: 'Returns the line highlight for the closest theme: the primary color\nat 14% opacity for [tint], and [Oito2SemanticColors.primaryText] (or\nthe primary color when the theme has no semantic colors) for [bar].', isConst: false, isFactory: true, parameters: [ApiParameter(name: 'context', type: 'BuildContext', isRequired: true, isNamed: false, defaultValue: '', doc: '')])], properties: [ApiMember(name: 'barWidth', signature: 'static double', doc: 'The width of the bar along the leading edge.')], methods: [ApiMember(name: 'paint', signature: 'paint(Canvas canvas, Rect rect, TextDirection direction) → void', doc: 'Paints [rect] as a highlighted line on [canvas]: [tint] over the whole\nrectangle and a [barWidth] bar in [bar] on its leading side for\n[direction].')], values: []),
  'Oito2SyntaxRole': ApiEntry(kind: 'enum', package: 'oito2_ui_syntax', doc: 'A token role of a [Oito2SyntaxPalette].', signature: '', constructors: [], properties: [], methods: [ApiMember(name: 'colorIn', signature: 'colorIn(Oito2SyntaxPalette palette) → Color', doc: 'The color of this role in [palette].')], values: [ApiMember(name: 'foreground', signature: '', doc: 'Plain code text.'), ApiMember(name: 'comment', signature: '', doc: 'Comments.'), ApiMember(name: 'keyword', signature: '', doc: 'Keywords and control flow.'), ApiMember(name: 'string', signature: '', doc: 'String literals.'), ApiMember(name: 'number', signature: '', doc: 'Numeric literals.'), ApiMember(name: 'function', signature: '', doc: 'Function and method names.'), ApiMember(name: 'type', signature: '', doc: 'Type and class names.'), ApiMember(name: 'tag', signature: '', doc: 'Markup tags.'), ApiMember(name: 'attribute', signature: '', doc: 'Markup attributes, annotations and properties.'), ApiMember(name: 'constant', signature: '', doc: 'Constants, booleans and enum values.'), ApiMember(name: 'invalid', signature: '', doc: 'Invalid code and removed lines.')]),
