  'Oito2CodeEditor': ApiEntry(kind: 'class', package: 'oito2_ui_code_editor', doc: 'An editable code field with highlighting in the theme\'s\n[Oito2SyntaxPalette], line numbers, highlighted lines and line markers.\n\nBuilt on `re_editor`, whose [CodeLineEditingController] holds the text\nand selection; it brings undo and redo, indentation with Tab and\nShift+Tab, line selection, moving and deleting lines, and the usual\ncursor and selection keys. Its find, replace and save shortcuts are left\nto the app, so Ctrl+F and Ctrl+S reach the widgets around the editor.\nSince Tab indents, Ctrl+Tab and Ctrl+Shift+Tab move the focus to the\nnext and previous widgets.\n\nThe code is laid out left to right in every locale, in the bundled\nJetBrains Mono at [Oito2CodeBlock.defaultTextStyle] (scaled with the\ntext scale), and long lines scroll horizontally.\n\nWith neither [minLines] nor [maxLines], the editor fills the height its\nparent gives it, which must be bounded. Otherwise it is as tall as its\nlines, at least [minLines] and at most [maxLines], scrolling beyond\nthat.\n\n`re_editor` brings some limits. Web builds compiled with `--wasm` are\nnot supported, because one of its dependencies imports `dart:html`.\nEach editor runs highlighting, code folding and search in three\nbackground isolates on native platforms; on the web they run on the\nmain thread. The editor colors a token by the first segment of its\nscope, so a class name such as `title.class` takes the function color,\nwhile [Oito2CodeBlock] colors it by its full scope.', signature: '', constructors: [ApiConstructor(name: 'Oito2CodeEditor', doc: 'Creates a code editor.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'controller', type: 'CodeLineEditingController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The text and selection; one holding no text is created when null.\n\n[CodeLineEditingController.fromText] creates one with text, and\n[CodeLineEditingController.text] reads and replaces it.'), ApiParameter(name: 'language', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The language name or alias, such as `dart` or `gitignore`; null or an\nunregistered name shows plain text.'), ApiParameter(name: 'highlighter', type: 'Oito2Highlighter?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The highlighter whose languages [language] is looked up in; defaults\nto [Oito2Highlighter.instance].'), ApiParameter(name: 'readOnly', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the text can\'t be changed; it can still be selected and\ncopied.'), ApiParameter(name: 'showLineNumbers', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether line numbers are shown in the gutter.'), ApiParameter(name: 'highlightedLines', type: 'Set<int>', isRequired: false, isNamed: true, defaultValue: 'const {}', doc: 'The lines drawn on a tint of the primary color with a bar along their\nleading edge, counted from 1.'), ApiParameter(name: 'lineMarkers', type: 'Map<int, Oito2LineMarker>', isRequired: false, isNamed: true, defaultValue: 'const {}', doc: 'The markers shown in the gutter, by line number counted from 1.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<String>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the whole text after every change to it; selection\nchanges don\'t call it.'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node of the editor; one is created when null.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the editor takes the focus when first shown.'), ApiParameter(name: 'minLines', type: 'int?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The least number of lines the editor is tall.'), ApiParameter(name: 'maxLines', type: 'int?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The most number of lines the editor is tall before it scrolls.'), ApiParameter(name: 'semanticLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label; defaults to [Oito2Localizations.codeEditor].\n\nThe accessibility value is the code, up to its first 20 000\ncharacters, so long files don\'t slow down every edit.')])], properties: [], methods: [], values: []),
  'Oito2LineMarker': ApiEntry(kind: 'class', package: 'oito2_ui_code_editor', doc: 'A mark on a line of an [Oito2CodeEditor]: an icon in the gutter with\n[message] as its tooltip and accessibility label.', signature: '', constructors: [ApiConstructor(name: 'Oito2LineMarker', doc: 'Creates a marker of [type] with [message].', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'type', type: 'Oito2LineMarkerType', isRequired: true, isNamed: true, defaultValue: '', doc: 'The kind of the marker.'), ApiParameter(name: 'message', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The text shown as the tooltip and announced by assistive\ntechnologies.')]), ApiConstructor(name: 'Oito2LineMarker.error', doc: 'Creates an error marker with [message].', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'message', type: 'String', isRequired: true, isNamed: false, defaultValue: '', doc: 'The text shown as the tooltip and announced by assistive\ntechnologies.')]), ApiConstructor(name: 'Oito2LineMarker.warning', doc: 'Creates a warning marker with [message].', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'message', type: 'String', isRequired: true, isNamed: false, defaultValue: '', doc: 'The text shown as the tooltip and announced by assistive\ntechnologies.')]), ApiConstructor(name: 'Oito2LineMarker.info', doc: 'Creates an information marker with [message].', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'message', type: 'String', isRequired: true, isNamed: false, defaultValue: '', doc: 'The text shown as the tooltip and announced by assistive\ntechnologies.')])], properties: [], methods: [], values: []),
  'Oito2LineMarkerType': ApiEntry(kind: 'enum', package: 'oito2_ui_code_editor', doc: 'The kind of an [Oito2LineMarker], from the most to the least urgent.', signature: '', constructors: [], properties: [], methods: [], values: [ApiMember(name: 'error', signature: '', doc: 'An error.'), ApiMember(name: 'warning', signature: '', doc: 'A warning.'), ApiMember(name: 'info', signature: '', doc: 'Neutral information.')]),
