ltValue: '', doc: 'Purple.'), ApiParameter(name: 'grey0', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Grey, level 0.'), ApiParameter(name: 'grey1', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Grey, level 1.'), ApiParameter(name: 'grey2', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Grey, level 2.')])], properties: [ApiMember(name: 'dark', signature: 'static Oito2EverforestPalette', doc: 'Everforest Dark, medium contrast.'), ApiMember(name: 'light', signature: 'static Oito2EverforestPalette', doc: 'Everforest Light, medium contrast.')], methods: [], values: []),
