  'oito2QrModules': ApiEntry(kind: 'function', package: 'oito2_ui_extras', doc: 'The dark modules of the QR code of [data], as a square grid of\n[moduleCount] rows: `modules[row][column]` is true for a dark module.\n\nThrows an [ArgumentError] when [data] doesn\'t fit in a QR code at\n[errorLevel].', signature: 'oito2QrModules(String data, Oito2QrErrorLevel errorLevel) → ({int moduleCount, List<List<bool>> modules})', constructors: [], properties: [], methods: [], values: []),
  'Oito2DownloadTrigger': ApiEntry(kind: 'class', package: 'oito2_ui_files', doc: 'A button that saves a file built on demand with [Oito2Downloads].\n\nA tap awaits [data], showing a spinner, and saves the bytes as\n[fileName]. [onSaved] reports whether the file was saved, and [onError]\nreceives a failure of [data] or of saving. On platforms that can\'t\nsave files, the button is disabled and its tooltip says why.', signature: '', constructors: [ApiConstructor(name: 'Oito2DownloadTrigger', doc: 'Creates a download trigger.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'fileName', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The suggested file name.'), ApiParameter(name: 'data', type: 'Future<Uint8List> Function()', isRequired: true, isNamed: true, defaultValue: '', doc: 'Builds the file content when the button is activated.'), ApiParameter(name: 'mimeType', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The MIME type of the file, or null for a generic binary file.'), ApiParameter(name: 'label', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The button label; defaults to the localized "Download".'), ApiParameter(name: 'onSaved', type: 'ValueChanged<bool>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called after a save with whether the file was saved.'), ApiParameter(name: 'onError', type: 'void Function(Object, StackTrace)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when building or saving the file fails; without it the error\nis rethrown as an unhandled asynchronous error.'), ApiParameter(name: 'enabled', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the button can be activated.')])], properties: [], methods: [], values: []),
  'Oito2Downloads': ApiEntry(kind: 'abstract class', package: 'oito2_ui_files', doc: 'Saves bytes as a file on the device: a download on the web, the\n"Save as" dialog on Linux, Windows and macOS.', signature: '', constructors: [ApiConstructor(name: 'Oito2Downloads', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [ApiMember(name: 'isSupported', signature: 'static bool', doc: 'Whether this platform can save files: the web and desktop platforms,\nnot Android or iOS.')], methods: [ApiMember(name: 'save', signature: 'static save(String fileName, Uint8List bytes, String? mimeType) → Future<bool>', doc: 'Saves [bytes] as [fileName], typed as [mimeType] when given.\n\nReturns false when the user cancels the "Save as" dialog, and true\notherwise; a web download always returns true. Throws an\n[UnsupportedError] when not [isSupported].')], values: []),
  'Oito2FileDropTargetBuilder': ApiEntry(kind: 'typedef', package: 'oito2_ui_files', doc: 'Builds a widget that receives files dropped on [child]: [onHover]\nreports whether files are dragged over it, and [onDrop] receives the\ndropped files while [enabled].\n\nPass one to [Oito2FileDropZone.dropTargetBuilder] to receive drops from\nanother source than [oito2PlatformDropTarget].', signature: 'Widget Function({required Widget child, required bool enabled, required void Function(List<XFile>) onDrop, required void Function(bool) onHover})', constructors: [], properties: [], methods: [], values: []),
  'Oito2FileDropZone': ApiEntry(kind: 'class', package: 'oito2_ui_files', doc: 'A dashed box that opens the file chooser when activated and, where the\nplatform supports it, receives files dropped on it.\n\nThe chosen or dropped files go to [onFiles] unchecked; an\n`Oito2FileUploadController` checks them against its limits. [accept]\nfilters the file chooser. Drops come from [dropTargetBuilder], or from\n[oito2PlatformDropTarget] (the web, Linux, Windows and macOS) when it is\nnull, and pass every dropped file even when [multiple] is false.\nDropped folders are passed too, marked for `oito2IsDirectory`;\n[acceptDirectories] only changes the title to invite them.', signature: '', constructors: [ApiConstructor(name: 'Oito2FileDropZone', doc: 'Creates a file drop zone.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'onFiles', type: 'ValueChanged<List<XFile>>', isRequired: true, isNamed: true, defaultValue: '', doc: 'Receives the chosen or dropped files.'), ApiParameter(name: 'accept', type: 'List<XTypeGroup>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: 'The file types the file chooser offers; empty offers every file.'), ApiParameter(name: 'multiple', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether several files can be chosen at once in the file chooser.'), ApiParameter(name: 'enabled', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the zone opens the chooser and receives drops.'), ApiParameter(name: 'hint', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A line under the title, such as the accepted types and sizes.'), ApiParameter(name: 'dropTargetBuilder', type: 'Oito2FileDropTargetBuilder?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The source of dropped files; null uses [oito2PlatformDropTarget].'), ApiParameter(name: 'minHeight', type: 'double', isRequired: false, isNamed: true, defaultValue: '160', doc: 'The smallest height of the zone, in logical pixels.'), ApiParameter(name: 'acceptDirectories', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the title invites dropping folders as well as files.')])], properties: [], methods: [], values: []),
  'Oito2FileRejection': ApiEntry(kind: 'enum', package: 'oito2_ui_files', doc: 'Why an [Oito2FileUploadController] refused a file.', signature: '', constructors: [], properties: [], methods: [], values: [ApiMember(name: 'type', signature: '', doc: 'The file type is not one of the accepted types.'), ApiMember(name: 'size', signature: '', doc: 'The file is larger than the size limit.'), ApiMember(name: 'count', signature: '', doc: 'The upload already holds the largest number of files.'), ApiMember(name: 'directory', signature: '', doc: 'The item is a directory, not a file, and the controller doesn\'t\naccept directories.'), ApiMember(name: 'unreadable', signature: '', doc: 'The size of the file couldn\'t be read, such as when it was removed\nor its drive was unmounted after it was chosen.')]),
  'Oito2FileUpload': ApiEntry(kind: 'class', package: 'oito2_ui_files', doc: 'A file upload: an [Oito2FileDropZone] that adds files to [controller],\nthe files refused by the last addition with the reasons, and the list\nof accepted files with their size, a preview of images and a remove\nbutton.\n\nDirectories the controller accepts are listed with a folder icon and\ntheir path, or "Folder" on the web, where the path isn\'t known.\n\nThe zone hint defaults to the accepted types and the size limit of the\ncontroller; the zone is disabled once the controller holds its largest\nnumber of files.', signature: '', constructors: [ApiConstructor(name: 'Oito2FileUpload', doc: 'Creates a file upload.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'controller', type: 'Oito2FileUploadController', isRequired: true, isNamed: true, defaultValue: '', doc: 'The controller that holds the files and checks their limits.'), ApiParameter(name: 'hint', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Replaces the default zone hint, which lists the accepted types and\nthe size limit.'), ApiParameter(name: 'showPreviews', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether image files show a thumbnail.'), ApiParameter(name: 'enabled', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether files can be added and removed.'), ApiParameter(name: 'dropTargetBuilder', type: 'Oito2FileDropTargetBuilder?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The source of dropped files; see [Oito2FileDropZone.dropTargetBuilder].'), ApiParameter(name: 'zoneMinHeight', type: 'double', isRequired: false, isNamed: true, defaultValue: '160', doc: 'The smallest height of the drop zone, in logical pixels.')])], properties: [], methods: [], values: []),
  'Oito2FileUploadController': ApiEntry(kind: 'class', package: 'oito2_ui_files', doc: 'The files of a file upload, checked against the [accept]ed types,\n[maxFileSize] and [maxFiles] as they are added.\n\nDirectories dropped on an `Oito2FileDropZone` are refused unless\n[acceptDirectories] is true. Accepted directories skip the type and\nsize checks but count toward [maxFiles]; [oito2IsDirectory] tells them\nfrom files.\n\n[add] keeps the files that pass the checks and lists the others in\n[rejected], which holds the refusals of the last [add] only.', signature: '', constructors: [ApiConstructor(name: 'Oito2FileUploadController', doc: 'Creates a controller holding [files] at first, unchecked.\n\nAsserts that [maxFiles] and [maxFileSize], when given, are positive.', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'accept', type: 'List<XTypeGroup>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: 'The accepted file types; empty accepts every file.'), ApiParameter(name: 'maxFiles', type: 'int?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The largest number of files, or null for no limit.'), ApiParameter(name: 'maxFileSize', type: 'int?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The largest file size, in bytes, or null for no limit.'), ApiParameter(name: 'acceptDirectories', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether dropped directories are accepted as items, without the type\nand size checks, instead of refused.'), ApiParameter(name: 'files', type: 'Iterable<XFile>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: '')])], properties: [ApiMember(name: 'rejected', signature: 'List<Oito2RejectedFile>', doc: 'The files refused by the last [add].'), ApiMember(name: 'canAddMore', signature: 'bool', doc: 'Whether more files can be added.')], methods: [ApiMember(name: 'add', signature: 'add(Iterable<XFile> incoming) → Future<void>', doc: 'Adds the files of [incoming] that pass the checks, in order, and\nlists the others in [rejected].\n\nReading the size of each file can take a moment, so this completes\nonce every file is checked. With [maxFileSize], a file whose size\ncan\'t be read is refused as [Oito2FileRejection.unreadable]. Nothing changes when the controller is\ndisposed meanwhile. A call made before an earlier one completes waits\nfor it, so the limits hold across both.'), ApiMember(name: 'remove', signature: 'remove(XFile file) → void', doc: 'Removes [file], if the controller holds it.'), ApiMember(name: 'clear', signature: 'clear() → void', doc: 'Removes every file and refusal.'), ApiMember(name: 'clearRejected', signature: 'clearRejected() → void', doc: 'Forgets the refusals of the last [add].')], values: []),
  'Oito2RejectedFile': ApiEntry(kind: 'class', package: 'oito2_ui_files', doc: 'A file an [Oito2FileUploadController] refused, with the reason.', signature: '', constructors: [ApiConstructor(name: 'Oito2RejectedFile', doc: 'Creates a record of [file] refused for [reason].', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'file', type: 'XFile', isRequired: true, isNamed: false, defaultValue: '', doc: 'The refused file.'), ApiParameter(name: 'reason', type: 'Oito2FileRejection', isRequired: true, isNamed: false, defaultValue: '', doc: 'Why it was refused.')])], properties: [], methods: [], values: []),
  'oito2CanDropFiles': ApiEntry(kind: 'getter', package: 'oito2_ui_files', doc: 'Whether [oito2PlatformDropTarget] receives dropped files on this\nplatform: true on the web, Linux, Windows and macOS.', signature: 'bool', constructors: [], properties: [], methods: [], values: []),
  'oito2FileMatchesTypes': ApiEntry(kind: 'function', package: 'oito2_ui_files', doc: 'Whether [file] is one of the [accept]ed types.\n\nA type group matches when the file name ends with one of its\n`extensions` (ignoring case and a leading dot), or when the file\'s MIME\ntype is one of its `mimeTypes` or `webWildCards`, where `image/*`\nmatches every image type. No groups, or a group with none of those\nlists, accept every file.', signature: 'oito2FileMatchesTypes(XFile file, List<XTypeGroup> accept) → bool', constructors: [], properties: [], methods: [], values: []),
  'oito2IsDirectory': ApiEntry(kind: 'function', package: 'oito2_ui_files', doc: 'Whether [file] stands for a directory rather than a file, as marked by\n[oito2MarkAsDirectory].\n\nOn Linux, Windows and macOS, the `path` of a dropped directory is its\npath in the file system. On the web the browser gives only its `name`,\nand its `path` is not a file system path.', signature: 'oito2IsDirectory(XFile file) → bool', constructors: [], properties: [], methods: [], values: []),
  'oito2MarkAsDirectory': ApiEntry(kind: 'function', package: 'oito2_ui_files', doc: 'Records that [file] stands for a directory and returns [file].\n\n[oito2PlatformDropTarget] marks the directories it receives; a custom\n`Oito2FileDropTargetBuilder` can mark its own the same way.', signature: 'oito2MarkAsDirectory(XFile file) → XFile', constructors: [], properties: [], methods: [], values: []),
  'oito2PlatformDropTarget': ApiEntry(kind: 'function', package: 'oito2_ui_files', doc: 'The drop target of the platform: files dragged from the desktop onto\n[child], received through the browser on the web and through the\ndesktop_drop plugin on Linux, Windows and macOS; elsewhere, [child]\nalone, without drops.\n\nDropped directories are handed over with the files, marked as such for\n`oito2IsDirectory`: with their file system path on the desktop and\nwith their name only on the web. An `Oito2FileUploadController`\nrefuses them unless it accepts directories.', signature: 'oito2PlatformDropTarget(Widget child, bool enabled, ValueChanged<bool> onHover, ValueChanged<List<XFile>> onDrop) → Widget', constructors: [], properties: [], methods: [], values: []),
